CREATE OR REPLACE FUNCTION public.kinto_deals_v1_admin_decide_g3(p_session_token text, p_submission_id uuid, p_expected_revision integer, p_decision text, p_rejection_reason text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_admin text; v_s public.kinto_deals_v1_submissions%rowtype;
v_c public.kinto_deals_v1_campaigns%rowtype; v_reason text;
begin
v_admin:=private.require_admin_session_v147(p_session_token);
if nullif(btrim(v_admin),'') is null then raise exception 'DEALS_ADMIN_SESSION_REQUIRED' using errcode='28000'; end if;
if p_decision not in ('approved','rejected') or p_decision is null then
raise exception 'DEALS_INVALID_DECISION' using errcode='22023'; end if;
v_reason:=nullif(btrim(coalesce(p_rejection_reason,'')),'');
if p_decision='rejected' and (v_reason is null or char_length(v_reason) not between 3 and 1000) then
raise exception 'DEALS_REJECTION_REASON_REQUIRED' using errcode='22023'; end if;
if p_decision='approved' and v_reason is not null then
raise exception 'DEALS_APPROVAL_HAS_NO_REJECTION_REASON' using errcode='22023'; end if;
select * into v_s from public.kinto_deals_v1_submissions where id=p_submission_id for update;
if not found then raise exception 'DEALS_SUBMISSION_NOT_FOUND' using errcode='P0002'; end if;
if v_s.review_state<>'pending' or v_s.revision is distinct from p_expected_revision then
raise exception 'DEALS_STALE_OR_ALREADY_REVIEWED' using errcode='40001'; end if;
select * into v_c from public.kinto_deals_v1_campaigns where id=v_s.campaign_id for update;
if not found or v_c.store_id<>v_s.store_id or v_c.status<>'submitted' then
raise exception 'DEALS_CAMPAIGN_NOT_SUBMITTED' using errcode='40001'; end if;
if p_decision='approved' and v_c.ends_at<=clock_timestamp() then
raise exception 'DEALS_CAMPAIGN_PERIOD_ENDED' using errcode='22023'; end if;
if exists(select 1 from public.kinto_deals_v1_submissions s2
where s2.campaign_id=v_s.campaign_id and s2.id<>v_s.id
and s2.submitted_at>v_s.submitted_at) then
raise exception 'DEALS_SUPERSEDED_SUBMISSION' using errcode='40001'; end if;
update public.kinto_deals_v1_submissions
set review_state=case when p_decision='approved' then 'acknowledged' else 'rejected' end,
reviewed_at=clock_timestamp(),reviewed_by=v_admin,rejection_reason=v_reason
where id=v_s.id;
-- Keep approved campaign as submitted; approved_scheduled is DERIVED by
-- review_state + server time. G4 alone may enable approved-only storefront.
if p_decision='rejected' then
update public.kinto_deals_v1_campaigns set status='rejected',updated_at=clock_timestamp()
where id=v_c.id;
end if;
insert into public.kinto_deals_v1_review_events
(submission_id,campaign_id,store_id,revision,decision,reason,reviewer_id)
values(v_s.id,v_s.campaign_id,v_s.store_id,v_s.revision,p_decision,v_reason,v_admin);
return jsonb_build_object('ok',true,'submission_id',v_s.id,'campaign_id',v_s.campaign_id,
'decision',p_decision,'decision_event_recorded',true,'merchant_push_sent',false,'customer_broadcast_sent',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.login_role_resolver_v296(p_identity text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
v_identity text := lower(trim(coalesce(p_identity, '')));
v_role text;
v_matches integer := 0;
v_employee_role text;
begin
if v_identity = '' then
return jsonb_build_object('ok', false, 'error', 'LOGIN_IDENTITY_REQUIRED');
end if;

select lower(trim(coalesce(e.role, '')))
into v_employee_role
from public.employees e
where lower(trim(coalesce(e.phone, ''))) = v_identity
limit 1;

if v_employee_role is not null then
v_matches := v_matches + 1;

if v_employee_role in ('admin', 'أدمن', 'ادمن') then
v_role := 'admin';
elsif v_employee_role in ('employee', 'موظف') then
v_role := 'employee';
else
return jsonb_build_object(
'ok', false,
'error', 'LOGIN_ROLE_UNSUPPORTED'
);
end if;
end if;

if exists (
select 1
from public.branches b
where lower(trim(coalesce(b.phone, ''))) = v_identity
) then
v_matches := v_matches + 1;
v_role := coalesce(v_role, 'branch');
end if;

if exists (
select 1
from public.couriers c
where lower(trim(coalesce(c.phone, ''))) = v_identity
) then
v_matches := v_matches + 1;
v_role := coalesce(v_role, 'courier');
end if;

if exists (
select 1
from public.customers c
where lower(trim(coalesce(c.phone, ''))) = v_identity
or lower(trim(coalesce(c.code, ''))) = v_identity
or lower(trim(coalesce(c.email, ''))) = v_identity
) then
v_matches := v_matches + 1;
v_role := coalesce(v_role, 'customer');
end if;

if exists (
select 1
from public.local_stores s
where lower(trim(coalesce(s.phone, ''))) = v_identity
or lower(trim(coalesce(s.username, ''))) = v_identity
) then
v_matches := v_matches + 1;
v_role := coalesce(v_role, 'vendor');
end if;

if v_matches = 0 then
return jsonb_build_object(
'ok', false,
'error', 'LOGIN_IDENTITY_NOT_FOUND'
);
end if;

if v_matches > 1 then
return jsonb_build_object(
'ok', false,
'error', 'LOGIN_IDENTITY_AMBIGUOUS'
);
end if;

return jsonb_build_object(
'ok', true,
'role', v_role
);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_admin_inbox_g3(p_session_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_admin text; v_items jsonb; v_count bigint;
begin
v_admin:=private.require_admin_session_v147(p_session_token);
if nullif(btrim(v_admin),'') is null then raise exception 'DEALS_ADMIN_SESSION_REQUIRED' using errcode='28000'; end if;
select count(*) into v_count from public.kinto_deals_v1_submissions where review_state='pending';
select coalesce(jsonb_agg(to_jsonb(q) order by q.submitted_at desc),'[]'::jsonb) into v_items
from (
select s.id as submission_id,s.campaign_id,s.store_id,s.title_snapshot,
s.summary_snapshot,s.submitted_at,s.revision,c.kind,c.starts_at,c.ends_at,
c.max_total_redemptions,c.max_uses_per_customer,c.gift_product_id
from public.kinto_deals_v1_submissions s
join public.kinto_deals_v1_campaigns c on c.id=s.campaign_id and c.store_id=s.store_id
where s.review_state='pending' order by s.submitted_at desc limit 100
) q;
return jsonb_build_object('pending_count',v_count,'items',v_items);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_attach_ad_g13(p_session_token text, p_campaign_id uuid, p_object_path text, p_byte_size integer, p_width integer, p_height integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$

declare
v_drafts jsonb;
v_old text;
v_status text;

begin
if p_campaign_id is null
or p_object_path is null
or p_byte_size not between 32 and 204800
or p_width not between 1 and 1200
or p_height not between 1 and 1200
or p_object_path !~ (
'^' || p_campaign_id::text ||
'/[0-9a-f-]{36}[.]webp$'
)
then
raise exception 'G13_INVALID_AD_METADATA'
using errcode = '22023';
end if;

-- Verify merchant session and campaign ownership
v_drafts := public.kinto_deals_v1_vendor_drafts_g4(
p_session_token,
p_campaign_id,
1
);

if jsonb_array_length(
coalesce(v_drafts->'items', '[]'::jsonb)
) <> 1
or v_drafts#>>'{items,0,id}' <> p_campaign_id::text
then
raise exception 'G13_DRAFT_NOT_OWNED'
using errcode = '28000';
end if;

select status into v_status
from public.kinto_deals_v1_campaigns
where id = p_campaign_id
for update;

if v_status is distinct from 'draft' then
raise exception 'G13_DRAFT_LOCKED'
using errcode = '55000';
end if;

-- Verify that the image exists in the dedicated private bucket
if not exists (
select 1
from storage.objects
where bucket_id = 'kinto-merchant-campaign-ads'
and name = p_object_path
) then
raise exception 'G13_OBJECT_MISSING'
using errcode = 'P0002';
end if;

select object_path into v_old
from public.kinto_deals_v1_ad_assets_g13
where campaign_id = p_campaign_id
for update;

insert into public.kinto_deals_v1_ad_assets_g13 (
campaign_id, object_path, byte_size, width, height
)
values (
p_campaign_id, p_object_path,
p_byte_size, p_width, p_height
)
on conflict (campaign_id)
do update set
object_path = excluded.object_path,
byte_size = excluded.byte_size,
width = excluded.width,
height = excluded.height,
updated_at = now();

-- Queue the previous image for secure cleanup
if v_old is not null and v_old <> p_object_path then
insert into public.kinto_deals_v1_ad_cleanup_g13 (
object_path, campaign_id
)
values (v_old, p_campaign_id)
on conflict (object_path) do nothing;
end if;

return jsonb_build_object(
'ok', true,
'campaign_id', p_campaign_id
);

end;
$function$

CREATE OR REPLACE FUNCTION public.list_featured_merchants_session_v1(p_session_token text)
RETURNS TABLE(id uuid, email text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE v_admin uuid;
BEGIN
v_admin := (private.require_admin_session_v147(p_session_token))::uuid;

IF NOT public.meshwar_is_admin(v_admin) THEN
RAISE EXCEPTION 'ADMIN_ROLE_REQUIRED' USING ERRCODE='42501';
END IF;

RETURN QUERY
SELECT * FROM public.list_featured_merchants(v_admin);
END $function$

CREATE OR REPLACE FUNCTION public.login_role_resolver_v299(p_identity text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
v_identity text := lower(trim(coalesce(p_identity, '')));
v_roles text[] := array[]::text[];
begin
if v_identity = '' then
return jsonb_build_object(
'ok', false,
'error', 'LOGIN_IDENTITY_REQUIRED'
);
end if;

-- Admin
if exists (
select 1
from public.employees e
where lower(trim(coalesce(e.phone, ''))) = v_identity
and lower(trim(coalesce(e.role, '')))
in ('admin', 'أدمن', 'ادمن')
) then
v_roles := array_append(v_roles, 'admin');
end if;

-- Employee
if exists (
select 1
from public.employees e
where lower(trim(coalesce(e.phone, ''))) = v_identity
and lower(trim(coalesce(e.role, '')))
in ('employee', 'موظف')
) then
v_roles := array_append(v_roles, 'employee');
end if;

-- أي صفة غير معروفة داخل جدول الموظفين
if exists (
select 1
from public.employees e
where lower(trim(coalesce(e.phone, ''))) = v_identity
and lower(trim(coalesce(e.role, '')))
not in (
'admin', 'أدمن', 'ادمن',
'employee', 'موظف'
)
) then
return jsonb_build_object(
'ok', false,
'error', 'LOGIN_ROLE_UNSUPPORTED'
);
end if;

-- Branch
if exists (
select 1
from public.branches b
where lower(trim(coalesce(b.phone, ''))) = v_identity
) then
v_roles := array_append(v_roles, 'branch');
end if;

-- Courier
if exists (
select 1
from public.couriers c
where lower(trim(coalesce(c.phone, ''))) = v_identity
) then
v_roles := array_append(v_roles, 'courier');
end if;

-- Customer
if exists (
select 1
from public.customers c
where lower(trim(coalesce(c.phone, ''))) = v_identity
or lower(trim(coalesce(c.code, ''))) = v_identity
or lower(trim(coalesce(c.email, ''))) = v_identity
) then
v_roles := array_append(v_roles, 'customer');
end if;

-- Vendor
if exists (
select 1
from public.local_stores s
where lower(trim(coalesce(s.phone, ''))) = v_identity
or lower(trim(coalesce(s.username, ''))) = v_identity
) then
v_roles := array_append(v_roles, 'vendor');
end if;

if cardinality(v_roles) = 0 then
return jsonb_build_object(
'ok', false,
'error', 'LOGIN_IDENTITY_NOT_FOUND'
);
end if;

if cardinality(v_roles) = 1 then
return jsonb_build_object(
'ok', true,
'role', v_roles[1],
'roles', to_jsonb(v_roles)
);
end if;

return jsonb_build_object(
'ok', true,
'roles', to_jsonb(v_roles),
'requires_role_choice', true
);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_account_v300(p_admin_session_token text, p_account_type text, p_account_id text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_password text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_permissions jsonb DEFAULT NULL::jsonb, p_branch_id text DEFAULT NULL::text, p_delivery_fee numeric DEFAULT NULL::numeric, p_email text DEFAULT NULL::text, p_code text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_secondary_phone text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_admin jsonb;
v_type text := lower(trim(coalesce(p_account_type,'')));
v_id text := nullif(trim(coalesce(p_account_id,'')),'');
v_phone text := lower(trim(coalesce(p_phone,'')));
v_role text;
begin
select public.admin_session_identity_v147(p_admin_session_token)
into v_admin;

if not coalesce((v_admin->>'ok')::boolean,false)
or lower(trim(coalesce(v_admin->'admin'->>'role','')))
not in ('admin','أدمن','ادمن') then
return jsonb_build_object(
'ok',false,
'error','ADMIN_SESSION_INVALID'
);
end if;

if v_phone = '' then
return jsonb_build_object(
'ok',false,
'error','ACCOUNT_FIELDS_REQUIRED'
);
end if;

if v_type in ('employee','admin') then

v_role := case
when v_type='admin' then 'admin'
else coalesce(nullif(lower(trim(p_role)),''),'employee')
end;

if exists (
select 1
from public.employees e
where lower(trim(coalesce(e.phone,''))) = v_phone
and lower(trim(coalesce(e.role,''))) = v_role
and (v_id is null or e.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

elsif v_type='courier' then

if exists (
select 1
from public.couriers c
where lower(trim(coalesce(c.phone,''))) = v_phone
and (v_id is null or c.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

elsif v_type='branch' then

if exists (
select 1
from public.branches b
where lower(trim(coalesce(b.phone,''))) = v_phone
and (v_id is null or b.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

elsif v_type='customer' then

if exists (
select 1
from public.customers c
where lower(trim(coalesce(c.phone,''))) = v_phone
and (v_id is null or c.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

else
return jsonb_build_object(
'ok',false,
'error','ACCOUNT_TYPE_INVALID'
);
end if;

return public.admin_save_account_v297(
p_admin_session_token,
p_account_type,
p_account_id,
p_name,
p_phone,
p_password,
p_role,
p_permissions,
p_branch_id,
p_delivery_fee,
p_email,
p_code,
p_country,
p_state,
p_address,
p_secondary_phone
);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_public_ad_path_g13(p_campaign_id uuid)
RETURNS text
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$

declare
v_store_id uuid;
v_path text;

begin
select
c.store_id,
a.object_path
into
v_store_id,
v_path
from public.kinto_deals_v1_campaigns c
join public.kinto_deals_v1_ad_assets_g13 a
on a.campaign_id = c.id
where c.id = p_campaign_id;

if v_path is null then
return null;
end if;

-- Reuse the existing approved and published campaign feed
if exists (
select 1
from public.kinto_deals_v1_public_feed_g7(v_store_id) as f
where f.campaign_id = p_campaign_id
) then
return v_path;
end if;

return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.branch_save_courier_v304(p_branch_session_token text, p_courier_id text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_password text DEFAULT NULL::text, p_delivery_fee numeric DEFAULT NULL::numeric)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_branch_id text;
v_id text := nullif(trim(coalesce(p_courier_id,'')),'');
v_name text := trim(coalesce(p_name,''));
v_phone text := trim(coalesce(p_phone,''));
v_password text := coalesce(p_password,'');
v_hash text;
v_saved_id text;
begin
v_branch_id := private.require_branch_session_v148(p_branch_session_token);

if v_name = '' or v_phone = '' then
return jsonb_build_object('ok',false,'error','ACCOUNT_FIELDS_REQUIRED');
end if;

if v_id is null and v_password = '' then
return jsonb_build_object('ok',false,'error','PASSWORD_REQUIRED');
end if;

if v_password <> '' and length(v_password) < 8 then
return jsonb_build_object('ok',false,'error','PASSWORD_TOO_SHORT');
end if;

if exists (
select 1
from public.couriers c
where trim(coalesce(c.phone,'')) = v_phone
and (v_id is null or c.id::text <> v_id)
) then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end if;

if v_password <> '' then
v_hash := crypt(v_password, gen_salt('bf'));
end if;

if v_id is null then
insert into public.couriers(
branch_id,
name,
phone,
password,
delivery_fee,
is_active
)
values(
v_branch_id,
v_name,
v_phone,
v_hash,
p_delivery_fee,
true
)
returning id::text into v_saved_id;

else
update public.couriers
set
name = v_name,
phone = v_phone,
delivery_fee = p_delivery_fee,
password = case
when v_hash is null then password
else v_hash
end
where id::text = v_id
and branch_id::text = v_branch_id
returning id::text into v_saved_id;
end if;

if v_saved_id is null then
return jsonb_build_object(
'ok',false,
'error','COURIER_NOT_FOUND_OR_NOT_OWNED'
);
end if;

return jsonb_build_object(
'ok',true,
'id',v_saved_id
);

exception
when unique_violation then
return jsonb_build_object(
'ok',false,
'error','SAME_ROLE_PHONE_EXISTS'
);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_account_v307(p_admin_session_token text, p_account_type text, p_account_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_admin_id text;
v_rows integer;
begin
v_admin_id := private.require_admin_session_v147(p_admin_session_token);

if p_account_type in ('employee','admin') then
if p_account_id = v_admin_id then
return jsonb_build_object('ok',false,'error','CANNOT_DELETE_CURRENT_ADMIN');
end if;

delete from public.employees
where id::text = p_account_id;

elsif p_account_type = 'customer' then
delete from public.customers
where id::text = p_account_id;

else
return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACCOUNT_TYPE');
end if;

get diagnostics v_rows = row_count;

if v_rows = 0 then
return jsonb_build_object('ok',false,'error','ACCOUNT_NOT_FOUND');
end if;

return jsonb_build_object('ok',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_courier_action_v308(p_admin_session_token text, p_courier_id text, p_action text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_admin_id text;
v_action text := lower(trim(coalesce(p_action,'')));
v_linked boolean;
begin
v_admin_id := private.require_admin_session_v147(p_admin_session_token);

if coalesce(v_admin_id,'') = '' then
return jsonb_build_object('ok',false,'error','INVALID_ADMIN_SESSION');
end if;

if v_action = 'toggle' then
update public.couriers
set is_active = not coalesce(is_active,true)
where id::text = p_courier_id;

if not found then
return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND');
end if;

return jsonb_build_object('ok',true,'result','TOGGLED');

elsif v_action = 'delete' then
select exists(
select 1 from public.orders
where courier_id::text = p_courier_id
limit 1
) into v_linked;

if v_linked then
update public.couriers
set is_active = false
where id::text = p_courier_id;
else
delete from public.couriers
where id::text = p_courier_id;
end if;

if not found then
return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND');
end if;

return jsonb_build_object(
'ok',true,
'result',
case when v_linked then 'DISABLED_LINKED' else 'DELETED' end
);
end if;

return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACTION');
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_save_draft_g4(p_session_token text, p_campaign_id uuid, p_expected_updated_at timestamp with time zone, p_draft jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store uuid; v_c public.kinto_deals_v1_campaigns%rowtype;
v_id uuid; v_kind text; v_title text; v_description text;
v_start timestamptz; v_end timestamptz; v_threshold integer;
v_gift uuid; v_gift_options jsonb; v_terms jsonb; v_ids uuid[];
v_uses integer; v_units integer; v_total integer; v_now timestamptz;
begin
v_store:=private.require_vendor_session(p_session_token);
if v_store is null then raise exception 'DEALS_VENDOR_SESSION_REQUIRED' using errcode='28000'; end if;
if p_draft is null or jsonb_typeof(p_draft)<>'object' then
raise exception 'DEALS_INVALID_DRAFT' using errcode='22023'; end if;
if exists(select 1 from jsonb_object_keys(p_draft) k
where k not in ('title','description','kind','starts_at','ends_at','threshold_units',
'gift_product_id','gift_selected_options','max_uses_per_customer',
'max_units_per_customer','max_total_redemptions','terms_snapshot','product_ids')) then
raise exception 'DEALS_UNKNOWN_DRAFT_FIELD' using errcode='22023'; end if;
v_kind:=p_draft->>'kind';v_title:=btrim(coalesce(p_draft->>'title',''));
v_description:=btrim(coalesce(p_draft->>'description',''));
if v_kind is null or v_kind not in ('choose_n','buy_n','limited_purchase')
or char_length(v_title) not between 2 and 160 or char_length(v_description)>2000 then
raise exception 'DEALS_INVALID_TITLE_OR_KIND' using errcode='22023'; end if;
begin
v_start:=(p_draft->>'starts_at')::timestamptz;
v_end:=(p_draft->>'ends_at')::timestamptz;
v_threshold:=(p_draft->>'threshold_units')::integer;
v_gift:=(p_draft->>'gift_product_id')::uuid;
v_uses:=coalesce((p_draft->>'max_uses_per_customer')::integer,1);
v_units:=(p_draft->>'max_units_per_customer')::integer;
v_total:=(p_draft->>'max_total_redemptions')::integer;
exception when invalid_text_representation or datetime_field_overflow or numeric_value_out_of_range then
raise exception 'DEALS_INVALID_DRAFT_FIELD_TYPE' using errcode='22023';
end;
if v_start is null or v_end is null or v_end<=v_start
or v_end<=clock_timestamp() or v_end>v_start+interval '366 days'
or v_uses not between 1 and 100
or (v_units is not null and v_units not between 1 and 1000)
or (v_total is not null and v_total not between 1 and 1000000) then
raise exception 'DEALS_INVALID_PERIOD_OR_LIMITS' using errcode='22023'; end if;
if (v_kind='limited_purchase' and (v_threshold is not null or v_gift is not null or v_units is null))
or (v_kind in ('choose_n','buy_n') and (v_threshold is null or v_threshold not between 1 and 100)) then
raise exception 'DEALS_INVALID_KIND_RULES' using errcode='22023'; end if;
v_gift_options:=coalesce(p_draft->'gift_selected_options','{}'::jsonb);
v_terms:=coalesce(p_draft->'terms_snapshot','{}'::jsonb);
if jsonb_typeof(v_gift_options)<>'object' or jsonb_typeof(v_terms)<>'object'
or length(v_terms::text)>12000 or length(v_gift_options::text)>3000 then
raise exception 'DEALS_INVALID_OPTIONS_OR_TERMS' using errcode='22023'; end if;
if jsonb_typeof(p_draft->'product_ids') is distinct from 'array'
or jsonb_array_length(p_draft->'product_ids') not between 1 and 50 then
raise exception 'DEALS_PRODUCT_LIST_REQUIRED' using errcode='22023'; end if;
if exists(select 1 from jsonb_array_elements(p_draft->'product_ids') x where jsonb_typeof(x)<>'string') then
raise exception 'DEALS_PRODUCT_ID_TYPE' using errcode='22023'; end if;
begin
select array_agg(x.value::uuid) into v_ids from jsonb_array_elements_text(p_draft->'product_ids') x(value);
exception when invalid_text_representation then
raise exception 'DEALS_INVALID_PRODUCT_UUID' using errcode='22023';
end;
if (select count(distinct id) from unnest(v_ids) id)<>cardinality(v_ids)
or (select count(*) from public.local_products p where p.id=any(v_ids) and p.store_id=v_store)<>cardinality(v_ids)
or (v_gift is not null and not exists(select 1 from public.local_products p where p.id=v_gift and p.store_id=v_store))
or (v_gift is not null and v_gift=any(v_ids)) then
raise exception 'DEALS_PRODUCT_OR_GIFT_OWNERSHIP' using errcode='23514'; end if;
if v_kind='choose_n' and v_threshold>cardinality(v_ids) then
raise exception 'DEALS_CHOOSE_N_EXCEEDS_PRODUCTS' using errcode='22023'; end if;
v_now:=clock_timestamp();
if p_campaign_id is null then
if p_expected_updated_at is not null then raise exception 'DEALS_NEW_DRAFT_VERSION_MUST_BE_NULL' using errcode='40001'; end if;
insert into public.kinto_deals_v1_campaigns
(store_id,title,description,kind,status,starts_at,ends_at,threshold_units,gift_product_id,
gift_selected_options,max_uses_per_customer,max_units_per_customer,max_total_redemptions,terms_snapshot)
values(v_store,v_title,v_description,v_kind,'draft',v_start,v_end,v_threshold,v_gift,
v_gift_options,v_uses,v_units,v_total,v_terms) returning id,updated_at into v_id,v_now;
else
select * into v_c from public.kinto_deals_v1_campaigns
where id=p_campaign_id and store_id=v_store for update;
if not found then raise exception 'DEALS_DRAFT_NOT_FOUND' using errcode='P0002'; end if;
if v_c.status<>'draft' or exists(select 1 from public.kinto_deals_v1_submissions where campaign_id=v_c.id) then
raise exception 'DEALS_REVIEWED_OR_SUBMITTED_DRAFT_LOCKED' using errcode='40001'; end if;
if v_c.updated_at is distinct from p_expected_updated_at then
raise exception 'DEALS_DRAFT_VERSION_CONFLICT' using errcode='40001'; end if;
update public.kinto_deals_v1_campaigns set title=v_title,description=v_description,
kind=v_kind,starts_at=v_start,ends_at=v_end,threshold_units=v_threshold,
gift_product_id=v_gift,gift_selected_options=v_gift_options,
max_uses_per_customer=v_uses,max_units_per_customer=v_units,
max_total_redemptions=v_total,terms_snapshot=v_terms,
updated_at=greatest(clock_timestamp(),v_c.updated_at+interval '1 microsecond')
where id=v_c.id returning id,updated_at into v_id,v_now;
delete from public.kinto_deals_v1_products where campaign_id=v_id;
end if;
insert into public.kinto_deals_v1_products(campaign_id,product_id)
select v_id,id from unnest(v_ids) id;
return jsonb_build_object('ok',true,'campaign_id',v_id,'status','draft',
'updated_at',v_now,'product_count',cardinality(v_ids),'submitted',false,'published',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reject_featured_request_session_v1(p_session_token text, p_request_id uuid, p_admin_note text DEFAULT NULL::text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE v_admin uuid;
BEGIN
v_admin := (private.require_admin_session_v147(p_session_token))::uuid;

IF NOT public.meshwar_is_admin(v_admin) THEN
RAISE EXCEPTION 'ADMIN_ROLE_REQUIRED' USING ERRCODE='42501';
END IF;

RETURN public.admin_reject_featured_request(
v_admin,
p_request_id,
p_admin_note
);
END $function$

