CREATE OR REPLACE FUNCTION public.branch_courier_action_v308(p_branch_session_token text, p_courier_id text, p_action text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_branch_id text;
v_action text := lower(trim(coalesce(p_action,'')));
v_linked boolean;
begin
v_branch_id := private.require_branch_session_v148(p_branch_session_token);

if coalesce(v_branch_id,'') = '' then
return jsonb_build_object('ok',false,'error','INVALID_BRANCH_SESSION');
end if;

if not exists(
select 1 from public.couriers
where id::text = p_courier_id
and branch_id::text = v_branch_id
) then
return jsonb_build_object('ok',false,'error','COURIER_NOT_FOUND_OR_NOT_OWNED');
end if;

if v_action = 'toggle' then
update public.couriers
set is_active = not coalesce(is_active,true)
where id::text = p_courier_id
and branch_id::text = v_branch_id;

return jsonb_build_object('ok',true,'result','TOGGLED');

elsif v_action = 'delete' then
select exists(
select 1 from public.orders
where courier_id::text = p_courier_id
limit 1
) into v_linked;

if v_linked then
update public.couriers
set is_active = false
where id::text = p_courier_id
and branch_id::text = v_branch_id;
else
delete from public.couriers
where id::text = p_courier_id
and branch_id::text = v_branch_id;
end if;

return jsonb_build_object(
'ok',true,
'result',
case when v_linked then 'DISABLED_LINKED' else 'DELETED' end
);
end if;

return jsonb_build_object('ok',false,'error','UNSUPPORTED_ACTION');
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_confirm_order_receipt_v60(p_session_token text, p_order_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
v_confirmed_at timestamptz;
begin
v_customer_id := private.require_customer_review_session(p_session_token);

if not exists (
select 1 from public.orders o
where o.id = p_order_id
and o.customer_id::text = v_customer_id::text
and o.status = 'تم التسليم'
) then
raise exception 'V60_DELIVERED_ORDER_NOT_FOUND';
end if;

insert into public.order_customer_receipts_v60(order_id, customer_id)
values (p_order_id, v_customer_id::text)
on conflict (order_id) do nothing;

select confirmed_at into v_confirmed_at
from public.order_customer_receipts_v60
where order_id = p_order_id and customer_id = v_customer_id::text;

return jsonb_build_object('confirmed', true, 'confirmed_at', v_confirmed_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_draft_options_g20(p_session_token text, p_campaign_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
