CREATE OR REPLACE FUNCTION public.kinto_normalize_currency_v310(v text)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare c text;
begin
c:=upper(trim(coalesce(nullif(v,''),'IQD')));

if c in('$','US$') then
c:='USD';
end if;

if c in('TL','₺') then
c:='TRY';
end if;

return c;
end $function$

CREATE OR REPLACE FUNCTION public.kinto_order_store_id_v310(o orders)
RETURNS text
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
d jsonb;
sid text;
multi_store_text text;
begin
d:=case
when jsonb_typeof(o.details::jsonb)='object'
then o.details::jsonb
else '{}'::jsonb
end;

multi_store_text:=
lower(trim(coalesce(d->>'multi_store','')));

if multi_store_text in('true','t','1','yes','y','on') then
return null;
end if;

sid:=nullif(trim(coalesce(d->>'store_id','')),'');

if sid is not null
and (
coalesce(d->>'source','')<>'local_cart_bundle'
or coalesce(d->>'checkout_contract','')
='independent_vendor_orders'
)
then
return sid;
end if;

return null;

exception when others then
return null;
end
$function$

CREATE OR REPLACE FUNCTION public.meshwar_assign_local_cart_order_code()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
declare
next_val bigint;
formatted_code text;
begin
-- Get next sequence value (fixing the sequence name to match the canonical one)
next_val := nextval('public.kinto_local_cart_order_code_seq');

-- Format as KN-000001
formatted_code := 'KN-' || lpad(next_val::text, 6, '0');

-- Assign to order_code safely
NEW.order_code := formatted_code;

-- Safely sync with details jsonb if bundle_id exists or needs setting
if NEW.details is not null then
NEW.details := jsonb_set(NEW.details::jsonb, '{bundle_id}', to_jsonb(formatted_code), true);
end if;

return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_staff_directory_session_v1(p_role text, p_session_token text, p_table text, p_filters jsonb DEFAULT '[]'::jsonb, p_order text DEFAULT 'id'::text, p_ascending boolean DEFAULT true, p_limit integer DEFAULT 2000)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; actor_id text; scope_sql text:='true'; filter_sql text:='';
columns_allowed text[]; f jsonb; field_name text; operator_name text; order_name text;
BEGIN
actor:=private.kinto_staff_actor_v1(p_role,p_session_token); actor_id:=actor->>'id';
IF p_table NOT IN ('employees','branches','couriers') OR p_table IS NULL THEN
RAISE EXCEPTION 'DIRECTORY_TABLE_NOT_ALLOWED' USING ERRCODE='42501';
END IF;
IF p_role='employee' AND p_table<>'employees'
AND actor->'permissions'->>'orders'='false' AND actor->'permissions'->>'branches'='false' THEN
RAISE EXCEPTION 'DIRECTORY_PERMISSION_REQUIRED' USING ERRCODE='42501';
END IF;
IF p_table='employees' THEN
IF p_role NOT IN ('admin','employee') THEN RAISE EXCEPTION 'DIRECTORY_ROLE_DENIED' USING ERRCODE='42501'; END IF;
IF p_role='employee' THEN scope_sql:=format('t.id::text=%L',actor_id); END IF;
columns_allowed:=ARRAY['id','created_at','name','phone','role','branch','status','is_active','permissions'];
ELSIF p_table='branches' THEN
IF p_role='branch' THEN scope_sql:=format('t.id::text=%L',actor_id);
ELSIF p_role='courier' THEN scope_sql:=format('t.id::text=%L',actor->>'branch_id'); END IF;
-- Legacy opaque payload is intentionally excluded; no credential-bearing JSON.
columns_allowed:=ARRAY['id','name','phone','status','created_at','updated_at','address'];
ELSE
IF p_role='branch' THEN scope_sql:=format('t.branch_id::text=%L',actor_id);
ELSIF p_role='courier' THEN scope_sql:=format('t.id::text=%L',actor_id); END IF;
columns_allowed:=ARRAY['id','courier_uuid','branch_id','name','phone','delivery_fee','is_active','created_at'];
END IF;
IF jsonb_typeof(p_filters) IS DISTINCT FROM 'array' OR jsonb_array_length(p_filters)>20 THEN
RAISE EXCEPTION 'DIRECTORY_FILTER_INVALID' USING ERRCODE='22023';
END IF;
FOR f IN SELECT value FROM jsonb_array_elements(p_filters) LOOP
field_name:=f->>'field'; operator_name:=f->>'op';
IF field_name IS NULL OR NOT field_name=ANY(columns_allowed) OR field_name NOT IN ('id','branch_id','phone') THEN
RAISE EXCEPTION 'DIRECTORY_FILTER_INVALID' USING ERRCODE='22023';
END IF;
IF operator_name IN ('eq','neq') AND jsonb_typeof(f->'value') IN ('string','number') THEN
filter_sql:=filter_sql||format(' AND (to_jsonb(t)->>%L) %s %L',field_name,CASE WHEN operator_name='eq' THEN '=' ELSE '<>' END,f->>'value');
ELSIF operator_name='in' AND jsonb_typeof(f->'value')='array' AND jsonb_array_length(f->'value')<=2000 THEN
filter_sql:=filter_sql||format(' AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(%L::jsonb) x(value) WHERE x.value=to_jsonb(t)->>%L)',f->'value',field_name);
ELSE RAISE EXCEPTION 'DIRECTORY_FILTER_INVALID' USING ERRCODE='22023'; END IF;
END LOOP;
order_name:=coalesce(p_order,'id');
IF order_name NOT IN ('id','name','created_at') THEN RAISE EXCEPTION 'DIRECTORY_ORDER_INVALID' USING ERRCODE='22023'; END IF;
RETURN QUERY EXECUTE format(
'SELECT (SELECT jsonb_object_agg(e.key,e.value) FROM jsonb_each(to_jsonb(t)) e WHERE e.key=ANY($1)) FROM public.%I t WHERE (%s) %s ORDER BY t.%I %s,t.id LIMIT $2',
p_table,scope_sql,filter_sql,order_name,CASE WHEN p_ascending IS FALSE THEN 'DESC' ELSE 'ASC' END)
USING columns_allowed,least(greatest(coalesce(p_limit,2000),1),2000);
END $function$

CREATE OR REPLACE FUNCTION public.vendor_update_order_shipping(p_session_token text, p_segment_id uuid, p_expected_version bigint, p_company_id uuid, p_rate_id uuid, p_delivery_fee numeric, p_currency text, p_free_shipping boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store_id uuid := private.require_vendor_session(p_session_token);
v_segment public.order_store_segments%rowtype;
v_order public.orders%rowtype;
v_company public.vendor_shipping_companies%rowtype;
v_rate public.vendor_shipping_rates%rowtype;
v_contract text;
v_currency text := upper(trim(coalesce(p_currency, '')));
v_fee numeric := case when coalesce(p_free_shipping, false)
then 0 else p_delivery_fee end;
v_snapshot jsonb;
v_details jsonb;
v_details_type text;
begin
select * into v_segment
from public.order_store_segments s
where s.id = p_segment_id
and s.store_id = v_store_id
for update;

if v_segment.id is null then
raise exception 'ORDER_SEGMENT_NOT_FOUND' using errcode = 'P0002';
end if;
if not v_segment.payment_confirmed then
raise exception 'ORDER_NOT_PAID' using errcode = 'P0001';
end if;

select * into v_order
from public.orders o
where o.id = v_segment.order_id
for update;

if v_order.id is null then
raise exception 'ORDER_NOT_FOUND' using errcode = 'P0002';
end if;
if v_order.shipping_version <> coalesce(p_expected_version, -1) then
raise exception 'ORDER_SHIPPING_VERSION_CONFLICT:%', v_order.shipping_version
using errcode = '40001';
end if;

v_details := private.v94_jsonb_object(to_jsonb(v_order.details));
v_contract := v_details ->> 'checkout_contract';
if v_contract is distinct from 'independent_vendor_orders' then
raise exception 'INDEPENDENT_VENDOR_ORDER_REQUIRED' using errcode = '22023';
end if;

select * into v_company
from public.vendor_shipping_companies c
where c.id = p_company_id
and c.store_id = v_store_id
and c.is_active = true;

if v_company.id is null then
raise exception 'SHIPPING_COMPANY_NOT_AVAILABLE' using errcode = '22023';
end if;

if p_rate_id is not null then
select * into v_rate
from public.vendor_shipping_rates r
where r.id = p_rate_id
and r.company_id = v_company.id
and r.store_id = v_store_id
and r.is_active = true;
if v_rate.id is null then
raise exception 'SHIPPING_RATE_NOT_AVAILABLE' using errcode = '22023';
end if;
end if;

if v_fee is null or v_fee < 0 or v_fee > 999999999999 then
raise exception 'SHIPPING_FEE_INVALID' using errcode = '22023';
end if;
if v_currency !~ '^[A-Z]{3,5}$' then
raise exception 'SHIPPING_CURRENCY_INVALID' using errcode = '22023';
end if;

v_snapshot := jsonb_strip_nulls(jsonb_build_object(
'profile_active', true,
'matched', p_rate_id is not null,
'mode', case when coalesce(p_free_shipping, false)
then 'vendor_free_shipping' else 'vendor_manual_selection' end,
'manual_override', true,
'free_shipping', coalesce(p_free_shipping, false),
'company_id', v_company.id,
'company_name', v_company.company_name,
'provider', v_company.company_name,
'company_phone', v_company.phone,
'tracking_url', v_company.tracking_url,
'rate_id', v_rate.id,
'base_delivery_fee', v_rate.delivery_fee,
'base_currency', v_rate.currency,
'delivery_fee', v_fee,
'cost', v_fee,
'currency', v_currency,
'estimated_days_min', v_rate.estimated_days_min,
'estimated_days_max', v_rate.estimated_days_max,
'scope', case when v_rate.id is null then null else jsonb_build_object(
'country', v_rate.destination_country,
'governorate', v_rate.governorate,
'area', v_rate.area
) end,
'selected_at', now(),
'selected_by', 'vendor'
));

v_details := jsonb_set(v_details, '{delivery_fee}', to_jsonb(v_fee), true);
v_details := jsonb_set(v_details, '{delivery_currency}', to_jsonb(v_currency), true);
v_details := jsonb_set(v_details, '{shipping_override}', v_snapshot, true);
v_details := jsonb_set(v_details, '{grand_total_components}', jsonb_build_array(
jsonb_build_object('type', 'goods', 'amount', v_segment.subtotal_local,
'currency', v_segment.currency),
jsonb_build_object('type', 'shipping', 'amount', v_fee,
'currency', v_currency)
), true);
if upper(v_currency) = upper(v_segment.currency) then
v_details := jsonb_set(v_details, '{grand_total_local}',
to_jsonb(v_segment.subtotal_local + v_fee), true);
else
v_details := v_details - 'grand_total_local';
end if;

select c.udt_name into v_details_type
from information_schema.columns c
where c.table_schema = 'public'
and c.table_name = 'orders'
and c.column_name = 'details';

if v_details_type = 'jsonb' then
execute $q$
update public.orders
set shipping_company_name = $2,
delivery_fee = $3,
delivery_currency = $4,
shipping_snapshot = $5,
shipping_version = shipping_version + 1,
details = $6
where id = $1
$q$ using v_order.id, v_company.company_name, v_fee, v_currency,
v_snapshot, v_details;
elsif v_details_type = 'json' then
execute $q$
update public.orders
set shipping_company_name = $2,
delivery_fee = $3,
delivery_currency = $4,
shipping_snapshot = $5,
shipping_version = shipping_version + 1,
details = $6::json
where id = $1
$q$ using v_order.id, v_company.company_name, v_fee, v_currency,
v_snapshot, v_details;
else
execute $q$
update public.orders
set shipping_company_name = $2,
delivery_fee = $3,
delivery_currency = $4,
shipping_snapshot = $5,
shipping_version = shipping_version + 1,
details = $6::text
where id = $1
$q$ using v_order.id, v_company.company_name, v_fee, v_currency,
v_snapshot, v_details;
end if;

-- Touching the segment emits the existing realtime event consumed by the
-- vendor table, while the canonical orders update reaches all other panels.
update public.order_store_segments
set updated_at = now()
where id = v_segment.id;

return public.vendor_get_order_shipping_control(
p_session_token, p_segment_id
);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_set_profit_margin(p_store_id text, p_margin numeric)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
v_margin NUMERIC;
BEGIN
IF p_margin IS NULL
OR p_margin < 0
OR p_margin > 10000
THEN
RAISE EXCEPTION
'Profit margin must be between 0 and 10000 percent';
END IF;

UPDATE public.local_stores
SET profit_margin_percent = p_margin
WHERE id::text = p_store_id
RETURNING profit_margin_percent INTO v_margin;

IF NOT FOUND THEN
RAISE EXCEPTION 'Store not found';
END IF;

RETURN v_margin;
END;
$function$

CREATE OR REPLACE FUNCTION public.customer_chat_send_v61(p_session_token text, p_message text DEFAULT NULL::text, p_file_url text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
v_message text := nullif(trim(coalesce(p_message, '')), '');
v_file_url text := nullif(trim(coalesce(p_file_url, '')), '');
v_row public.messages%rowtype;
begin
v_customer_id := private.require_customer_review_session(p_session_token);

if v_message is null and v_file_url is null then
raise exception 'CHAT_MESSAGE_REQUIRED';
end if;

if v_message is not null and char_length(v_message) > 4000 then
raise exception 'CHAT_MESSAGE_TOO_LONG';
end if;

if v_file_url is not null
and position('/storage/v1/object/public/chat-attachments/customer/' || v_customer_id::text || '/' in v_file_url) = 0 then
raise exception 'CHAT_ATTACHMENT_NOT_OWNED';
end if;

insert into public.messages(
customer_id, sender_type, message, file_url, read_by_employee, read_by_customer
) values (
v_customer_id, 'customer', coalesce(v_message, ''), v_file_url, false, true
)
returning * into v_row;

return jsonb_build_object(
'id', v_row.id,
'created_at', v_row.created_at,
'customer_id', v_row.customer_id,
'employee_id', v_row.employee_id,
'sender_type', v_row.sender_type,
'message', v_row.message,
'file_url', v_row.file_url,
'read_by_employee', v_row.read_by_employee,
'read_by_customer', v_row.read_by_customer
);
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_apply_coupon_v310(p_session_token text, p_order_id text, p_points bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
cid text;
o public.orders%rowtype;
c text;
sid text;
ratio numeric;
unit bigint;
need integer;
ids uuid[];
cnt integer;
cap bigint;
vendor_points bigint:=0;
kinto_points bigint:=0;
fund text;
begin
cid:=private.require_customer_review_session(p_session_token)::text;

if coalesce(cid,'')='' then
raise exception 'invalid customer session';
end if;

if p_points not in(1000,3000,5000) then
raise exception 'invalid coupon tier';
end if;

select *
into o
from public.orders
where id::text=p_order_id
for update;

if not found or o.customer_id::text<>cid then
raise exception 'order not found';
end if;

sid:=public.kinto_order_store_id_v310(o);

if sid is null then
raise exception 'store not found';
end if;

if o.status not in(
'بانتظار موافقة العميل',
'قيد الطلب',
'بانتظار الدفع',
'تمت الموافقة - بانتظار الدفع',
'تمت الموافقة'
) then
raise exception 'coupon not allowed at this order stage';
end if;

if coalesce(o.reward_discount_amount,0)>0
or coalesce(o.loyalty_points_redeemed,0)>0 then
raise exception 'order already has reward discount';
end if;

c:=public.kinto_normalize_currency_v310(o.currency);

if c<>'IQD' then
raise exception 'KINTO_V310_COUPON_TIERS_IQD_ONLY';
end if;

select max_order_ratio,coupon_unit
into ratio,unit
from public.kinto_loyalty_settings
where id=1;

cap:=floor(coalesce(o.total_price,0)*ratio);

if p_points>cap then
raise exception 'coupon exceeds 10 percent limit';
end if;

need:=p_points/unit;

-- Ordinary V310 coupons remain exact-store only.
-- Campaign coupons are valid at any store participating
-- in the same KINTO campaign.
select
array_agg(id order by expires_at,issued_at),
count(*)
into ids,cnt
from(
select
q.id,
q.expires_at,
q.issued_at
from public.kinto_loyalty_coupons q
where q.customer_id=cid
and q.currency=c
and q.status='active'
and q.expires_at>now()
and (
(
q.campaign_id is null
and q.store_id=sid
)
or
(
q.campaign_id is not null
and exists(
select 1
from public.kinto_campaign_stores cs
join public.kinto_campaigns ca
on ca.id=cs.campaign_id
where cs.campaign_id=q.campaign_id
and cs.store_id=sid
and ca.status<>'cancelled'
)
)
)
order by q.expires_at,q.issued_at
for update of q skip locked
limit need
) q;

if coalesce(cnt,0)<>need then
raise exception 'insufficient active eligible coupons';
end if;

select
coalesce(sum(points) filter(where funded_by='vendor'),0),
coalesce(sum(points) filter(where funded_by='kinto'),0)
into vendor_points,kinto_points
from public.kinto_loyalty_coupons
where id=any(ids);

fund:=case
when vendor_points>0 and kinto_points>0 then 'mixed'
when kinto_points>0 then 'kinto'
else 'vendor'
end;

update public.kinto_loyalty_coupons
set
status='used',
used_order_id=o.id::text,
used_at=now()
where id=any(ids);

update public.orders
set
loyalty_points_redeemed=p_points,
reward_discount_amount=p_points,
reward_discount_currency=c,
reward_discount_snapshot=jsonb_build_object(
'amount',p_points,
'currency',c,
'source','kinto_coupon_v401',
'funded_by',fund,
'vendor_points',vendor_points,
'kinto_points',kinto_points,
'store_id',sid,
'points',p_points,
'coupon_ids',to_jsonb(ids),
'product_total',o.total_price,
'shipping_discount',0
)
where id=o.id;

insert into public.kinto_loyalty_ledger(
customer_id,
store_id,
order_id,
event_type,
points,
currency,
eligible_product_total,
note,
funded_by,
funding_snapshot
)
values(
cid,
sid,
o.id::text,
'redeem',
-p_points,
c,
o.total_price,
'customer_selected_eligible_coupon',
fund,
jsonb_build_object(
'vendor_points',vendor_points,
'kinto_points',kinto_points,
'coupon_ids',to_jsonb(ids)
)
);

return jsonb_build_object(
'ok',true,
'points',p_points,
'currency',c,
'store_id',sid,
'order_id',o.id
);
end $function$

CREATE OR REPLACE FUNCTION private.v161_stamp_new_vendor_finance()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
d jsonb := private.v94_jsonb_object(to_jsonb(new.details));
r numeric;
sid uuid;
begin
if current_setting('app.v161_finance_checkout', true) <> 'on'
or coalesce(d ->> 'checkout_contract', '') <> 'independent_vendor_orders' then
return new;
end if;

sid := private.v94_uuid(d ->> 'store_id');

select commission_rate
into r
from public.local_stores
where id = sid;

if sid is null or r is null or r < 0 or r >= 100 then
raise exception 'V161_STORE_COMMISSION_INVALID';
end if;

d := d || jsonb_build_object(
'vendor_finance_version', 'v161',
'vendor_finance_snapshot', jsonb_build_object(
'version', 'v161',
'commission_rate', r,
'gross_amount', coalesce(new.total_price, 0),
'commission_amount', round(coalesce(new.total_price, 0) * r / 100, 2),
'other_deductions', 0,
'net_amount', round(coalesce(new.total_price, 0) * (1 - r / 100), 2),
'currency', coalesce(new.currency, 'IQD'),
'captured_at', now(),
'vendor_payment_status', 'pending'
)
);

new.details := d::text;
return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.v161_sync_new_vendor_finance_segment()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
d jsonb := private.v94_jsonb_object(to_jsonb(new.details));
s jsonb;
begin
s := d -> 'vendor_finance_snapshot';

if coalesce(d ->> 'vendor_finance_version', '') <> 'v161'
or jsonb_typeof(s) <> 'object' then
return new;
end if;

update public.order_store_segments
set
commission_snapshot = s,
vendor_payment_status = coalesce(s ->> 'vendor_payment_status', 'pending'),
updated_at = now()
where order_id = new.id;

return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_direct_order_g20(p_session_token text, p_campaign_id uuid, p_request_id uuid, p_customer_shipping jsonb, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$

declare
v_customer uuid;
v_campaign public.kinto_deals_v1_campaigns%rowtype;
v_checkout jsonb;
v_order_id uuid;
v_units integer;
v_distinct integer;
v_canonical_items jsonb;

begin

v_customer:=private.require_customer_review_session(p_session_token);

if v_customer is null then
raise exception 'DEALS_CUSTOMER_SESSION_REQUIRED'
using errcode='28000';
end if;

if p_campaign_id is null
or p_request_id is null
or jsonb_typeof(p_items) is distinct from 'array'
or jsonb_array_length(p_items)<1
or jsonb_array_length(p_items)>100
or jsonb_typeof(p_customer_shipping) is distinct from 'object'
then
raise exception 'DEALS_DIRECT_ORDER_INVALID_INPUT'
using errcode='22023';
end if;


select *
into v_campaign
from public.kinto_deals_v1_campaigns
where id=p_campaign_id;

if not found then
raise exception 'DEALS_CAMPAIGN_NOT_FOUND'
using errcode='P0001';
end if;


-- Validate input shape before canonical checkout.
if exists(
select 1
from jsonb_array_elements(p_items) x(item)
where jsonb_typeof(x.item)<>'object'

or coalesce(x.item->>'product_id','') !~*
'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

or coalesce(x.item->>'store_id','') !~*
'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

or coalesce(x.item->>'quantity','') <> '1'

or (
x.item ? 'selected_options'
and jsonb_typeof(x.item->'selected_options')<>'object'
)
) then
raise exception 'DEALS_DIRECT_ORDER_ITEM_INVALID'
using errcode='22023';
end if;


-- Products must belong to this campaign and this store.
if exists(
select 1
from jsonb_array_elements(p_items) x(item)

where x.item->>'store_id'<>v_campaign.store_id::text

or not exists(
select 1
from public.kinto_deals_v1_products cp
where cp.campaign_id=v_campaign.id
and cp.product_id=(x.item->>'product_id')::uuid
)
) then
raise exception 'DEALS_DIRECT_ORDER_CAMPAIGN_SCOPE_INVALID'
using errcode='P0001';
end if;


-- One campaign product = one unit.
-- Repeated product IDs are rejected.
if (
select count(*)
from jsonb_array_elements(p_items)
) <>
(
select count(distinct (x.item->>'product_id')::uuid)
from jsonb_array_elements(p_items) x(item)
) then
raise exception 'DEALS_DIRECT_ORDER_DUPLICATE_PRODUCT'
using errcode='22023';
end if;


-- Ignore browser variant authority.
-- Rebuild items from merchant-frozen campaign options.
select jsonb_agg(
jsonb_build_object(
'store_id',v_campaign.store_id,
'product_id',cp.product_id,
'quantity',1,
'selected_options',
coalesce(cp.selected_options,'{}'::jsonb)
)
order by ord.n
)
into v_canonical_items

from jsonb_array_elements(p_items)
with ordinality ord(item,n)

join public.kinto_deals_v1_products cp
on cp.campaign_id=v_campaign.id
and cp.product_id=(ord.item->>'product_id')::uuid;


if jsonb_array_length(v_canonical_items)
<> jsonb_array_length(p_items)
then
raise exception 'DEALS_DIRECT_ORDER_CANONICAL_ITEMS_INVALID'
using errcode='P0001';
end if;


select
coalesce(
sum((x.item->>'quantity')::integer),
0
)::integer,

count(
distinct (x.item->>'product_id')::uuid
)::integer

into v_units,v_distinct

from jsonb_array_elements(p_items) x(item);


-- Campaign rules.
-- Existing G5 lifecycle rechecks campaign rules later.
if
(
v_campaign.kind='choose_n'
and v_distinct<v_campaign.threshold_units
)

or (
v_campaign.kind='buy_n'
and v_units<v_campaign.threshold_units
)

or (
v_campaign.kind='limited_purchase'
and (
v_units<1
or v_units>v_campaign.max_units_per_customer
)
)
then
raise exception 'DEALS_THRESHOLD_NOT_MET'
using errcode='P0001';
end if;


-- Existing canonical order engine remains authoritative.
v_checkout:=
public.kinto_deals_v1_checkout_no_gift_g5d(
p_session_token,
p_campaign_id,
p_request_id,
p_customer_shipping,
v_canonical_items
);


v_order_id:=
nullif(
v_checkout->'deal'->>'order_id',
''
)::uuid;


if v_order_id is null then
raise exception 'DEALS_DIRECT_ORDER_CANONICAL_ORDER_MISSING'
using errcode='P0001';
end if;


-- Campaign identification only.
-- Does NOT change KN, status or order lifecycle.
update public.orders o

set details=(
coalesce(
nullif(o.details,'')::jsonb,
'{}'::jsonb
)

||

jsonb_build_object(
'deal_campaign_id',
v_campaign.id,

'deal_campaign_title',
v_campaign.title,

'deal_order_kind',
v_campaign.kind,

'deal_order_contract',
'g20-direct-campaign-order-v1'
)
)::text

where o.id=v_order_id
and o.customer_id::text=v_customer::text;


return
v_checkout
||
jsonb_build_object(
'direct_campaign_order',
true,

'campaign_order_id',
v_order_id,

'campaign_order_code',
(
select o.order_code
from public.orders o
where o.id=v_order_id
),

'deals_direct_order_contract',
'g20-direct-campaign-order-v1'
);

end;

$function$

CREATE OR REPLACE FUNCTION public.kinto_credit_points_v310(p_customer_id text, p_store_id text, p_currency text, p_whole_points bigint, p_fraction numeric, p_source_order_id text DEFAULT NULL::text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
c text;
unit bigint;
days integer;
cur bigint;
n bigint:=0;
begin
if coalesce(p_customer_id,'')='' or coalesce(p_store_id,'')='' then
raise exception 'customer/store required';
end if;

if not exists(
select 1
from public.local_stores s
where s.id::text=p_store_id
) then
raise exception 'store not found';
end if;

if coalesce(p_whole_points,0)<0 then
raise exception 'negative points not allowed';
end if;

c:=public.kinto_normalize_currency_v310(p_currency);

select coupon_unit,coupon_days
into unit,days
from public.kinto_loyalty_settings
where id=1;

insert into public.kinto_loyalty_wallets(
customer_id,store_id,currency
)
values(
p_customer_id,p_store_id,c
)
on conflict do nothing;

update public.kinto_loyalty_wallets
set
progress_points=progress_points+coalesce(p_whole_points,0),
fractional_carry=greatest(
0,
least(coalesce(p_fraction,0),.99999999)
),
updated_at=now()
where customer_id=p_customer_id
and store_id=p_store_id
and currency=c
returning progress_points into cur;

-- Coupon tiers are currently defined only for IQD.
-- Other currencies keep accumulating their independent balance.
if c='IQD' then
while cur>=unit loop
insert into public.kinto_loyalty_coupons(
customer_id,
store_id,
currency,
points,
source_order_id,
expires_at,
funded_by
)
values(
p_customer_id,
p_store_id,
c,
unit,
p_source_order_id,
now()+make_interval(days=>days),
'vendor'
);

cur:=cur-unit;
n:=n+1;
end loop;
end if;

update public.kinto_loyalty_wallets
set
progress_points=cur,
updated_at=now()
where customer_id=p_customer_id
and store_id=p_store_id
and currency=c;

return n;
end $function$

CREATE OR REPLACE FUNCTION public.admin_grant_loyalty_v310(p_session_token text, p_customer_id text, p_store_id text, p_currency text, p_points bigint, p_funded_by text, p_reason text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
aid text;
c text;
reason text;
fund text;
units bigint;
i bigint;
exp timestamptz;
begin
aid:=private.require_admin_session_v147(p_session_token);

if coalesce(aid,'')='' then
raise exception 'invalid admin session';
end if;

if coalesce(trim(p_customer_id),'')=''
or coalesce(trim(p_store_id),'')='' then
raise exception 'customer and store are required';
end if;

if p_points not in(1000,3000,5000) then
raise exception 'allowed grant tiers are 1000, 3000 or 5000';
end if;

fund:=lower(trim(coalesce(p_funded_by,'')));

if fund not in('vendor','kinto') then
raise exception 'invalid funding source';
end if;

reason:=trim(coalesce(p_reason,''));

if length(reason)<3 then
raise exception 'grant reason is required';
end if;

if not exists(
select 1
from public.customers
where id::text=p_customer_id
) then
raise exception 'customer not found';
end if;

if not exists(
select 1
from public.local_stores
where id::text=p_store_id
) then
raise exception 'store not found';
end if;

c:=public.kinto_normalize_currency_v310(p_currency);

if c<>'IQD' then
raise exception 'KINTO_V310_ADMIN_GRANT_TIERS_IQD_ONLY';
end if;

units:=p_points/1000;
exp:=now()+interval '30 days';

for i in 1..units loop
insert into public.kinto_loyalty_coupons(
customer_id,
store_id,
currency,
points,
status,
issued_at,
expires_at,
funded_by
)
values(
p_customer_id,
p_store_id,
c,
1000,
'active',
now(),
exp,
fund
);
end loop;

insert into public.kinto_loyalty_ledger(
customer_id,
store_id,
event_type,
points,
currency,
note,
actor_id,
funded_by,
funding_snapshot
)
values(
p_customer_id,
p_store_id,
'admin_adjustment',
p_points,
c,
reason,
aid,
fund,
jsonb_build_object(
'vendor_points',
case when fund='vendor' then p_points else 0 end,
'kinto_points',
case when fund='kinto' then p_points else 0 end
)
);

return jsonb_build_object(
'ok',true,
'customer_id',p_customer_id,
'store_id',p_store_id,
'points',p_points,
'currency',c,
'funded_by',fund,
'expires_at',exp
);
end $function$

CREATE OR REPLACE FUNCTION public.customer_portal_data(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
v_customer public.customers%rowtype;
v_orders jsonb;
begin
select c.* into v_customer
from public.customer_portal_sessions s
join public.customers c on c.id = s.customer_id
where s.token_hash = encode(digest(p_token, 'sha256'), 'hex')
and s.expires_at > now()
and c.status = 'active'
limit 1;

if v_customer.id is null then
return jsonb_build_object('ok', false, 'message', 'انتهت جلسة العميل');
end if;

select coalesce(jsonb_agg(to_jsonb(o) order by o.created_at desc), '[]'::jsonb)
into v_orders
from public.orders o
where o.customer_id = v_customer.id
or public.normalize_customer_phone(o.customer_phone) = public.normalize_customer_phone(v_customer.phone);

return jsonb_build_object(
'ok', true,
'customer', to_jsonb(v_customer) - 'password_hash',
'orders', v_orders
);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_set_exchange_rate(p_store_id uuid, p_rate numeric, p_base_currency text, p_target_currency text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
begin
if p_rate is null or p_rate <= 0 then
raise exception 'Exchange rate must be greater than zero';
end if;

update public.local_stores
set exchange_rate = p_rate,
exchange_base_currency = nullif(trim(p_base_currency), ''),
exchange_target_currency = nullif(trim(p_target_currency), '')
where id = p_store_id;

if not found then
raise exception 'Store not found';
end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_customer_account(p_customer_id uuid, p_name text, p_phone text, p_password text, p_customer_code text, p_email text DEFAULT NULL::text, p_country text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_state text DEFAULT NULL::text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
v_id uuid;
v_phone text := public.normalize_customer_phone(p_phone);
v_code text := nullif(trim(p_customer_code), '');
begin
if not public.is_staff() then
raise exception 'Not authorized';
end if;

if v_phone = '' or trim(coalesce(p_name, '')) = '' then
raise exception 'Name and phone are required';
end if;

if p_customer_id is null and length(coalesce(p_password, '')) < 4 then
raise exception 'Password must contain at least 4 characters';
end if;

if v_code is null then
v_code := 'CUS-' || upper(substr(encode(gen_random_bytes(4), 'hex'), 1, 8));
end if;

if p_customer_id is null then
insert into public.customers (
phone, name, email, country, address, status, balance,
customer_code, password_hash, payload
) values (
v_phone, trim(p_name), nullif(trim(p_email), ''), nullif(trim(p_country), ''),
nullif(trim(p_address), ''), 'active', 0, v_code,
crypt(p_password, gen_salt('bf')),
jsonb_strip_nulls(jsonb_build_object('code', v_code, 'state', nullif(trim(p_state), '')))
)
returning id into v_id;
else
update public.customers
set phone = v_phone,
name = trim(p_name),
email = nullif(trim(p_email), ''),
country = nullif(trim(p_country), ''),
address = nullif(trim(p_address), ''),
customer_code = v_code,
password_hash = case
when length(coalesce(p_password, '')) >= 4 then crypt(p_password, gen_salt('bf'))
else password_hash
end,
payload = coalesce(payload, '{}'::jsonb) ||
jsonb_strip_nulls(jsonb_build_object('code', v_code, 'state', nullif(trim(p_state), ''))),
updated_at = now()
where id = p_customer_id
returning id into v_id;

if v_id is null then raise exception 'Customer not found'; end if;
end if;

return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_submit_g4(p_session_token text, p_campaign_id uuid, p_expected_updated_at timestamp with time zone)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_store uuid;v_c public.kinto_deals_v1_campaigns%rowtype;
v_submission uuid;v_count integer;v_now timestamptz;
begin
v_store:=private.require_vendor_session(p_session_token);
if v_store is null then raise exception 'DEALS_VENDOR_SESSION_REQUIRED' using errcode='28000';end if;
if p_campaign_id is null or p_expected_updated_at is null then
raise exception 'DEALS_SUBMIT_REQUIRES_DRAFT_VERSION' using errcode='22023';end if;
select * into v_c from public.kinto_deals_v1_campaigns
where id=p_campaign_id and store_id=v_store for update;
if not found then raise exception 'DEALS_DRAFT_NOT_FOUND' using errcode='P0002';end if;
if v_c.status<>'draft' or exists(select 1 from public.kinto_deals_v1_submissions s where s.campaign_id=v_c.id) then
raise exception 'DEALS_ALREADY_SUBMITTED_OR_LOCKED' using errcode='40001';end if;
if v_c.updated_at is distinct from p_expected_updated_at then
raise exception 'DEALS_DRAFT_VERSION_CONFLICT' using errcode='40001';end if;
v_now:=clock_timestamp();
if v_c.ends_at<=v_now or v_c.ends_at<=v_c.starts_at then
raise exception 'DEALS_CAMPAIGN_PERIOD_ENDED' using errcode='22023';end if;
select count(*) into v_count from public.kinto_deals_v1_products cp
join public.local_products p on p.id=cp.product_id and p.store_id=v_store
where cp.campaign_id=v_c.id;
if v_count not between 1 and 50 or v_count<>(select count(*) from public.kinto_deals_v1_products where campaign_id=v_c.id)
or (v_c.kind='choose_n' and (v_c.threshold_units is null or v_c.threshold_units>v_count))
or (v_c.kind='buy_n' and (v_c.threshold_units is null or v_c.threshold_units not between 1 and 100))
or (v_c.kind='limited_purchase' and (v_c.threshold_units is not null or v_c.gift_product_id is not null or v_c.max_units_per_customer is null))
or (v_c.gift_product_id is not null and (not exists(select 1 from public.local_products p where p.id=v_c.gift_product_id and p.store_id=v_store)
or exists(select 1 from public.kinto_deals_v1_products cp where cp.campaign_id=v_c.id and cp.product_id=v_c.gift_product_id))) then
raise exception 'DEALS_DRAFT_PRODUCTS_OR_RULES_INVALID' using errcode='23514';end if;
insert into public.kinto_deals_v1_submissions
(campaign_id,store_id,title_snapshot,summary_snapshot,submitted_at,review_state,revision)
values(v_c.id,v_store,v_c.title,
jsonb_build_object('description',v_c.description,'kind',v_c.kind,
'starts_at',v_c.starts_at,'ends_at',v_c.ends_at,'threshold_units',v_c.threshold_units,
'gift_product_id',v_c.gift_product_id,'gift_selected_options',v_c.gift_selected_options,
'max_uses_per_customer',v_c.max_uses_per_customer,'max_units_per_customer',v_c.max_units_per_customer,
'max_total_redemptions',v_c.max_total_redemptions,'terms_snapshot',v_c.terms_snapshot,
'product_ids',(select coalesce(jsonb_agg(cp.product_id order by cp.created_at,cp.product_id),'[]'::jsonb)
from public.kinto_deals_v1_products cp where cp.campaign_id=v_c.id)),
v_now,'pending',1) returning id into v_submission;
update public.kinto_deals_v1_campaigns
set status='submitted',submitted_at=v_now,updated_at=greatest(v_now,v_c.updated_at+interval '1 microsecond')
where id=v_c.id;
return jsonb_build_object('ok',true,'campaign_id',v_c.id,'submission_id',v_submission,
'revision',1,'review_state','pending','published',false,'approved',false,
'merchant_push_sent',false,'customer_broadcast_sent',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_toggle_merchant_featured_slot(p_admin_id uuid, p_id uuid, p_is_active boolean)
