CREATE OR REPLACE FUNCTION public.customer_password_login(p_phone text, p_password text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
v_customer public.customers%rowtype;
v_token text;
begin
select * into v_customer
from public.customers
where public.normalize_customer_phone(phone) = public.normalize_customer_phone(p_phone)
and status = 'active'
and password_hash is not null
and password_hash = crypt(p_password, password_hash)
limit 1;

if v_customer.id is null then
return jsonb_build_object('ok', false, 'message', 'رقم الهاتف أو كلمة المرور غير صحيحة');
end if;

delete from public.customer_portal_sessions where expires_at < now();
v_token := encode(gen_random_bytes(32), 'hex');

insert into public.customer_portal_sessions(token_hash, customer_id, expires_at)
values (encode(digest(v_token, 'sha256'), 'hex'), v_customer.id, now() + interval '30 days');

return jsonb_build_object(
'ok', true,
'token', v_token,
'customer', jsonb_build_object(
'id', v_customer.id,
'name', v_customer.name,
'phone', v_customer.phone,
'code', coalesce(v_customer.customer_code, v_customer.payload ->> 'code'),
'country', v_customer.country,
'address', v_customer.address,
'role', 'customer'
)
);
end;
$function$

CREATE OR REPLACE FUNCTION public.staff_customer_view_v312(p_session_token text, p_role text, p_customer_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_role text;
v_actor_id text;
v_customer jsonb;
begin
v_role := lower(trim(coalesce(p_role,'')));

if v_role = 'admin' then
v_actor_id := private.require_admin_session_v147(p_session_token);

elsif v_role = 'employee' then
v_actor_id := private.require_employee_session_v143(p_session_token);

else
raise exception 'STAFF_CUSTOMER_VIEW_ROLE_INVALID';
end if;

if trim(coalesce(v_actor_id,'')) = '' then
raise exception 'STAFF_CUSTOMER_VIEW_SESSION_INVALID';
end if;

select
jsonb_strip_nulls(
jsonb_build_object(
'id', c.id,
'created_at', c.created_at,
'name', c.name,
'phone', c.phone,
'email', c.email,
'country', c.country,
'address', c.address,
'code', c.code,
'cart_items', c.cart_items,
'state', c.state,
'secondary_phone', c.secondary_phone,
'rewards_log', c.rewards_log,
'wallet_balance', c.wallet_balance,
'wallet_currency', c.wallet_currency,
'rewards_count', c.rewards_count,
'current_cycle_delivered', c.current_cycle_delivered
)
)
into v_customer
from public.customers c
where c.id::text = trim(p_customer_id)
limit 1;

if v_customer is null then
