'read_only', true,
'role', v_role,
'customer', v_customer
);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_revise_rejected_g4(p_session_token text, p_rejected_campaign_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_store uuid;v_old public.kinto_deals_v1_campaigns%rowtype;
v_last public.kinto_deals_v1_submissions%rowtype;v_new uuid;v_updated timestamptz;
begin
v_store:=private.require_vendor_session(p_session_token);
if v_store is null then raise exception 'DEALS_VENDOR_SESSION_REQUIRED' using errcode='28000';end if;
select * into v_old from public.kinto_deals_v1_campaigns
where id=p_rejected_campaign_id and store_id=v_store for update;
if not found or v_old.status<>'rejected' then
raise exception 'DEALS_REJECTED_CAMPAIGN_NOT_FOUND' using errcode='P0002';end if;
select * into v_last from public.kinto_deals_v1_submissions
where campaign_id=v_old.id order by submitted_at desc,id desc limit 1;
if not found or v_last.review_state<>'rejected' or nullif(btrim(v_last.rejection_reason),'') is null
or not exists(select 1 from public.kinto_deals_v1_review_events e
where e.submission_id=v_last.id and e.decision='rejected' and e.store_id=v_store) then
raise exception 'DEALS_REJECTION_DECISION_REQUIRED' using errcode='40001';end if;
insert into public.kinto_deals_v1_campaigns
(store_id,title,description,kind,status,starts_at,ends_at,threshold_units,
gift_product_id,gift_selected_options,max_uses_per_customer,max_units_per_customer,
max_total_redemptions,terms_snapshot)
values(v_store,v_old.title,v_old.description,v_old.kind,'draft',v_old.starts_at,v_old.ends_at,
v_old.threshold_units,v_old.gift_product_id,v_old.gift_selected_options,
v_old.max_uses_per_customer,v_old.max_units_per_customer,v_old.max_total_redemptions,
v_old.terms_snapshot || jsonb_build_object('revision_origin_campaign_id',v_old.id,
'revision_origin_submission_id',v_last.id))
returning id,updated_at into v_new,v_updated;
insert into public.kinto_deals_v1_products(campaign_id,product_id)
select v_new,cp.product_id from public.kinto_deals_v1_products cp where cp.campaign_id=v_old.id;
return jsonb_build_object('ok',true,'campaign_id',v_new,'updated_at',v_updated,
'status','draft','source_campaign_id',v_old.id,'source_submission_id',v_last.id,
'rejection_reason',v_last.rejection_reason,'published',false,'submitted',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_deals_v1_checkout_no_gift_g5d(p_session_token text, p_campaign_id uuid, p_request_id uuid, p_customer_shipping jsonb, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_customer uuid;
v_campaign public.kinto_deals_v1_campaigns%rowtype;
v_request private.kinto_deals_v1_checkout_requests_g5d%rowtype;
v_hash text;
v_checkout jsonb;
v_order_id uuid;
v_reservation jsonb;
begin
v_customer:=private.require_customer_review_session(p_session_token);
if v_customer is null then raise exception 'DEALS_CUSTOMER_SESSION_REQUIRED' using errcode='28000';end if;
if p_campaign_id is null or p_request_id is null
or jsonb_typeof(p_items) is distinct from 'array'
or jsonb_typeof(p_customer_shipping) is distinct from 'object' then
raise exception 'DEALS_CHECKOUT_INVALID_INPUT' using errcode='22023';end if;
if not coalesce((select enabled from public.kinto_deals_v1_flags
where key='merchant_deals_enabled'),false) then
raise exception 'DEALS_FEATURE_DISABLED' using errcode='P0001';end if;

select * into v_campaign from public.kinto_deals_v1_campaigns
where id=p_campaign_id for update;
if not found then
raise exception 'DEALS_CAMPAIGN_NOT_FOUND' using errcode='P0001';end if;

v_hash:=md5(jsonb_build_object('campaign_id',p_campaign_id,
'shipping',p_customer_shipping,'items',p_items)::text);

insert into private.kinto_deals_v1_checkout_requests_g5d(
customer_id,request_id,campaign_id,payload_hash)
values(v_customer,p_request_id,p_campaign_id,v_hash)
on conflict(customer_id,request_id) do nothing;

select * into v_request from private.kinto_deals_v1_checkout_requests_g5d
where customer_id=v_customer and request_id=p_request_id for update;

if v_request.campaign_id is distinct from p_campaign_id
or v_request.payload_hash is distinct from v_hash then
raise exception 'DEALS_IDEMPOTENCY_KEY_REUSED' using errcode='23505';end if;

if v_request.result is not null then return v_request.result;end if;

if v_campaign.gift_product_id is not null then
perform set_config('app.kinto_deals_gift_campaign_id',v_campaign.id::text,true);
perform set_config('app.kinto_deals_verified_customer_id',v_customer::text,true);
end if;

v_checkout:=public.checkout_independent_vendor_orders_v101(
v_customer,null,null,p_customer_shipping,p_items);

perform set_config('app.kinto_deals_gift_campaign_id','',true);
perform set_config('app.kinto_deals_verified_customer_id','',true);

select (x->>'id')::uuid into v_order_id
from jsonb_array_elements(v_checkout->'orders') x
where x->>'store_id'=v_campaign.store_id::text;

if v_order_id is null then
raise exception 'DEALS_CAMPAIGN_STORE_NOT_IN_CART' using errcode='P0001';end if;

v_reservation:=private.kinto_deals_v1_reserve_canonical_order_g5(
p_session_token,p_campaign_id,v_order_id);

v_checkout:=v_checkout||jsonb_build_object(
'deal',jsonb_build_object('campaign_id',p_campaign_id,
'order_id',v_order_id,'redemption_id',v_reservation->>'redemption_id',
'state','pending','gift_fulfilled',v_reservation->'gift_fulfilled'),
'deals_checkout_contract','g5g_canonical_gift_or_no_gift_v1');

update private.kinto_deals_v1_checkout_requests_g5d
set result=v_checkout where customer_id=v_customer and request_id=p_request_id;

return v_checkout;
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_password_login_v2(p_phone text, p_password text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
v_customer public.customers%rowtype;
v_salt text;
v_expected_hash text;
v_token text;
v_token_hash text;
begin
select *
into v_customer
from public.customers
where public.normalize_customer_phone(phone)
= public.normalize_customer_phone(p_phone)
and status = 'active'
and password_hash like 'sha256$%$%'
limit 1;

if v_customer.id is null then
return pg_catalog.jsonb_build_object(
'ok', false,
'message', 'رقم الهاتف أو كلمة المرور غير صحيحة'
);
end if;

v_salt :=
pg_catalog.split_part(
v_customer.password_hash,
'$',
2
);

v_expected_hash :=
'sha256$' ||
v_salt ||
'$' ||
pg_catalog.encode(
extensions.digest(
v_salt || p_password,
'sha256'
),
'hex'
);

if v_customer.password_hash <> v_expected_hash then
return pg_catalog.jsonb_build_object(
'ok', false,
'message', 'رقم الهاتف أو كلمة المرور غير صحيحة'
);
end if;

delete from public.customer_portal_sessions
where expires_at < pg_catalog.now();

v_token :=
pg_catalog.md5(
pg_catalog.random()::text ||
pg_catalog.clock_timestamp()::text ||
v_customer.id::text ||
p_phone
)
||
pg_catalog.md5(
pg_catalog.random()::text ||
pg_catalog.clock_timestamp()::text ||
p_password
);

v_token_hash :=
pg_catalog.encode(
extensions.digest(
v_token,
'sha256'
),
'hex'
);

insert into public.customer_portal_sessions (
token_hash,
customer_id,
expires_at
)
values (
v_token_hash,
v_customer.id,
pg_catalog.now() + interval '30 days'
);

return pg_catalog.jsonb_build_object(
'ok', true,
'token', v_token,
'customer', pg_catalog.jsonb_build_object(
'id', v_customer.id,
'name', v_customer.name,
'phone', v_customer.phone,
'code', coalesce(
v_customer.customer_code,
v_customer.payload ->> 'code'
),
'country', v_customer.country,
'address', v_customer.address,
'role', 'customer'
)
);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_loyalty_overview_v344(p_session_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
sid text := private.require_vendor_session(p_session_token)::text;
settings public.kinto_store_loyalty_settings%rowtype;
cap numeric;
begin
select * into settings from public.kinto_store_loyalty_settings where store_id = sid;
select max_store_earn_rate into cap from public.kinto_loyalty_settings where id = 1;
return jsonb_build_object(
