CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_product_options_g20(p_session_token text, p_product_ids uuid[])
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store uuid;
v_rows jsonb;
begin
v_store:=private.require_vendor_session(p_session_token);

if v_store is null then
raise exception 'DEALS_VENDOR_SESSION_REQUIRED'
using errcode='28000';
end if;

if p_product_ids is null
or cardinality(p_product_ids) not between 1 and 50
then
raise exception 'DEALS_PRODUCT_LIST_REQUIRED'
using errcode='22023';
end if;

if (
select count(*)
from public.local_products p
where p.store_id=v_store
and p.id=any(p_product_ids)
)<>cardinality(p_product_ids)
then
raise exception 'DEALS_PRODUCT_OWNERSHIP_REQUIRED'
using errcode='23514';
end if;

select coalesce(
jsonb_agg(
jsonb_build_object(
'id',p.id,

'options',
jsonb_build_object(
'colors',
coalesce(p.options->'colors','[]'::jsonb),

'sizes',
coalesce(p.options->'sizes','[]'::jsonb),

'volumes',
coalesce(p.options->'volumes','[]'::jsonb)
),

'available_combinations',
coalesce((
select jsonb_agg(
jsonb_build_object(
'color',c.v,
'size',s.v,
'volume',vol.v
)
)
from jsonb_array_elements_text(
case
when jsonb_array_length(
coalesce(p.options->'colors','[]'::jsonb)
)>0
then p.options->'colors'
else '[""]'::jsonb
end
) c(v)

cross join jsonb_array_elements_text(
case
when jsonb_array_length(
coalesce(p.options->'sizes','[]'::jsonb)
)>0
then p.options->'sizes'
else '[""]'::jsonb
end
) s(v)

cross join jsonb_array_elements_text(
case
when jsonb_array_length(
coalesce(p.options->'volumes','[]'::jsonb)
)>0
then p.options->'volumes'
else '[""]'::jsonb
end
) vol(v)

where private.kinto_deals_v1_combo_available_g21d(
v_store,p.id,c.v,s.v,vol.v
)
),'[]'::jsonb)
)
order by p.id
),
'[]'::jsonb
)
into v_rows
from public.local_products p
where p.store_id=v_store
and p.id=any(p_product_ids);

return v_rows;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_site_settings(p_admin_id text, p_value jsonb)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
begin
if p_admin_id is null or btrim(p_admin_id) = '' then
raise exception 'adminId is required';
end if;

if p_value is null or jsonb_typeof(p_value) <> 'object' then
raise exception 'site_settings payload must be a JSON object';
end if;

if not exists (
select 1
from public.employees e
where e.id::text = btrim(p_admin_id)
and lower(btrim(coalesce(e.role::text, ''))) in ('admin', 'أدمن', 'ادمن')
and coalesce(e.is_active, true) = true
) then
raise exception 'Not authorized to manage site settings';
end if;

insert into public.settings (key, value, updated_at)
values ('site_settings', p_value, now())
on conflict (key) do update
set value = excluded.value,
updated_at = now();

return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_merchant_featured_slot_v2(p_admin_id uuid, p_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
v_deleted uuid;
begin
-- السماح للأدمن المخوّل فقط
if p_admin_id is null
or not public.meshwar_is_admin(p_admin_id) then
raise exception 'not authorized';
end if;

-- يجب إرسال معرف الحملة
if p_id is null then
raise exception 'campaign id is required';
end if;

-- الحذف محصور حصرياً بجدول الحملات
delete from public.merchant_featured_slots
where id = p_id
returning id into v_deleted;

