$function$

CREATE OR REPLACE FUNCTION public.meshwar_lock_order_cost_snapshot()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
v_store_id TEXT;
v_product_id TEXT;
v_product_name TEXT;
v_cost NUMERIC(14,2);
v_status TEXT;
BEGIN
-- Once a snapshot exists it is immutable.
IF TG_OP = 'UPDATE' AND OLD.snapshot_cost_price IS NOT NULL THEN
NEW.snapshot_cost_price := OLD.snapshot_cost_price;
RETURN NEW;
END IF;

v_status := lower(trim(coalesce(NEW.status, '')));

IF v_status NOT IN (
'تم التسليم',
'delivered',
'delivered_to_customer'
) THEN
RETURN NEW;
END IF;

IF NEW.snapshot_cost_price IS NOT NULL THEN
RETURN NEW;
END IF;

-- Explicit order-level cost has priority.
IF NEW.cost_price IS NOT NULL THEN
NEW.snapshot_cost_price := NEW.cost_price;
RETURN NEW;
END IF;

v_store_id :=
nullif(trim((new.details::jsonb)->>'store_id'), '');

v_product_id :=
nullif(trim((new.details::jsonb)->>'product_id'), '');

v_product_name :=
nullif(trim((new.details::jsonb)->>'product_name'), '');

IF v_product_id IS NOT NULL THEN

SELECT p.cost_price
INTO v_cost
FROM public.local_products p
WHERE p.id::text = v_product_id
AND (
v_store_id IS NULL
OR p.store_id::text = v_store_id
)
LIMIT 1;

ELSIF
v_store_id IS NOT NULL
AND v_product_name IS NOT NULL
THEN

SELECT p.cost_price
INTO v_cost
FROM public.local_products p
WHERE p.store_id::text = v_store_id
AND p.product_name = v_product_name
ORDER BY
p.updated_at DESC NULLS LAST,
p.created_at DESC NULLS LAST
LIMIT 1;

END IF;

-- Legacy/unknown products remain NULL.
-- No historical value is fabricated.
NEW.snapshot_cost_price := v_cost;

RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_release_local_stock_after_insert()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
d jsonb;
product_uuid uuid;
requested_qty integer;
begin
begin
d := coalesce(new.details::jsonb, '{}'::jsonb);
exception when others then
return new;
end;

if coalesce(d->>'source','') <> 'local_store' then
return new;
end if;

begin
product_uuid := nullif(d->>'product_id','')::uuid;
requested_qty := greatest(
1,
coalesce(
nullif(d->>'requested_quantity','')::integer,
nullif(d->>'quantity','')::integer,
1
)
);
exception when others then
return new;
end;

-- Current storefront performs a temporary Compare-and-Set reservation before INSERT.
-- Release it immediately after a successful order INSERT. This means the order itself
-- does not retain a stock deduction; the final deduction occurs only on paid status.
update public.local_products
set stock_quantity = stock_quantity + requested_qty,
is_out_of_stock = false
where id = product_uuid
and stock_quantity is not null;

return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_adjust_variant_stock(p_options jsonb, p_details jsonb, p_qty integer, p_direction integer)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
declare
result_options jsonb := coalesce(p_options, '{}'::jsonb);
variant_stock jsonb := coalesce(p_options->'variant_stock', '{}'::jsonb);
group_key text;
legacy_group_key text;
selected_value text;
current_qty integer;
next_qty integer;
target_group text;
begin
if p_qty is null or p_qty < 1 then
raise exception 'Variant stock quantity must be at least 1';
end if;

if p_direction not in (-1, 1) then
raise exception 'Variant stock direction must be -1 or 1';
end if;

for group_key, legacy_group_key, selected_value in
select * from (values
('color'::text,  'colors'::text,  coalesce(nullif(p_details->>'color',''),  nullif(p_details->>'selected_color',''))),
('size'::text,   'sizes'::text,   coalesce(nullif(p_details->>'size',''),   nullif(p_details->>'selected_size',''))),
('volume'::text, 'volumes'::text, coalesce(nullif(p_details->>'volume',''), nullif(p_details->>'selected_volume','')))
) as selected_variants(group_key, legacy_group_key, selected_value)
loop
if selected_value is null or btrim(selected_value) = '' then
continue;
end if;

target_group := null;

if jsonb_typeof(variant_stock->group_key) = 'object'
and (variant_stock->group_key) ? selected_value then
target_group := group_key;

elsif jsonb_typeof(variant_stock->legacy_group_key) = 'object'
and (variant_stock->legacy_group_key) ? selected_value then
target_group := legacy_group_key;
end if;

-- No configured per-variant quantity: preserve legacy total-stock behavior.
if target_group is null then
continue;
end if;

begin
current_qty := (variant_stock->target_group->>selected_value)::integer;
exception when others then
raise exception 'Invalid variant stock for %=%', group_key, selected_value;
end;

if current_qty < 0 then
raise exception 'Invalid negative variant stock for %=%', group_key, selected_value;
end if;

if p_direction = -1 and current_qty < p_qty then
raise exception 'Insufficient variant stock for %=%: available %, requested %',
group_key, selected_value, current_qty, p_qty;
end if;

next_qty := current_qty + (p_direction * p_qty);

if next_qty < 0 then
raise exception 'Variant stock cannot become negative for %=%', group_key, selected_value;
end if;

variant_stock := jsonb_set(
variant_stock,
array[target_group, selected_value],
to_jsonb(next_qty),
false
);
end loop;

return jsonb_set(
result_options,
'{variant_stock}',
variant_stock,
true
);
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_normalize_local_order_details()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
declare
d jsonb;
begin
begin
d := coalesce(new.details::jsonb, '{}'::jsonb);
exception when others then
return new;
end;

if coalesce(d->>'source','') <> 'local_store' then return new; end if;

if coalesce(d->>'color','') = '' and coalesce(d->>'selected_color','') <> '' then
d := jsonb_set(d, '{color}', to_jsonb(d->>'selected_color'), true);
end if;
if coalesce(d->>'size','') = '' and coalesce(d->>'selected_size','') <> '' then
d := jsonb_set(d, '{size}', to_jsonb(d->>'selected_size'), true);
end if;
if coalesce(d->>'volume','') = '' and coalesce(d->>'selected_volume','') <> '' then
d := jsonb_set(d, '{volume}', to_jsonb(d->>'selected_volume'), true);
end if;
if coalesce(d->>'selected_color','') = '' and coalesce(d->>'color','') <> '' then
d := jsonb_set(d, '{selected_color}', to_jsonb(d->>'color'), true);
end if;
if coalesce(d->>'selected_size','') = '' and coalesce(d->>'size','') <> '' then
d := jsonb_set(d, '{selected_size}', to_jsonb(d->>'size'), true);
end if;
if coalesce(d->>'selected_volume','') = '' and coalesce(d->>'volume','') <> '' then
d := jsonb_set(d, '{selected_volume}', to_jsonb(d->>'volume'), true);
end if;

new.details := d::text;
return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_matrix_stock_key(p_details jsonb)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
declare
parts text[] := array[]::text[];
v text;
begin
v := coalesce(nullif(p_details->>'color',''), nullif(p_details->>'selected_color',''));
if v is not null and btrim(v) <> '' then
parts := array_append(parts, btrim(v));
end if;

v := coalesce(nullif(p_details->>'size',''), nullif(p_details->>'selected_size',''));
if v is not null and btrim(v) <> '' then
parts := array_append(parts, btrim(v));
end if;

v := coalesce(nullif(p_details->>'volume',''), nullif(p_details->>'selected_volume',''));
if v is not null and btrim(v) <> '' then
parts := array_append(parts, btrim(v));
end if;

if coalesce(array_length(parts,1),0) < 2 then
return null;
end if;

return array_to_string(parts, '_');
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_adjust_matrix_stock(p_options jsonb, p_details jsonb, p_qty integer, p_direction integer)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
declare
result_options jsonb := coalesce(p_options, '{}'::jsonb);
matrix_stock jsonb := coalesce(p_options->'matrix_stock', '{}'::jsonb);
matrix_key text;
current_qty integer;
next_qty integer;
begin
if p_qty is null or p_qty < 1 then
raise exception 'Matrix stock quantity must be at least 1';
end if;

if p_direction not in (-1,1) then
raise exception 'Matrix stock direction must be -1 or 1';
end if;

matrix_key := public.meshwar_matrix_stock_key(p_details);

if matrix_key is null then
return result_options;
end if;

if jsonb_typeof(matrix_stock) <> 'object'
or not (matrix_stock ? matrix_key) then
return result_options;
end if;

begin
current_qty := (matrix_stock->>matrix_key)::integer;
exception when others then
raise exception 'Invalid matrix stock for combination %', matrix_key;
end;

if current_qty < 0 then
raise exception 'Invalid negative matrix stock for combination %', matrix_key;
end if;

if p_direction = -1 and current_qty < p_qty then
raise exception
'Insufficient matrix stock for combination %. Available %, requested %',
matrix_key,
current_qty,
p_qty;
end if;

next_qty := current_qty + (p_direction * p_qty);

if next_qty < 0 then
raise exception 'Matrix stock cannot become negative for combination %', matrix_key;
end if;

matrix_stock := jsonb_set(
matrix_stock,
array[matrix_key],
to_jsonb(next_qty),
false
);

return jsonb_set(
result_options,
'{matrix_stock}',
matrix_stock,
true
);
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_local_stock_status_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
d jsonb;
product_uuid uuid;
requested_qty integer;
current_stock integer;
current_options jsonb;
next_options jsonb;
lifecycle_state text;
rejected_or_cancelled boolean;
begin
if old.status is not distinct from new.status then return new; end if;

begin
d := coalesce(new.details::jsonb, '{}'::jsonb);
exception when others then
return new;
end;

if coalesce(d->>'source','') <> 'local_store' then return new; end if;

begin
product_uuid := nullif(d->>'product_id','')::uuid;
requested_qty := greatest(1, coalesce(
nullif(d->>'requested_quantity','')::integer,
nullif(d->>'quantity','')::integer,
1
));
exception when others then
return new;
end;

lifecycle_state := coalesce(d->>'stock_lifecycle_state','');
rejected_or_cancelled := new.status = any(array[
'مرفوض','رفض التسليم','رفض الطلب','ملغي من قبل العميل','ملغي','ملغى'
]);

if new.status = 'تم التسديد' then
if lifecycle_state = 'deducted' then return new; end if;

if lifecycle_state = ''
and coalesce(d->>'stock_deducted_at','') <> ''
and coalesce(d->>'stock_restored_at','') = '' then
d := jsonb_set(d, '{stock_lifecycle_state}', '"deducted"'::jsonb, true);
new.details := d::text;
return new;
end if;

select stock_quantity, coalesce(options, '{}'::jsonb)
into current_stock, current_options
from public.local_products
where id = product_uuid
for update;

if not found then
raise exception 'Local product % was not found', product_uuid;
end if;

if current_stock is null then
return new;
end if;

if current_stock < requested_qty then
raise exception 'Insufficient stock for product %. Available %, requested %',
product_uuid, current_stock, requested_qty;
end if;

next_options := public.meshwar_adjust_variant_stock(
current_options,
d,
requested_qty,
-1
);

update public.local_products
set stock_quantity = current_stock - requested_qty,
options = next_options,
is_out_of_stock = (current_stock - requested_qty) = 0
where id = product_uuid;

d := jsonb_set(d, '{stock_lifecycle_state}', '"deducted"'::jsonb, true);
d := jsonb_set(d, '{stock_deducted_at}', to_jsonb(now()::text), true);
d := jsonb_set(d, '{stock_deducted_quantity}', to_jsonb(requested_qty), true);
d := d - 'stock_restored_at' - 'stock_restored_quantity';

new.details := d::text;
return new;
end if;

if rejected_or_cancelled then
if lifecycle_state <> 'deducted' then
if not (
lifecycle_state = ''
and coalesce(d->>'stock_deducted_at','') <> ''
and coalesce(d->>'stock_restored_at','') = ''
) then
return new;
end if;
end if;

select stock_quantity, coalesce(options, '{}'::jsonb)
into current_stock, current_options
from public.local_products
where id = product_uuid
for update;

if not found then
raise exception 'Local product % was not found', product_uuid;
end if;

if current_stock is null then
return new;
end if;

next_options := public.meshwar_adjust_variant_stock(
current_options,
d,
requested_qty,
1
);

update public.local_products
set stock_quantity = current_stock + requested_qty,
options = next_options,
is_out_of_stock = false
where id = product_uuid;

d := jsonb_set(d, '{stock_lifecycle_state}', '"restored"'::jsonb, true);
d := jsonb_set(d, '{stock_restored_at}', to_jsonb(now()::text), true);
d := jsonb_set(d, '{stock_restored_quantity}', to_jsonb(requested_qty), true);

new.details := d::text;
return new;
end if;

return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_local_cart_bundle_stock_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
d jsonb;
product_rec record;
item_rec record;
current_stock integer;
current_options jsonb;
next_options jsonb;
item_details jsonb;
begin
if old.status is not distinct from new.status then
return new;
end if;

begin
d := coalesce(new.details::jsonb, '{}'::jsonb);
exception when others then
return new;
end;

if coalesce(d->>'source','') <> 'local_cart_bundle' then
return new;
end if;

-- Pending / rejected / customer-cancelled bundles never affect stock.
if new.status <> 'تم التسديد' then
return new;
end if;

-- Exactly-once protection.
if coalesce(d->>'bundle_stock_lifecycle_state','') = 'deducted' then
return new;
end if;

if jsonb_typeof(d->'items') <> 'array' or jsonb_array_length(d->'items') = 0 then
raise exception 'Local cart bundle has no items';
end if;

-- Validate product ids/quantities and lock every affected product in stable order.
-- Aggregating total quantity here prevents different option rows for one product
-- from collectively overdrawing local_products.stock_quantity.
for product_rec in
select nullif(item->>'product_id','')::uuid as product_id,
sum(greatest(1, coalesce(nullif(item->>'quantity','')::integer, 1)))::integer as requested_qty
from jsonb_array_elements(d->'items') item
group by nullif(item->>'product_id','')::uuid
order by nullif(item->>'product_id','')::uuid
loop
if product_rec.product_id is null then
raise exception 'Local cart bundle contains an invalid product id';
end if;

select stock_quantity
into current_stock
from public.local_products
where id = product_rec.product_id
for update;

if not found then
raise exception 'Local product % was not found', product_rec.product_id;
end if;

if current_stock is not null and current_stock < product_rec.requested_qty then
raise exception 'Insufficient stock for product %. Available %, requested %',
product_rec.product_id, current_stock, product_rec.requested_qty;
end if;
end loop;

-- Process one locked product at a time. Every option row is applied to an in-memory
-- copy first; any insufficient configured variant/matrix raises before that product
-- is updated, and PostgreSQL rolls the whole order status transaction back.
for product_rec in
select nullif(item->>'product_id','')::uuid as product_id,
sum(greatest(1, coalesce(nullif(item->>'quantity','')::integer, 1)))::integer as requested_qty
from jsonb_array_elements(d->'items') item
group by nullif(item->>'product_id','')::uuid
order by nullif(item->>'product_id','')::uuid
loop
select stock_quantity, coalesce(options, '{}'::jsonb)
into current_stock, current_options
from public.local_products
where id = product_rec.product_id;

next_options := current_options;

for item_rec in
select item,
greatest(1, coalesce(nullif(item->>'quantity','')::integer, 1))::integer as requested_qty
from jsonb_array_elements(d->'items') item
where nullif(item->>'product_id','')::uuid = product_rec.product_id
loop
-- Existing stock helpers expect color/size/volume at the top level. V93 bundle
-- items persist them under selected_options, so flatten only those selections.
item_details := jsonb_build_object(
'color',  coalesce(item_rec.item->'selected_options'->>'color',  item_rec.item->>'color',  ''),
'size',   coalesce(item_rec.item->'selected_options'->>'size',   item_rec.item->>'size',   ''),
'volume', coalesce(item_rec.item->'selected_options'->>'volume', item_rec.item->>'volume', '')
);

next_options := public.meshwar_adjust_variant_stock(
next_options,
item_details,
item_rec.requested_qty,
-1
);
next_options := public.meshwar_adjust_matrix_stock(
next_options,
item_details,
item_rec.requested_qty,
-1
);
end loop;

-- One atomic row update keeps total, variants, matrix combinations and availability
-- synchronized. Legacy null total stock stays unmanaged while option JSON is retained.
if current_stock is not null then
update public.local_products
set stock_quantity = current_stock - product_rec.requested_qty,
options = next_options,
is_out_of_stock = (current_stock - product_rec.requested_qty) = 0
where id = product_rec.product_id;
end if;
end loop;

d := jsonb_set(d, '{bundle_stock_lifecycle_state}', '"deducted"'::jsonb, true);
d := jsonb_set(d, '{bundle_stock_deducted_at}', to_jsonb(now()::text), true);
d := jsonb_set(d, '{bundle_variant_stock_deducted}', 'true'::jsonb, true);
new.details := d;
return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.v94_jsonb_object(p_value jsonb)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
AS $function$
declare
v_result jsonb;
begin
if p_value is null then
return '{}'::jsonb;
end if;

if jsonb_typeof(p_value) = 'object' then
return p_value;
end if;

if jsonb_typeof(p_value) = 'string' then
begin
v_result := (p_value #>> '{}')::jsonb;

if jsonb_typeof(v_result) = 'object' then
return v_result;
end if;
exception when others then
return '{}'::jsonb;
end;
end if;

return '{}'::jsonb;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_vendor_session(p_session_token text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_store_id uuid;
v_token_hash bytea;
begin
if coalesce(length(p_session_token), 0) < 32 then
raise exception 'VENDOR_SESSION_INVALID'
using errcode = '28000';
end if;

v_token_hash := digest(
p_session_token,
'sha256'
);

select s.store_id
into v_store_id
from public.vendor_sessions s
join public.local_stores ls
on ls.id = s.store_id
where s.token_hash = v_token_hash
and s.revoked_at is null
and s.expires_at > now()
and lower(
trim(coalesce(ls.status, ''))
) = 'active'
limit 1;

if v_store_id is null then
raise exception 'VENDOR_SESSION_INVALID'
using errcode = '28000';
end if;

update public.vendor_sessions
set last_seen_at = now()
where token_hash = v_token_hash;

return v_store_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_submit_featured_request(p_store_id uuid, p_slot_type character varying, p_banner_url text, p_store_logo text, p_store_name character varying, p_item_ids uuid[], p_requested_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_requested_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
if not exists(
select 1 from public.local_stores s
where s.id=p_store_id and coalesce(s.is_active,true)=true
) then
raise exception 'store not found or inactive';
end if;

if p_slot_type not in ('hero_banner','featured_grid','sponsored_product') then
raise exception 'invalid slot_type';
end if;
if nullif(trim(coalesce(p_store_name,'')),'') is null then
raise exception 'store_name required';
end if;
if p_requested_start_date is not null
and p_requested_end_date is not null
and p_requested_end_date <= p_requested_start_date then
raise exception 'requested end must be after start';
end if;

insert into public.merchant_featured_requests(
store_id,slot_type,banner_url,store_logo,store_name,item_ids,
requested_start_date,requested_end_date,status,updated_at
) values(
p_store_id,p_slot_type,nullif(trim(p_banner_url),''),
nullif(trim(p_store_logo),''),trim(p_store_name),
coalesce(p_item_ids,'{}'::uuid[]),p_requested_start_date,
p_requested_end_date,'pending',now()
) returning id into v_id;

return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_send_vendor_notification_v391(p_session_token text, p_title text, p_body text, p_kind text DEFAULT 'announcement'::text, p_store_ids text[] DEFAULT NULL::text[], p_all_stores boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
aid text;
nid uuid;
cnt integer:=0;
k text;
begin
aid:=private.require_admin_session_v147(p_session_token);

if coalesce(aid,'')='' then
raise exception 'invalid admin session';
end if;

if length(trim(coalesce(p_title,''))) not between 2 and 160 then
raise exception 'invalid title';
end if;

if length(trim(coalesce(p_body,''))) not between 2 and 4000 then
raise exception 'invalid body';
end if;

k:=lower(trim(coalesce(p_kind,'announcement')));

if k not in(
'announcement',
'campaign',
'warning',
'policy',
'action_required'
) then
raise exception 'invalid notification kind';
end if;

if not coalesce(p_all_stores,false)
and coalesce(cardinality(p_store_ids),0)=0 then
raise exception 'recipient required';
end if;

insert into public.kinto_admin_notifications(
title,
body,
kind,
created_by
)
values(
trim(p_title),
trim(p_body),
k,
aid
)
returning id into nid;

if coalesce(p_all_stores,false) then

insert into public.kinto_admin_notification_recipients(
notification_id,
store_id
)
select
nid,
s.id::text
from public.local_stores s
on conflict do nothing;

else

insert into public.kinto_admin_notification_recipients(
notification_id,
store_id
)
select
nid,
s.id::text
from public.local_stores s
where s.id::text=any(p_store_ids)
on conflict do nothing;

end if;

get diagnostics cnt=row_count;

if cnt=0 then
raise exception 'no valid recipients';
end if;

return jsonb_build_object(
'ok',true,
'notification_id',nid,
'recipients',cnt
);
end
$function$

CREATE OR REPLACE FUNCTION public.admin_reject_featured_request(p_admin_id uuid, p_request_id uuid, p_admin_note text DEFAULT NULL::text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
begin
if not public.meshwar_is_admin(p_admin_id) then
raise exception 'not authorized';
end if;

update public.merchant_featured_requests
set status='rejected',reviewed_by=p_admin_id,reviewed_at=now(),
admin_note=nullif(trim(p_admin_note),''),updated_at=now()
where id=p_request_id and status='pending';

if not found then raise exception 'pending request not found'; end if;
return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.require_customer_review_session(p_session_token text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
begin
if trim(coalesce(p_session_token, '')) = '' then
raise exception 'REVIEW_SESSION_REQUIRED';
end if;

select s.customer_id
into v_customer_id
from public.customer_review_sessions s
where s.token_hash = digest(p_session_token, 'sha256')
and s.revoked_at is null
and s.expires_at > now()
limit 1;

if v_customer_id is null then
raise exception 'REVIEW_SESSION_INVALID';
end if;

update public.customer_review_sessions
set last_seen_at = now()
where token_hash = digest(p_session_token, 'sha256');

return v_customer_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_local_cart_bundle_guard_v94_legacy()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
declare
old_d jsonb := '{}'::jsonb;
new_d jsonb := '{}'::jsonb;
begin
-- Parse the TEXT details column once. Invalid/legacy text must never block an
-- operational status/shipping/payment update.
begin
if old.details is not null and btrim(old.details::text) <> '' then
old_d := old.details::jsonb;
end if;
exception when others then
return new;
end;

if coalesce(old_d->>'source', '') <> 'local_cart_bundle' then
return new;
end if;

begin
if new.details is not null and btrim(new.details::text) <> '' then
new_d := new.details::jsonb;
end if;
exception when others then
-- If a dashboard did not provide valid JSON details, preserve the submitted
-- bundle details instead of failing the whole operational update.
new_d := old_d;
end;

-- Preserve only immutable submitted bundle identity/product fields.
-- IMPORTANT: no JSON existence operator (?) is ever applied to orders.details.
new_d := jsonb_set(new_d, '{source}', coalesce(old_d->'source', '"local_cart_bundle"'::jsonb), true);
new_d := jsonb_set(new_d, '{items}', coalesce(old_d->'items', '[]'::jsonb), true);

if (old_d->'quantity') is not null then
new_d := jsonb_set(new_d, '{quantity}', old_d->'quantity', true);
end if;
if (old_d->'requested_quantity') is not null then
new_d := jsonb_set(new_d, '{requested_quantity}', old_d->'requested_quantity', true);
end if;
if (old_d->'item_count') is not null then
new_d := jsonb_set(new_d, '{item_count}', old_d->'item_count', true);
end if;
if (old_d->'bundle_id') is not null then
new_d := jsonb_set(new_d, '{bundle_id}', old_d->'bundle_id', true);
end if;
if (old_d->'bundle_version') is not null then
new_d := jsonb_set(new_d, '{bundle_version}', old_d->'bundle_version', true);
end if;
if (old_d->'store_id') is not null then
new_d := jsonb_set(new_d, '{store_id}', old_d->'store_id', true);
end if;
if (old_d->'customer_scope_id') is not null then
new_d := jsonb_set(new_d, '{customer_scope_id}', old_d->'customer_scope_id', true);
end if;
if (old_d->'customer_scope_type') is not null then
new_d := jsonb_set(new_d, '{customer_scope_type}', old_d->'customer_scope_type', true);
end if;
if (old_d->'submitted_at') is not null then
new_d := jsonb_set(new_d, '{submitted_at}', old_d->'submitted_at', true);
end if;

-- Cast back to the physical column type through assignment. Status, shipping,
-- payment, branch, parcel and all non-immutable metadata remain untouched.
new.details := new_d::text;
return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.kinto_deals_v1_inject_gift_g5f()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_campaign_id uuid;
v_customer_id uuid;
v_c public.kinto_deals_v1_campaigns%rowtype;
v_d jsonb;
v_paid jsonb;
v_gift jsonb;
v_units integer;
v_distinct integer;
v_existing integer;
v_gift_stock integer;
begin
if nullif(current_setting('app.kinto_deals_gift_campaign_id',true),'') is null then
return new;
end if;
-- Only a trusted, verified future wrapper may set this transaction-local context.
if not coalesce((select enabled from public.kinto_deals_v1_flags
where key='merchant_deals_enabled'),false) then
raise exception 'DEALS_FEATURE_DISABLED' using errcode='P0001';end if;
v_campaign_id:=private.v94_uuid(current_setting('app.kinto_deals_gift_campaign_id',true));
v_customer_id:=private.v94_uuid(current_setting('app.kinto_deals_verified_customer_id',true));
if v_campaign_id is null or v_customer_id is null
or new.customer_id is distinct from v_customer_id::text then
raise exception 'DEALS_GIFT_CONTEXT_INVALID' using errcode='28000';end if;
v_d:=coalesce(nullif(new.details,'')::jsonb,'{}'::jsonb);
if v_d->>'source'<>'local_cart_bundle'
or v_d->>'checkout_contract'<>'independent_vendor_orders' then
raise exception 'DEALS_GIFT_ORDER_CONTRACT_INVALID' using errcode='P0001';end if;
select * into v_c from public.kinto_deals_v1_campaigns
where id=v_campaign_id;
if not found then raise exception 'DEALS_GIFT_CAMPAIGN_NOT_FOUND' using errcode='P0001';end if;
-- Multi-store canonical checkout: inject into the owning store order ONLY.
if v_d->>'store_id' is distinct from v_c.store_id::text then return new;end if;
if v_c.gift_product_id is null or v_c.kind not in ('choose_n','buy_n')
or v_c.status<>'submitted'
or v_c.starts_at>statement_timestamp() or v_c.ends_at<=statement_timestamp()
or not exists (
select 1 from public.kinto_deals_v1_submissions sub
join public.kinto_deals_v1_review_events ev
on ev.submission_id=sub.id and ev.campaign_id=v_c.id
and ev.store_id=v_c.store_id and ev.decision='approved'
where sub.campaign_id=v_c.id and sub.review_state='acknowledged'
and sub.id=(select s.id from public.kinto_deals_v1_submissions s
where s.campaign_id=v_c.id order by s.submitted_at desc,s.id desc limit 1))
then raise exception 'DEALS_GIFT_CAMPAIGN_NOT_APPROVED_ACTIVE' using errcode='P0001';end if;
v_paid:=v_d->'items';
if jsonb_typeof(v_paid)<>'array' or jsonb_array_length(v_paid)<1
or exists(select 1 from jsonb_array_elements(v_paid) x
where coalesce(x->>'is_deal_gift','false')='true'
or private.v94_uuid(x->>'product_id') is null
or private.v94_numeric(x->>'quantity',0)<1) then
raise exception 'DEALS_GIFT_PAID_ITEMS_INVALID' using errcode='22023';end if;
select coalesce(sum((x->>'quantity')::integer),0)::integer,
count(distinct (x->>'product_id')::uuid)::integer
into v_units,v_distinct from jsonb_array_elements(v_paid) x
where exists(select 1 from public.kinto_deals_v1_products cp
where cp.campaign_id=v_c.id and cp.product_id=private.v94_uuid(x->>'product_id'));
if (v_c.kind='choose_n' and v_distinct<v_c.threshold_units)
or (v_c.kind='buy_n' and v_units<v_c.threshold_units) then
raise exception 'DEALS_GIFT_THRESHOLD_NOT_MET' using errcode='P0001';end if;
-- Check combined paid+gift quantity, including when gift product is also paid.
select coalesce(sum((x->>'quantity')::integer),0)::integer into v_existing
from jsonb_array_elements(v_paid) x
where private.v94_uuid(x->>'product_id')=v_c.gift_product_id;
select stock_quantity into v_gift_stock from public.local_products
where id=v_c.gift_product_id and store_id=v_c.store_id for update;
if not found or (v_gift_stock is not null and v_gift_stock<v_existing+1) then
raise exception 'DEALS_GIFT_COMBINED_STOCK_INSUFFICIENT' using errcode='P0001';end if;
v_gift:=private.kinto_deals_v1_gift_line_g5e(v_c.id,v_c.store_id);
new.details:=(v_d||jsonb_build_object(
'items',v_paid||jsonb_build_array(v_gift),
'deal_campaign_id',v_c.id,
'deal_gift_snapshot',v_gift,
'deal_gift_net_local',0,
'deal_gift_discount_local',v_gift->'gift_discount_local',
'deal_gift_original_local',v_gift->'gift_original_unit_price_local',
'deal_gift_insert_contract','g5f_before_insert_v1'
))::text;
-- Canonical paid subtotal/total are deliberately unchanged. Existing V93 payment
-- stock lifecycle will see this gift as one additional quantity exactly once.
return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_hero_upload(p_admin_id uuid, p_file_name text, p_mime_type text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
v_token uuid := gen_random_uuid();
v_mime text := lower(trim(coalesce(p_mime_type, '')));
v_ext text;
v_object_name text;
v_expires_at timestamptz := now() + interval '15 minutes';
begin
if p_admin_id is null or not public.meshwar_is_admin(p_admin_id) then
raise exception 'not authorized';
end if;

v_ext := case v_mime
when 'image/jpeg' then 'jpg'
when 'image/png' then 'png'
when 'image/webp' then 'webp'
when 'image/gif' then 'gif'
when 'video/mp4' then 'mp4'
when 'video/webm' then 'webm'
when 'video/quicktime' then 'mov'
else null
end;

if v_ext is null then
raise exception 'unsupported hero media mime type: %', v_mime;
end if;

-- Keep only live tickets; uploaded objects themselves remain immutable because
-- CMS uses unique names with upsert=false and no UPDATE storage policy exists.
delete from public.hero_upload_tokens where expires_at <= now();

v_object_name := 'hero/' || v_token::text || '.' || v_ext;

insert into public.hero_upload_tokens(token, admin_id, object_name, mime_type, expires_at)
values (v_token, p_admin_id, v_object_name, v_mime, v_expires_at);

return jsonb_build_object(
'bucket', 'site-hero-media',
'path', v_object_name,
'mime_type', v_mime,
'expires_at', v_expires_at,
'max_bytes', 104857600,
'original_name', left(coalesce(p_file_name, ''), 255)
);
end;
$function$

