LANGUAGE plpgsql
AS $function$
BEGIN
NEW.updated_at = NOW();
RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.vendor_save_shipping_settings(p_session_token text, p_expected_version bigint, p_is_active boolean, p_default_currency text, p_companies jsonb, p_rates jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store_id uuid := private.require_vendor_session(p_session_token);
v_profile public.vendor_shipping_profiles%rowtype;
v_company jsonb;
v_rate jsonb;
v_company_key text;
v_company_id uuid;
v_company_map jsonb := '{}'::jsonb;
v_currency text := upper(trim(coalesce(p_default_currency, '')));
begin
if jsonb_typeof(coalesce(p_companies, '[]'::jsonb)) <> 'array'
or jsonb_typeof(coalesce(p_rates, '[]'::jsonb)) <> 'array' then
raise exception 'SHIPPING_SETTINGS_ARRAYS_REQUIRED' using errcode = '22023';
end if;
if jsonb_array_length(coalesce(p_companies, '[]'::jsonb)) > 30
or jsonb_array_length(coalesce(p_rates, '[]'::jsonb)) > 300 then
raise exception 'SHIPPING_SETTINGS_LIMIT_EXCEEDED' using errcode = '22023';
end if;
if v_currency !~ '^[A-Z]{3,5}$' then
raise exception 'SHIPPING_CURRENCY_INVALID' using errcode = '22023';
end if;
if coalesce(p_is_active, false)
and (jsonb_array_length(coalesce(p_companies, '[]'::jsonb)) = 0
or jsonb_array_length(coalesce(p_rates, '[]'::jsonb)) = 0) then
raise exception 'ACTIVE_SHIPPING_REQUIRES_COMPANY_AND_RATE' using errcode = '22023';
end if;

insert into public.vendor_shipping_profiles(store_id, is_active, default_currency)
values (v_store_id, false, v_currency)
on conflict (store_id) do nothing;

select * into v_profile
from public.vendor_shipping_profiles
where store_id = v_store_id
for update;

if v_profile.version <> coalesce(p_expected_version, -1) then
raise exception 'SHIPPING_SETTINGS_VERSION_CONFLICT' using errcode = '40001';
end if;

delete from public.vendor_shipping_rates where store_id = v_store_id;
delete from public.vendor_shipping_companies where store_id = v_store_id;

for v_company in
select value from jsonb_array_elements(coalesce(p_companies, '[]'::jsonb))
loop
v_company_key := nullif(trim(v_company ->> 'key'), '');
if v_company_key is null
or nullif(trim(v_company ->> 'company_name'), '') is null
or v_company_map ? v_company_key then
raise exception 'SHIPPING_COMPANY_INVALID_OR_DUPLICATE' using errcode = '22023';
end if;
v_company_id := gen_random_uuid();
insert into public.vendor_shipping_companies(
id, store_id, company_name, phone, tracking_url, is_active, sort_order
) values (
v_company_id,
v_store_id,
trim(v_company ->> 'company_name'),
nullif(trim(v_company ->> 'phone'), ''),
nullif(trim(v_company ->> 'tracking_url'), ''),
coalesce((v_company ->> 'is_active')::boolean, true),
greatest(0, private.v94_numeric(v_company ->> 'sort_order', 0)::integer)
);
v_company_map := v_company_map || jsonb_build_object(v_company_key, v_company_id::text);
end loop;

for v_rate in
select value from jsonb_array_elements(coalesce(p_rates, '[]'::jsonb))
loop
v_company_key := nullif(trim(v_rate ->> 'company_key'), '');
if v_company_key is null or not (v_company_map ? v_company_key) then
raise exception 'SHIPPING_RATE_COMPANY_INVALID' using errcode = '22023';
end if;
if nullif(trim(v_rate ->> 'governorate'), '') is null
or private.v94_numeric(v_rate ->> 'delivery_fee', -1) < 0 then
raise exception 'SHIPPING_RATE_INVALID' using errcode = '22023';
end if;
v_currency := upper(trim(coalesce(nullif(v_rate ->> 'currency', ''), p_default_currency)));
if v_currency !~ '^[A-Z]{3,5}$' then
raise exception 'SHIPPING_RATE_CURRENCY_INVALID' using errcode = '22023';
end if;

insert into public.vendor_shipping_rates(
store_id, company_id, destination_country, governorate, area,
delivery_fee, currency, estimated_days_min, estimated_days_max,
priority, is_active
) values (
v_store_id,
(v_company_map ->> v_company_key)::uuid,
coalesce(nullif(trim(v_rate ->> 'destination_country'), ''), '*'),
trim(v_rate ->> 'governorate'),
coalesce(nullif(trim(v_rate ->> 'area'), ''), '*'),
private.v94_numeric(v_rate ->> 'delivery_fee', 0),
v_currency,
case when nullif(v_rate ->> 'estimated_days_min', '') is null then null else greatest(0, private.v94_numeric(v_rate ->> 'estimated_days_min', 0)::integer) end,
case when nullif(v_rate ->> 'estimated_days_max', '') is null then null else greatest(0, private.v94_numeric(v_rate ->> 'estimated_days_max', 0)::integer) end,
private.v94_numeric(v_rate ->> 'priority', 0)::integer,
coalesce((v_rate ->> 'is_active')::boolean, true)
);
end loop;

update public.vendor_shipping_profiles
set is_active = coalesce(p_is_active, false),
default_currency = upper(trim(p_default_currency)),
version = version + 1,
updated_at = now()
where store_id = v_store_id;

return private.v98_vendor_shipping_settings(v_store_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_logout_session(p_session_token text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_token_hash bytea;
begin
if coalesce(p_session_token, '') = '' then
return;
end if;

v_token_hash := digest(
p_session_token,
'sha256'
);

update public.vendor_sessions
set revoked_at = coalesce(
revoked_at,
now()
)
where token_hash = v_token_hash;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_kinto_campaign_status_v400(p_session_token text, p_campaign_id uuid, p_status text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
aid text;
s text;
begin
aid:=private.require_admin_session_v147(p_session_token);

if coalesce(aid,'')='' then
raise exception 'invalid admin session';
end if;

s:=lower(trim(coalesce(p_status,'')));

if s not in('active','paused','cancelled') then
raise exception 'invalid campaign status';
end if;

update public.kinto_campaigns
set status=s
where id=p_campaign_id;

if not found then
raise exception 'campaign not found';
end if;

return jsonb_build_object(
'ok',true,
'campaign_id',p_campaign_id,
'status',s
);
end
$function$

CREATE OR REPLACE FUNCTION public.customer_create_review_image_upload_v150(p_session_token text, p_review_id uuid, p_mime_type text, p_byte_size integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'storage', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
v_review public.product_reviews%rowtype;
v_ticket private.product_review_upload_tickets_v150%rowtype;
v_ext text;
v_max_images smallint;
begin
v_customer_id :=
private.require_customer_review_session(p_session_token);

if p_mime_type not in (
'image/jpeg',
'image/png',
'image/webp'
) then
raise exception 'IMAGE_TYPE_NOT_ALLOWED';
end if;

if coalesce(p_byte_size, 0) not between 12 and 51200 then
raise exception 'IMAGE_SIZE_NOT_ALLOWED';
end if;

perform pg_advisory_xact_lock(
hashtextextended(p_review_id::text, 150)
);

select *
into v_review
from public.product_reviews
where id = p_review_id
and customer_id = v_customer_id
for update;

if v_review.id is null then
raise exception 'REVIEW_NOT_FOUND';
end if;

if v_review.moderation_status not in ('pending','rejected') then
raise exception 'REVIEW_IMAGES_LOCKED';
end if;

select coalesce(max_images, 1)
into v_max_images
from private.product_review_media_policy_v149
where singleton;

if (
select count(*)
from public.product_review_images
where review_id = p_review_id
) + (
select count(*)
from private.product_review_upload_tickets_v150
where review_id = p_review_id
and used_at is null
and expires_at > now()
) >= v_max_images then
raise exception 'REVIEW_IMAGE_LIMIT_REACHED';
end if;

delete from private.product_review_upload_tickets_v150
where expires_at <= now();

v_ext :=
case p_mime_type
when 'image/webp' then 'webp'
when 'image/png' then 'png'
else 'jpg'
end;

insert into private.product_review_upload_tickets_v150 (
review_id,
customer_id,
storage_path,
mime_type,
byte_size
)
values (
p_review_id,
v_customer_id,
'reviews/'
|| p_review_id::text
|| '/'
|| gen_random_uuid()::text
|| '.'
|| v_ext,
p_mime_type,
p_byte_size
)
returning *
into v_ticket;

return jsonb_build_object(
'ok', true,
'ticket_id', v_ticket.id,
'bucket', 'product-review-images',
'storage_path', v_ticket.storage_path,
'expires_at', v_ticket.expires_at
);
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_notification_read_state_v155(p_session_token text, p_notification_keys text[])
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_customer uuid;
v_keys text[];
v_unread integer;
begin
v_customer :=
private.require_customer_review_session(p_session_token);

select coalesce(
array_agg(distinct k),
array[]::text[]
)
into v_keys
from unnest(
coalesce(p_notification_keys, array[]::text[])
) k
where char_length(k) between 3 and 500;

if cardinality(v_keys) > 100 then
raise exception 'TOO_MANY_NOTIFICATION_KEYS';
end if;

select count(*)::integer
into v_unread
from unnest(v_keys) k
where not exists (
select 1
from public.customer_notification_reads_v155 r
where r.customer_id = v_customer
and r.notification_key = k
);

return jsonb_build_object(
'unread_count', v_unread,
'total_count', cardinality(v_keys)
);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_login_session(p_identity text, p_password text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_store_id uuid;
v_store public.local_stores%rowtype;
v_token text;
v_expires_at timestamptz := now() + interval '12 hours';
begin
if trim(coalesce(p_identity, '')) = ''
or coalesce(p_password, '') = '' then
raise exception 'بيانات الدخول غير مكتملة'
using errcode = '28000';
end if;

-- استخدام دالة الدخول القديمة المستقرة للتحقق من الحساب.
select authenticated_store.id
into v_store_id
from public.vendor_login(
trim(p_identity),
p_password
) authenticated_store
limit 1;

if v_store_id is null then
raise exception 'بيانات الدخول غير صحيحة أو المتجر غير نشط'
using errcode = '28000';
end if;

select s.*
into v_store
from public.local_stores s
where s.id = v_store_id
and lower(trim(coalesce(s.status, ''))) = 'active'
limit 1;

if v_store.id is null then
raise exception 'بيانات الدخول غير صحيحة أو المتجر غير نشط'
using errcode = '28000';
end if;

-- تنظيف الجلسات المنتهية أو الملغاة.
delete from public.vendor_sessions
where expires_at <= now()
or revoked_at is not null;

-- إنشاء رمز جلسة آمن.
v_token := encode(gen_random_bytes(32), 'hex');

insert into public.vendor_sessions(
store_id,
token_hash,
expires_at
)
values (
v_store.id,
digest(v_token, 'sha256'),
v_expires_at
);

return jsonb_build_object(
'session_token', v_token,
'expires_at', v_expires_at,
'store', jsonb_build_object(
'id', v_store.id,
'store_name', v_store.store_name,
'logo_url', v_store.logo_url,
'username', v_store.username,
'phone', v_store.phone,
'country', v_store.country,
'governorate', v_store.governorate,
'store_type', v_store.store_type,
'specialty', v_store.specialty,
'default_currency', v_store.default_currency,
'commission_rate', v_store.commission_rate,
'status', v_store.status,
'exchange_rate', v_store.exchange_rate,
'exchange_base_currency',
v_store.exchange_base_currency,
'exchange_target_currency',
v_store.exchange_target_currency
)
);
end;
$function$

CREATE OR REPLACE FUNCTION private.v101_location_key(p_value text)
RETURNS text
LANGUAGE plpgsql
IMMUTABLE
AS $function$
declare
v text := lower(trim(coalesce(p_value, '')));
begin
if v = '*' then return '*'; end if;
v := trim(both '*' from v);
v := replace(replace(replace(replace(v, 'أ', 'ا'), 'إ', 'ا'), 'آ', 'ا'), 'ٱ', 'ا');
v := replace(replace(replace(replace(v, 'ى', 'ي'), 'ة', 'ه'), 'ؤ', 'و'), 'ئ', 'ي');
v := regexp_replace(v, '[ًٌٍَُِّْـ]', '', 'g');
return regexp_replace(v, '[[:space:]_\-،,./]+', '', 'g');
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_request_settlements_session_v1(p_role text, p_session_token text, p_type text, p_branch_id text, p_courier_id text, p_order_ids uuid[], p_basis text DEFAULT 'collection'::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; bid text; entry public.orders%rowtype; locked jsonb:='[]'; bucket record; sid bigint; result jsonb:='[]'; n integer:=0;
BEGIN
actor:=private.kinto_settlement_actor_v1(p_role,p_session_token);
bid:=CASE WHEN p_role='branch' THEN actor->>'id' ELSE nullif(btrim(p_branch_id),'') END;
IF bid IS NULL OR (p_role='branch' AND p_branch_id IS DISTINCT FROM bid) THEN RAISE EXCEPTION 'SETTLEMENT_BRANCH_DENIED'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.branches b WHERE b.id::text=bid) THEN RAISE EXCEPTION 'SETTLEMENT_BRANCH_NOT_FOUND'; END IF;
IF p_type IS NULL OR p_type NOT IN ('branch','courier') OR p_basis IS NULL OR p_basis NOT IN ('collection','legacy_goods')
OR (p_basis='legacy_goods' AND (p_role<>'admin' OR p_type<>'courier')) THEN RAISE EXCEPTION 'SETTLEMENT_REQUEST_INVALID'; END IF;
IF (p_type='branch' AND p_courier_id IS NOT NULL) OR (p_type='courier' AND NOT EXISTS(SELECT 1 FROM public.couriers c WHERE c.id::text=p_courier_id AND c.branch_id::text=bid)) THEN RAISE EXCEPTION 'SETTLEMENT_COURIER_DENIED'; END IF;
IF coalesce(cardinality(p_order_ids),0) NOT BETWEEN 1 AND 10000 OR (SELECT count(DISTINCT x) FROM unnest(p_order_ids) x)<>cardinality(p_order_ids) THEN RAISE EXCEPTION 'SETTLEMENT_ORDER_IDS_INVALID'; END IF;
FOR entry IN SELECT * FROM public.orders WHERE id=ANY(p_order_ids) ORDER BY id FOR UPDATE LOOP
IF entry.branch_id IS DISTINCT FROM bid OR entry.status IS DISTINCT FROM 'تم التسليم'
OR entry.settlement_id IS NOT NULL OR (p_type='courier' AND entry.courier_id IS DISTINCT FROM p_courier_id) THEN RAISE EXCEPTION 'SETTLEMENT_ORDER_NOT_ELIGIBLE'; END IF;
IF entry.total_price::text IN ('NaN','Infinity','-Infinity') OR entry.delivery_fee::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'SETTLEMENT_AMOUNT_INVALID'; END IF;
locked:=locked||jsonb_build_array(to_jsonb(entry));n:=n+1;
END LOOP;
IF n<>cardinality(p_order_ids) THEN RAISE EXCEPTION 'SETTLEMENT_ORDER_NOT_FOUND'; END IF;
FOR bucket IN SELECT coalesce(nullif(r->>'currency',''),'$') currency,sum(a.gross) gross,sum(a.fee) fee,sum(a.net) net,
array_agg((r->>'id')::uuid ORDER BY r->>'id') ids FROM jsonb_array_elements(locked) r
CROSS JOIN LATERAL private.kinto_settlement_amounts_v1((r->>'total_price')::numeric,(r->>'delivery_fee')::numeric,r->>'delivery_payment_type',p_basis) a GROUP BY 1 ORDER BY 1 LOOP
INSERT INTO public.settlements(settlement_type,branch_id,courier_id,gross_amount,delivery_fee,net_amount,currency,order_ids,status,requested_by,requested_at,calculation_basis)
VALUES(p_type,bid,p_courier_id,bucket.gross,bucket.fee,bucket.net,bucket.currency,to_jsonb(bucket.ids),'pending',p_role||':'||(actor->>'id'),now(),p_basis) RETURNING id INTO sid;
UPDATE public.orders SET settlement_id=sid,settlement_status='pending' WHERE id=ANY(bucket.ids);
result:=result||jsonb_build_array(jsonb_build_object('id',sid,'currency',bucket.currency,'order_count',cardinality(bucket.ids)));
END LOOP;
RETURN jsonb_build_object('ok',true,'created',jsonb_array_length(result),'settlements',result,'order_count',n);
END $function$

CREATE OR REPLACE FUNCTION public.kinto_vendor_legacy_status_session_v1(p_session_token text, p_order_id uuid, p_next_status text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE sid text:=private.require_vendor_session(p_session_token)::text; o public.orders%ROWTYPE; d jsonb;
BEGIN
IF p_next_status IS NULL OR p_next_status NOT IN ('مخزن الشركة','تجهيز شحن','محولة إلى الفرع','تم الشحن','مخزن محلي','مندوب','توزيع داخلي','تم التسليم','رفض التسليم','مرفوض') THEN RAISE EXCEPTION 'VENDOR_STATUS_DENIED'; END IF;
SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;d:=private.v94_jsonb_object(to_jsonb(o.details));
IF NOT FOUND OR d->>'source' IS DISTINCT FROM 'local_cart_bundle'
OR NOT (coalesce(d->>'bundle_stock_lifecycle_state','')='deducted' OR o.status='تم التسديد')
OR NOT EXISTS(SELECT FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'items')='array' THEN d->'items' ELSE '[]'::jsonb END) i WHERE i->>'store_id'=sid) THEN
RAISE EXCEPTION 'VENDOR_ORDER_DENIED' USING ERRCODE='42501'; END IF;
d:=jsonb_set(d,'{store_statuses}',coalesce(d->'store_statuses','{}'::jsonb)||jsonb_build_object(sid,p_next_status));
UPDATE public.orders SET details=d::text WHERE id=o.id;
END $function$

CREATE OR REPLACE FUNCTION public.kinto_loyalty_order_v310()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
c text;
sid text;
r numeric;
x numeric;
whole bigint;
carry numeric;
enabled boolean;
fund text;
vendor_points numeric:=0;
kinto_points numeric:=0;
begin

sid:=public.kinto_order_store_id_v310(new);
c:=public.kinto_normalize_currency_v310(new.currency);

if new.status='تم التسليم'
and coalesce(old.status,'')<>'تم التسليم'
and sid is not null
and coalesce(new.total_price,0)>0
and not exists(
select 1
from public.kinto_loyalty_ledger
where order_id=new.id::text
and store_id=sid
and event_type='earn'
)
then
begin

insert into public.kinto_store_loyalty_settings(store_id)
values(sid)
on conflict do nothing;

select s.enabled,s.earn_rate
into enabled,r
from public.kinto_store_loyalty_settings s
where s.store_id=sid;

if enabled
and coalesce(r,0)>0
and new.customer_id is not null
then

insert into public.kinto_loyalty_wallets(
customer_id,
store_id,
currency
)
values(
new.customer_id::text,
sid,
c
)
on conflict do nothing;

select fractional_carry
into carry
from public.kinto_loyalty_wallets
where customer_id=new.customer_id::text
and store_id=sid
and currency=c
for update;

x:=coalesce(new.total_price,0)*r
+coalesce(carry,0);

whole:=floor(x);
carry:=x-whole;

perform public.kinto_credit_points_v310(
new.customer_id::text,
sid,
c,
whole,
carry,
new.id::text
);

insert into public.kinto_loyalty_ledger(
customer_id,
store_id,
order_id,
event_type,
points,
currency,
earn_rate_snapshot,
eligible_product_total,
note
)
values(
new.customer_id::text,
sid,
new.id::text,
'earn',
whole,
c,
r,
new.total_price,
'delivered_store_order'
);

new.loyalty_points_earned:=whole;

end if;

exception when others then

raise warning
'KINTO_V310_EARN_SKIPPED order=% error=%',
new.id,
sqlerrm;

end;
end if;


if coalesce(new.status,'') in(
'ملغي',
'ملغي من قبل العميل',
'رفض الطلب',
'مرفوض'
)
and coalesce(old.status,'') not in(
'ملغي',
'ملغي من قبل العميل',
'رفض الطلب',
'مرفوض'
)
and coalesce(new.loyalty_points_redeemed,0)>0
and sid is not null
and not exists(
select 1
from public.kinto_loyalty_ledger
where order_id=new.id::text
and store_id=sid
and event_type='restore'
)
then
begin

fund:=lower(
trim(
coalesce(
new.reward_discount_snapshot->>'funded_by',
''
)
)
);

if fund not in('vendor','kinto','mixed') then
fund:=null;
end if;

if coalesce(
new.reward_discount_snapshot->>'vendor_points',
''
) ~ '^\s*[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)\s*$'
then
vendor_points:=
(new.reward_discount_snapshot->>'vendor_points')::numeric;
else
vendor_points:=0;
end if;

if coalesce(
new.reward_discount_snapshot->>'kinto_points',
''
) ~ '^\s*[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)\s*$'
then
kinto_points:=
(new.reward_discount_snapshot->>'kinto_points')::numeric;
else
kinto_points:=0;
end if;

update public.kinto_loyalty_coupons
set
status='active',
used_order_id=null,
used_at=null
where used_order_id=new.id::text
and status='used'
and (
campaign_id is not null
or store_id=sid
);

insert into public.kinto_loyalty_ledger(
customer_id,
store_id,
order_id,
event_type,
points,
currency,
note,
funded_by,
funding_snapshot
)
values(
new.customer_id::text,
sid,
new.id::text,
'restore',
new.loyalty_points_redeemed,
coalesce(
new.reward_discount_currency,
c
),
'cancelled_order_original_expiry_restored',
fund,
jsonb_build_object(
'vendor_points',vendor_points,
'kinto_points',kinto_points,
'coupon_ids',
coalesce(
new.reward_discount_snapshot->'coupon_ids',
'[]'::jsonb
),
'restored_original_expiry',true
)
);

new.loyalty_points_redeemed:=0;
new.reward_discount_amount:=0;
new.reward_discount_currency:=null;
new.reward_discount_snapshot:='{}'::jsonb;

exception when others then

raise warning
'KINTO_V310_RESTORE_SKIPPED order=% error=%',
new.id,
sqlerrm;

end;
end if;

return new;
end $function$

CREATE OR REPLACE FUNCTION private.kinto_deals_v1_unavailable_reason_g21(p_campaign_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
c public.kinto_deals_v1_campaigns%rowtype;
cp record;
p public.local_products%rowtype;
probe jsonb;
opts jsonb;
used_count bigint;
gift_is_campaign_product boolean;
begin
select * into c from public.kinto_deals_v1_campaigns where id=p_campaign_id;
if not found then return jsonb_build_object('code','missing_campaign'); end if;

if c.ends_at<=statement_timestamp() then
return jsonb_build_object('code','time_expired');
end if;

if c.max_total_redemptions is not null then
select count(*) into used_count
from public.kinto_deals_v1_redemptions r
where r.campaign_id=c.id and r.state in ('pending','confirmed');
if used_count>=c.max_total_redemptions then
return jsonb_build_object('code','quota_exhausted');
end if;
end if;

for cp in
select x.product_id,x.selected_options,lp.product_name
from public.kinto_deals_v1_products x
left join public.local_products lp on lp.id=x.product_id and lp.store_id=c.store_id
where x.campaign_id=c.id
order by x.product_id
loop
select * into p from public.local_products
where id=cp.product_id and store_id=c.store_id;

if not found or coalesce(p.is_out_of_stock,false)
or (p.stock_quantity is not null and p.stock_quantity<1) then
return jsonb_build_object(
'code','product_out_of_stock',
'product_id',cp.product_id,
'product_name',cp.product_name
);
end if;

probe:=jsonb_build_object(
'color',coalesce(cp.selected_options->>'color',''),
'size',coalesce(cp.selected_options->>'size',''),
'volume',coalesce(cp.selected_options->>'volume','')
);

begin
opts:=public.meshwar_adjust_variant_stock(
coalesce(p.options,'{}'::jsonb),probe,1,-1
);
opts:=public.meshwar_adjust_matrix_stock(opts,probe,1,-1);
exception when others then
return jsonb_build_object(
'code','product_variant_out_of_stock',
'product_id',cp.product_id,
'product_name',cp.product_name
);
end;
end loop;

if c.gift_product_id is not null then
select * into p from public.local_products
where id=c.gift_product_id and store_id=c.store_id;

select exists(
select 1
from public.kinto_deals_v1_products x
where x.campaign_id=c.id
and x.product_id=c.gift_product_id
) into gift_is_campaign_product;

if not found or coalesce(p.is_out_of_stock,false)
or (
p.stock_quantity is not null
and p.stock_quantity <
case when gift_is_campaign_product then 2 else 1 end
) then
return jsonb_build_object(
'code','gift_out_of_stock',
'product_id',c.gift_product_id,
'product_name',p.product_name
);
end if;

probe:=jsonb_build_object(
'color',coalesce(c.gift_selected_options->>'color',''),
'size',coalesce(c.gift_selected_options->>'size',''),
'volume',coalesce(c.gift_selected_options->>'volume','')
);

begin
opts:=public.meshwar_adjust_variant_stock(
coalesce(p.options,'{}'::jsonb),
probe,
case when gift_is_campaign_product then 2 else 1 end,
-1
);
opts:=public.meshwar_adjust_matrix_stock(
opts,
probe,
case when gift_is_campaign_product then 2 else 1 end,
-1
);
exception when others then
return jsonb_build_object(
'code','gift_variant_out_of_stock',
'product_id',c.gift_product_id,
'product_name',p.product_name
);
end;
end if;

return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_settlements_directory_session_v1(p_role text, p_session_token text, p_table text, p_filters jsonb DEFAULT '[]'::jsonb, p_order text DEFAULT 'id'::text, p_ascending boolean DEFAULT true, p_limit integer DEFAULT 2000, p_offset integer DEFAULT 0)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; base_sql text; where_sql text:='true'; order_sql text; direction text; f jsonb; field text; op text; result jsonb;
allowed text[]:=ARRAY['id','branch_id','courier_id','status','settlement_type','currency','requested_at','created_at'];
BEGIN
actor:=private.kinto_settlement_actor_v1(p_role,p_session_token);
IF p_table='settlements' THEN base_sql:='SELECT to_jsonb(s) doc FROM public.settlements s';
ELSIF p_table='delivery_settlements' THEN
base_sql:='SELECT to_jsonb(s)||jsonb_build_object(''courier_id'',coalesce(s.courier_id,c.id::text,s.delivery_agent_id::text),''courier_name'',coalesce(s.courier_name,c.name),''branch_name'',coalesce(s.branch_name,b.name),''amount'',s.net_submitted_amount,''net_amount'',s.net_submitted_amount,''order_count'',s.orders_count,''settled_at'',s.created_at) doc FROM public.delivery_settlements s LEFT JOIN LATERAL (SELECT x.id,x.name FROM public.couriers x WHERE x.courier_uuid=s.delivery_agent_id ORDER BY x.id LIMIT 1) c ON true LEFT JOIN public.branches b ON b.id=s.branch_id';
ELSE RAISE EXCEPTION 'SETTLEMENT_DIRECTORY_TABLE_INVALID'; END IF;
IF p_role='branch' THEN where_sql:=format('doc->>''branch_id''=%L',actor->>'id'); END IF;
IF p_filters IS NULL OR jsonb_typeof(p_filters)<>'array' OR jsonb_array_length(p_filters)>32 OR p_order IS NULL OR NOT p_order=ANY(allowed)
OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 10000 OR p_offset IS NULL OR p_offset NOT BETWEEN 0 AND 10000000 THEN RAISE EXCEPTION 'SETTLEMENT_DIRECTORY_QUERY_INVALID'; END IF;
FOR f IN SELECT value FROM jsonb_array_elements(p_filters) LOOP
field:=f->>'field';op:=f->>'op';
IF field IS NULL OR NOT field=ANY(allowed) OR op IS NULL OR op NOT IN ('eq','in','gte','lte') THEN RAISE EXCEPTION 'SETTLEMENT_DIRECTORY_FILTER_INVALID'; END IF;
IF op='in' THEN
IF jsonb_typeof(f->'value') IS DISTINCT FROM 'array' OR jsonb_array_length(f->'value')>10000 THEN RAISE EXCEPTION 'SETTLEMENT_DIRECTORY_FILTER_INVALID'; END IF;
where_sql:=where_sql||format(' AND doc->>%L IN (SELECT jsonb_array_elements_text(%L::jsonb))',field,(f->'value')::text);
ELSIF op IN ('gte','lte') THEN
IF field NOT IN ('requested_at','created_at') OR jsonb_typeof(f->'value') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'SETTLEMENT_DIRECTORY_FILTER_INVALID'; END IF;
where_sql:=where_sql||format(' AND (doc->>%L)::timestamptz %s %L::timestamptz',field,CASE WHEN op='gte' THEN '>=' ELSE '<=' END,f->>'value');
ELSE
IF jsonb_typeof(f->'value') NOT IN ('string','number') OR f->'value' IS NULL THEN RAISE EXCEPTION 'SETTLEMENT_DIRECTORY_FILTER_INVALID'; END IF;
where_sql:=where_sql||format(' AND doc->>%L=%L',field,f->>'value');
END IF;
END LOOP;
direction:=CASE WHEN coalesce(p_ascending,true) THEN 'ASC' ELSE 'DESC' END;
order_sql:=format('(doc->>%L)',p_order);
IF p_order IN ('created_at','requested_at') THEN order_sql:=order_sql||'::timestamptz';
ELSIF p_order='id' AND p_table='settlements' THEN order_sql:=order_sql||'::bigint'; END IF;
EXECUTE format('WITH base AS (%s), matched AS MATERIALIZED (SELECT doc FROM base WHERE %s), page AS (SELECT doc FROM matched ORDER BY %s %s,doc->>''id'' %s LIMIT %s OFFSET %s) SELECT jsonb_build_object(''rows'',coalesce((SELECT jsonb_agg(doc ORDER BY %s %s,doc->>''id'' %s) FROM page),''[]''::jsonb),''count'',(SELECT count(*) FROM matched))',base_sql,where_sql,order_sql,direction,direction,p_limit,p_offset,order_sql,direction,direction) INTO result;
RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.vendor_advance_order_segment_status(p_session_token text, p_segment_id uuid, p_expected_status text, p_next_status text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store_id uuid := private.require_vendor_session(p_session_token);
v_segment public.order_store_segments%rowtype;
v_contract text;
v_allowed constant text[] := array[
'مخزن الشركة', 'تجهيز شحن', 'محولة إلى الفرع', 'تم الشحن',
'مخزن محلي', 'مندوب', 'توزيع داخلي', 'تم التسليم',
'رفض التسليم', 'مرفوض'
];
begin
select * into v_segment
from public.order_store_segments s
where s.id = p_segment_id
and s.store_id = v_store_id
for update;

if v_segment.id is null then
raise exception 'ORDER_SEGMENT_NOT_FOUND' using errcode = 'P0002';
end if;
if not v_segment.payment_confirmed then
raise exception 'ORDER_NOT_PAID' using errcode = 'P0001';
end if;
if v_segment.store_status is distinct from p_expected_status then
raise exception 'ORDER_STATUS_CONFLICT:%', v_segment.store_status
using errcode = '40001';
end if;
if nullif(trim(coalesce(p_next_status, '')), '') is null
or not (p_next_status = any(v_allowed)) then
raise exception 'ORDER_STATUS_TRANSITION_INVALID' using errcode = '22023';
end if;

select private.v94_jsonb_object(to_jsonb(o.details))
->> 'checkout_contract'
into v_contract
from public.orders o
where o.id = v_segment.order_id
for update;

update public.order_store_segments
set store_status = p_next_status,
updated_at = now()
where id = v_segment.id;

if v_contract = 'independent_vendor_orders' then
perform private.v103_sync_independent_order_status(
v_segment.order_id, v_store_id, p_next_status
);
else
perform private.mirror_v94_store_status(
v_segment.order_id, v_store_id, p_next_status
);
end if;

return jsonb_build_object(
'segment_id', v_segment.id,
'order_id', v_segment.order_id,
'previous_status', v_segment.store_status,
'store_status', p_next_status,
'canonical_order_status',
case when v_contract = 'independent_vendor_orders'
then p_next_status else null end,
'updated_at', now()
);
end;
$function$

CREATE OR REPLACE FUNCTION private.v98_apply_vendor_shipping()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_details jsonb := private.v94_jsonb_object(to_jsonb(new.details));
v_currency text := upper(coalesce(nullif(new.currency::text, ''), 'IQD'));
v_pending jsonb := jsonb_build_object(
'profile_active', true,
'matched', false,
'mode', 'vendor_assignment_pending',
'assigned', false,
'delivery_fee', 0,
'cost', 0,
'currency', upper(coalesce(nullif(new.currency::text, ''), 'IQD')),
'created_at', now()
);
begin
if coalesce(v_details ->> 'checkout_contract', '')
<> 'independent_vendor_orders' then
return new;
end if;

-- Checkout no longer chooses or exposes a company/rate. The immutable goods
-- total remains available while shipping is explicitly pending vendor input.
new.delivery_fee := 0;
new.delivery_currency := v_currency;
new.shipping_company_name := null;
new.shipping_snapshot := v_pending;
new.shipping_version := 0;
new.details := (v_details || jsonb_build_object(
'shipping_mode', 'vendor_assignment_pending',
'shipping_assigned', false,
'delivery_fee', 0,
'delivery_fee_local', 0,
'delivery_currency', v_currency,
'shipping_company_name', null,
'shipping_snapshot', v_pending,
'grand_total_local', private.v94_numeric(
v_details ->> 'customer_total_local', new.total_price
),
'grand_total_components', jsonb_build_array(
jsonb_build_object(
'kind', 'goods',
'amount', private.v94_numeric(
v_details ->> 'customer_total_local', new.total_price
),
'currency', v_currency
)
)
))::text;
return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_apply_option_stock_v47(p_options jsonb, p_item jsonb, p_qty integer)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
result jsonb := coalesce(p_options, '{}'::jsonb);
stocks jsonb := coalesce(p_options->'variant_stock', '{}'::jsonb);
selections jsonb := coalesce(p_item->'selected_options', '{}'::jsonb);
entry record;
canonical text;
chosen text;
available integer;
normalized jsonb := '{}'::jsonb;
matrix jsonb := coalesce(p_options->'matrix_stock', '{}'::jsonb);
matrix_key text;
BEGIN
IF p_qty IS NULL OR p_qty < 1 THEN
RAISE EXCEPTION 'V47_INVALID_QUANTITY';
END IF;

IF jsonb_typeof(stocks) <> 'object'
OR jsonb_typeof(selections) <> 'object' THEN
RAISE EXCEPTION 'V47_INVALID_OPTIONS';
END IF;

FOR entry IN SELECT key, value FROM jsonb_each(stocks)
LOOP
IF jsonb_typeof(entry.value) <> 'object' THEN
RAISE EXCEPTION 'V47_INVALID_STOCK_GROUP: %', entry.key;
END IF;

IF entry.value = '{}'::jsonb THEN
CONTINUE;
END IF;

canonical := CASE entry.key
WHEN 'colors' THEN 'color'
WHEN 'sizes' THEN 'size'
WHEN 'volumes' THEN 'volume'
ELSE entry.key
END;

chosen := coalesce(
nullif(selections->>canonical, ''),
nullif(selections->>entry.key, ''),
nullif(p_item->>canonical, ''),
nullif(p_item->>('selected_' || canonical), '')
);

IF chosen IS NULL OR NOT (entry.value ? chosen) THEN
CONTINUE;
END IF;

available := (entry.value->>chosen)::integer;

IF available IS NULL OR available < p_qty THEN
RAISE EXCEPTION
'Insufficient variant stock for %=%: available %, requested %',
canonical, chosen, available, p_qty;
END IF;

stocks := jsonb_set(
stocks,
ARRAY[entry.key, chosen],
to_jsonb(available - p_qty),
false
);
END LOOP;

FOREACH canonical IN ARRAY ARRAY['color', 'size', 'volume']
LOOP
chosen := coalesce(
nullif(selections->>canonical, ''),
nullif(p_item->>canonical, ''),
nullif(p_item->>('selected_' || canonical), ''),
''
);

normalized := jsonb_set(
normalized,
ARRAY[canonical],
to_jsonb(chosen),
true
);
END LOOP;

result := jsonb_set(result, '{variant_stock}', stocks, true);

IF jsonb_typeof(matrix) <> 'object' THEN
RAISE EXCEPTION 'V47_INVALID_MATRIX';
END IF;

IF matrix <> '{}'::jsonb THEN
matrix_key := public.meshwar_matrix_stock_key(normalized);

IF matrix_key IS NULL OR NOT (matrix ? matrix_key) THEN
RETURN result;
END IF;

available := (matrix->>matrix_key)::integer;

IF available IS NULL OR available < p_qty THEN
RAISE EXCEPTION
'Insufficient matrix stock for combination %. Available %, requested %',
matrix_key, available, p_qty;
END IF;

result := jsonb_set(
result,
ARRAY['matrix_stock', matrix_key],
to_jsonb(available - p_qty),
false
);
END IF;

RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.kinto_bundle_stock_link_v47()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
original jsonb;
details jsonb;
product record;
line record;
before_total integer;
before_options jsonb;
next_options jsonb;
saved_options jsonb;
saved_total integer;
evidence jsonb := '[]'::jsonb;
BEGIN
IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
RETURN NEW;
END IF;

BEGIN
original := coalesce(OLD.details::jsonb, '{}'::jsonb);
details := coalesce(NEW.details::jsonb, original);
EXCEPTION WHEN invalid_text_representation THEN
RETURN NEW;
END;

IF coalesce(original->>'source', '') <> 'local_cart_bundle'
OR NEW.status <> 'تم التسديد' THEN
RETURN NEW;
END IF;

IF original->>'bundle_stock_lifecycle_state' = 'deducted' THEN
RETURN NEW;
END IF;

IF jsonb_typeof(original->'items') IS DISTINCT FROM 'array'
OR original->'items' = '[]'::jsonb THEN
RAISE EXCEPTION 'V47_BUNDLE_ITEMS_REQUIRED';
END IF;

IF EXISTS (
SELECT 1
FROM jsonb_array_elements(original->'items') AS x(item)
WHERE nullif(item->>'product_id', '') IS NULL
OR coalesce(item->>'quantity', '') !~ '^[0-9]+$'
OR (item->>'quantity')::numeric < 1
OR (item->>'quantity')::numeric > 2147483647
) THEN
RAISE EXCEPTION 'V47_INVALID_BUNDLE_ITEM';
END IF;

FOR product IN
SELECT
(item->>'product_id')::uuid AS id,
sum((item->>'quantity')::integer)::integer AS qty
FROM jsonb_array_elements(original->'items') AS x(item)
GROUP BY (item->>'product_id')::uuid
ORDER BY (item->>'product_id')::uuid
LOOP
SELECT p.stock_quantity, coalesce(p.options, '{}'::jsonb)
INTO before_total, before_options
FROM public.local_products p
WHERE p.id = product.id
FOR UPDATE;

IF NOT FOUND THEN
RAISE EXCEPTION 'Local product % was not found', product.id;
END IF;

IF before_total IS NOT NULL AND before_total < product.qty THEN
RAISE EXCEPTION
'Insufficient stock for product %. Available %, requested %',
product.id, before_total, product.qty;
END IF;

IF before_total IS NULL THEN
CONTINUE;
END IF;

next_options := before_options;

FOR line IN
SELECT item, (item->>'quantity')::integer AS qty
FROM jsonb_array_elements(original->'items') AS x(item)
WHERE (item->>'product_id')::uuid = product.id
LOOP
next_options := public.kinto_apply_option_stock_v47(
next_options, line.item, line.qty
);
END LOOP;

UPDATE public.local_products p
SET
stock_quantity = before_total - product.qty,
options = next_options,
is_out_of_stock = (before_total - product.qty = 0)
WHERE p.id = product.id;

SELECT p.stock_quantity, p.options
INTO saved_total, saved_options
FROM public.local_products p
WHERE p.id = product.id;

IF saved_total IS DISTINCT FROM before_total - product.qty
OR saved_options IS DISTINCT FROM next_options THEN
RAISE EXCEPTION 'V47_STOCK_WRITE_MISMATCH: %', product.id;
END IF;

evidence := evidence || jsonb_build_array(
jsonb_build_object(
'product_id', product.id,
'quantity', product.qty,
'total_before', before_total,
'total_after', saved_total,
'variant_before', before_options->'variant_stock',
'variant_after', saved_options->'variant_stock',
'matrix_before', before_options->'matrix_stock',
'matrix_after', saved_options->'matrix_stock'
)
);
END LOOP;

details := jsonb_set(details, '{items}', original->'items', true);

details := jsonb_set(
details, '{bundle_stock_lifecycle_state}', '"deducted"'::jsonb, true
);

details := jsonb_set(
details, '{bundle_stock_deducted_at}', to_jsonb(now()::text), true
);

details := jsonb_set(
details, '{bundle_variant_stock_deducted}', 'true'::jsonb, true
);

details := jsonb_set(
details, '{stock_engine_version}', '"v47"'::jsonb, true
);

details := jsonb_set(
details, '{stock_deduction_evidence_v47}', evidence, true
);

NEW.details := details::text;
RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.kinto_save_staff_order_session_v1(p_role text, p_session_token text, p_order_id uuid, p_expected_status text, p_expected_price numeric, p_expected_currency text, p_patch jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; permissions jsonb; old_row public.orders%ROWTYPE;
typed public.orders%ROWTYPE; old_details jsonb; next_details jsonb;
price_changed boolean; assignment_changed boolean;
BEGIN
IF p_role IS NULL OR p_role NOT IN ('admin','employee') THEN
RAISE EXCEPTION 'ORDER_SAVE_ROLE_DENIED' USING ERRCODE='42501'; END IF;
actor:=private.kinto_staff_actor_v1(p_role,p_session_token);
permissions:=actor->'permissions';
-- Match the existing employee UI: absent permissions allow; explicit false denies.
-- Legacy JSON-string permissions are parsed just as the UI parses them.
IF jsonb_typeof(permissions)='string' THEN
BEGIN permissions:=(permissions#>>'{}')::jsonb;
EXCEPTION WHEN others THEN RAISE EXCEPTION 'ORDER_SAVE_PERMISSIONS_INVALID' USING ERRCODE='42501'; END;
END IF;
IF p_role='employee' AND (permissions->'orders'='false'::jsonb OR permissions->'manage_orders'='false'::jsonb) THEN
RAISE EXCEPTION 'ORDER_SAVE_PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR p_patch='{}'::jsonb
OR EXISTS(SELECT FROM jsonb_object_keys(p_patch) k(key) WHERE k.key<>ALL(ARRAY[
'status','reference_order_no','delivery_payment_type','branch_id','branch_name',
'delivery_agent_id','courier_id','total_price','currency','rejection_reason','details','delivery_fee'])) THEN
RAISE EXCEPTION 'ORDER_SAVE_PATCH_DENIED' USING ERRCODE='42501'; END IF;
SELECT * INTO old_row FROM public.orders WHERE id=p_order_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_SAVE_NOT_FOUND'; END IF;
IF old_row.status IS DISTINCT FROM p_expected_status OR old_row.total_price IS DISTINCT FROM p_expected_price
OR old_row.currency IS DISTINCT FROM p_expected_currency THEN RAISE EXCEPTION 'ORDER_SAVE_CHANGED_RELOAD'; END IF;
typed:=jsonb_populate_record(old_row,p_patch);
-- The external-shipping editor sends the UUID only; keep its legacy courier ID in sync.
IF typed.delivery_agent_id IS DISTINCT FROM old_row.delivery_agent_id AND NOT p_patch ? 'courier_id' THEN
SELECT c.id::text INTO typed.courier_id FROM public.couriers c WHERE c.courier_uuid=typed.delivery_agent_id;
END IF;
IF typed.status IS DISTINCT FROM old_row.status AND (typed.status IS NULL OR typed.status NOT IN (
'انتظار رد الموظف','بانتظار موافقة العميل','بانتظار موافقة الزبون','بانتظار التسعير',
'تم التسعير / بانتظار موافقة العميل','تمت الموافقة - بانتظار الدفع','تمت الموافقة',
'ملغي من قبل العميل','قيد الطلب','مخزن شركة','تجهيز شحن','تم الشحن','مخزن محلي',
'مندوب','توزيع داخلي','تم التسليم','رفض الطلب','مرفوض')) THEN
RAISE EXCEPTION 'ORDER_SAVE_STATUS_DENIED'; END IF;
-- Payment approval and payment-type edits keep their existing dedicated RPCs.
IF typed.delivery_payment_type IS DISTINCT FROM old_row.delivery_payment_type THEN
RAISE EXCEPTION 'ORDER_SAVE_USE_PAYMENT_TYPE_RPC' USING ERRCODE='42501'; END IF;
price_changed:=typed.total_price IS DISTINCT FROM old_row.total_price OR typed.currency IS DISTINCT FROM old_row.currency;
assignment_changed:=typed.branch_id IS DISTINCT FROM old_row.branch_id
OR typed.delivery_agent_id IS DISTINCT FROM old_row.delivery_agent_id OR typed.courier_id IS DISTINCT FROM old_row.courier_id;
IF p_role='employee' AND price_changed AND (permissions->'pricing'='false'::jsonb OR permissions->'manage_pricing'='false'::jsonb) THEN
RAISE EXCEPTION 'ORDER_SAVE_PRICING_DENIED' USING ERRCODE='42501'; END IF;
IF p_role='employee' AND assignment_changed AND (permissions->'branches'='false'::jsonb OR permissions->'manage_branches'='false'::jsonb) THEN
RAISE EXCEPTION 'ORDER_SAVE_ASSIGNMENT_DENIED' USING ERRCODE='42501'; END IF;
IF price_changed AND ((typed.total_price IS NOT NULL AND (typed.total_price<0 OR typed.total_price::text IN ('NaN','Infinity','-Infinity')))
OR (typed.currency IS DISTINCT FROM old_row.currency AND (typed.currency IS NULL OR typed.currency NOT IN ('$','USD','IQD','TL','TRY','SYP','€','EUR')))) THEN
RAISE EXCEPTION 'ORDER_SAVE_AMOUNT_INVALID'; END IF;
IF typed.delivery_fee IS DISTINCT FROM old_row.delivery_fee AND typed.delivery_fee IS NOT NULL
AND (typed.delivery_fee<0 OR typed.delivery_fee::text IN ('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'ORDER_SAVE_FEE_INVALID'; END IF;
IF p_role='employee' AND typed.delivery_fee IS DISTINCT FROM old_row.delivery_fee THEN
RAISE EXCEPTION 'ORDER_SAVE_EMPLOYEE_FEE_DENIED' USING ERRCODE='42501'; END IF;
-- SECURITY DEFINER bypasses the API-only settlement guard, so repeat its financial lock here.
IF (old_row.settlement_id IS NOT NULL OR coalesce(old_row.is_settled,false)) AND
(price_changed OR assignment_changed OR typed.delivery_fee IS DISTINCT FROM old_row.delivery_fee) THEN
RAISE EXCEPTION 'ORDER_SAVE_SETTLEMENT_LOCKED' USING ERRCODE='42501'; END IF;
IF assignment_changed THEN
IF typed.branch_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.branches b WHERE b.id::text=typed.branch_id) THEN
RAISE EXCEPTION 'ORDER_SAVE_BRANCH_INVALID'; END IF;
IF typed.delivery_agent_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.couriers c
WHERE c.courier_uuid=typed.delivery_agent_id AND coalesce(c.is_active,true)
AND (typed.branch_id IS NULL OR c.branch_id=typed.branch_id)) THEN RAISE EXCEPTION 'ORDER_SAVE_COURIER_INVALID'; END IF;
IF typed.courier_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.couriers c
WHERE c.id::text=typed.courier_id AND coalesce(c.is_active,true)
AND (typed.branch_id IS NULL OR c.branch_id=typed.branch_id)
AND (typed.delivery_agent_id IS NULL OR c.courier_uuid=typed.delivery_agent_id)) THEN RAISE EXCEPTION 'ORDER_SAVE_COURIER_INVALID'; END IF;
END IF;
IF p_patch ? 'details' THEN
old_details:=coalesce(nullif(old_row.details,'')::jsonb,'{}'::jsonb);
next_details:=coalesce(nullif(typed.details,'')::jsonb,'{}'::jsonb);
IF jsonb_typeof(old_details) IS DISTINCT FROM 'object' OR jsonb_typeof(next_details) IS DISTINCT FROM 'object'
OR (old_details-'parcels_count') IS DISTINCT FROM (next_details-'parcels_count') THEN
RAISE EXCEPTION 'ORDER_SAVE_DETAILS_DENIED' USING ERRCODE='42501'; END IF;
IF next_details IS DISTINCT FROM old_details THEN
IF jsonb_typeof(next_details->'parcels_count') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'ORDER_SAVE_PARCELS_INVALID'; END IF;
IF (next_details->>'parcels_count')::numeric NOT BETWEEN 1 AND 100000
OR (next_details->>'parcels_count')::numeric<>trunc((next_details->>'parcels_count')::numeric) THEN RAISE EXCEPTION 'ORDER_SAVE_PARCELS_INVALID'; END IF;
END IF;
END IF;
-- Names are display metadata derived from the selected branch, never identity evidence.
IF typed.branch_id IS DISTINCT FROM old_row.branch_id THEN
SELECT b.name INTO typed.branch_name FROM public.branches b WHERE b.id::text=typed.branch_id;
ELSE typed.branch_name:=old_row.branch_name; END IF;
PERFORM private.kinto_check_order_assignment_v1(actor,old_row,typed); UPDATE public.orders SET status=typed.status,reference_order_no=typed.reference_order_no,
branch_id=typed.branch_id,branch_name=typed.branch_name,delivery_agent_id=typed.delivery_agent_id,
courier_id=typed.courier_id,total_price=typed.total_price,currency=typed.currency,
rejection_reason=typed.rejection_reason,details=typed.details,delivery_fee=typed.delivery_fee WHERE id=p_order_id;
-- Existing local-price, stock, paid-marker and lifecycle triggers still run above.
IF price_changed THEN
INSERT INTO private.kinto_order_save_audit_v1(order_id,actor_type,actor_id,previous_price,new_price,previous_currency,new_currency)
VALUES(p_order_id,p_role,actor->>'id',old_row.total_price,typed.total_price,old_row.currency,typed.currency);
END IF;
END $function$

CREATE OR REPLACE FUNCTION private.v112_require_reward_actor(p_actor_id text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_role text;
begin
select lower(trim(coalesce(e.role::text, '')))
into v_role
from public.employees e
where e.id::text = trim(coalesce(p_actor_id, ''))
limit 1;

if v_role not in ('admin', 'employee', 'أدمن', 'ادمن', 'موظف') then
raise exception 'REWARD_ACTOR_NOT_AUTHORIZED' using errcode = '42501';
end if;
return v_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_kinto_campaign_v400(p_session_token text, p_title text, p_reward_amount bigint, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_store_ids text[] DEFAULT NULL::text[], p_all_stores boolean DEFAULT false, p_display_text text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
aid text;
cid uuid;
t text;
d text;
nid uuid;
ncnt integer:=0;
begin

aid:=private.require_admin_session_v147(p_session_token);

if coalesce(aid,'')='' then
raise exception 'invalid admin session';
end if;

t:=trim(coalesce(p_title,''));

if length(t) not between 2 and 160 then
raise exception 'invalid campaign title';
end if;

if p_reward_amount not in(1000,2000,3000,5000,10000) then
raise exception 'invalid campaign reward';
end if;

if p_starts_at is null
or p_ends_at is null
or p_ends_at<=p_starts_at then
raise exception 'invalid campaign period';
end if;

if not coalesce(p_all_stores,false)
and coalesce(cardinality(p_store_ids),0)=0 then
raise exception 'campaign store required';
end if;

d:=nullif(trim(coalesce(p_display_text,'')),'');

if d is not null and length(d) not between 2 and 120 then
raise exception 'invalid campaign display text';
end if;


-- ننشئ الحملة بدون أي متجر مشارك بعد
insert into public.kinto_campaigns(
title,
reward_amount,
currency,
starts_at,
ends_at,
display_text,
created_by
)
values(
t,
p_reward_amount,
'IQD',
p_starts_at,
p_ends_at,
d,
aid
)
returning id into cid;


-- إنشاء دعوة الحملة
insert into public.kinto_admin_notifications(
title,
body,
kind,
created_by,
campaign_id
)
values(
'حملة KINTO: '||t,

'دعوة للمشاركة في حملة KINTO بقيمة مكافأة '||
to_char(p_reward_amount,'FM999G999G999')||
' IQD. لن يظهر متجرك ضمن الحملة ولن تُمنح مكافآت الحملة لطلباته إلا بعد قبولك. الفترة: '||
to_char(
p_starts_at at time zone 'UTC',
'YYYY-MM-DD HH24:MI'
)||
' UTC إلى '||
to_char(
p_ends_at at time zone 'UTC',
'YYYY-MM-DD HH24:MI'
)||
' UTC.',

'campaign',
aid,
cid
)
returning id into nid;


-- المتاجر المختارة تستلم دعوة فقط
if coalesce(p_all_stores,false) then

insert into public.kinto_admin_notification_recipients(
notification_id,
store_id
)
select
nid,
s.id::text
from public.local_stores s
where lower(trim(coalesce(s.status,'')))='active'
on conflict do nothing;

else

insert into public.kinto_admin_notification_recipients(
notification_id,
store_id
)
select
nid,
s.id::text
from public.local_stores s
where s.id::text=any(p_store_ids)
and lower(trim(coalesce(s.status,'')))='active'
on conflict do nothing;

end if;

get diagnostics ncnt=row_count;

if ncnt=0 then
raise exception 'no active campaign stores';
end if;


return jsonb_build_object(
'ok',true,
'campaign_id',cid,
'stores',ncnt,
'invited_stores',ncnt,
'accepted_stores',0,
'reward_amount',p_reward_amount,
'currency','IQD',
'notification_id',nid,
'notified_stores',ncnt
);

end $function$

CREATE OR REPLACE FUNCTION private.invoice_stock_projection_v58(p_order orders)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
d jsonb := coalesce(nullif(p_order.details::text,'')::jsonb,'{}'::jsonb);
cache jsonb := '{}'::jsonb;
p record; x jsonb; s jsonb; opts jsonb; selected jsonb; group_entry record;
pid text; key text; chosen text; matrix_key text; normalized jsonb;
requested integer; available integer; cap integer; total integer;
old_line numeric; new_line numeric; loss numeric := 0; qty integer := 0;
active_items jsonb := '[]'::jsonb; display_items jsonb := '[]'::jsonb;
stores jsonb := '[]'::jsonb; loss_by_store jsonb := '{}'::jsonb;
sid text; goods numeric; line_count integer := 0; line_index integer := 0; original_requested integer; v_changed boolean := false;
begin
if d->>'source' is distinct from 'local_cart_bundle'
or d->>'checkout_contract' is distinct from 'independent_vendor_orders' then
raise exception 'V58_INDEPENDENT_LOCAL_ORDER_REQUIRED';
end if;
if jsonb_typeof(d->'items') is distinct from 'array' then
raise exception 'V58_ITEMS_REQUIRED';
end if;
-- Match V47 lock order. This transaction only reads inventory.
for p in
select lp.id, lp.store_id, lp.stock_quantity, lp.options
from public.local_products lp
where lp.id in (select (item->>'product_id')::uuid
from jsonb_array_elements(d->'items') item)
order by lp.id for update
loop
cache := jsonb_set(cache,array[p.id::text],jsonb_build_object(
'stock',p.stock_quantity,'options',coalesce(p.options,'{}'::jsonb),
'store_id',p.store_id),true);
end loop;
-- Retain zero rows solely in invoice history, never in active deduction items.
select coalesce(jsonb_agg(v),'[]'::jsonb) into display_items
from jsonb_array_elements(coalesce(d->'stock_adjustment_v58'->'display_items','[]'::jsonb)) v
where coalesce((v->>'quantity')::integer,0)=0;
for x in select value from jsonb_array_elements(d->'items') loop
line_index := line_index + 1;
pid := x->>'product_id';
if pid is null or coalesce(x->>'quantity','') !~ '^[0-9]+$'
or (x->>'quantity')::numeric < 1 or (x->>'quantity')::numeric > 1000000 then
raise exception 'V58_INVALID_ITEM';
end if;
requested := (x->>'quantity')::integer;
original_requested := coalesce((x->>'stock_requested_quantity_v58')::integer,requested);
x := x || jsonb_build_object('stock_line_id_v58',coalesce((x->>'stock_line_id_v58')::integer,line_index),
'stock_requested_quantity_v58',original_requested);
available := requested;
selected := coalesce(x->'selected_options','{}'::jsonb);
if jsonb_typeof(selected) <> 'object' then raise exception 'V58_INVALID_OPTIONS'; end if;
if not (cache ? pid) then
available := 0;
else
if cache->pid->>'store_id' is distinct from coalesce(x->>'store_id',d->>'store_id') then
raise exception 'V58_PRODUCT_STORE_MISMATCH';
end if;
total := (cache->pid->>'stock')::integer;
opts := cache->pid->'options';
-- Preserve V47 unmanaged-total semantics.
if total is not null then
available := least(available,greatest(0,total));
for group_entry in select e.key,e.value from jsonb_each(coalesce(opts->'variant_stock','{}'::jsonb)) e loop
if jsonb_typeof(group_entry.value) <> 'object' then raise exception 'V58_INVALID_STOCK_GROUP'; end if;
key := case group_entry.key when 'colors' then 'color' when 'sizes' then 'size'
when 'volumes' then 'volume' else group_entry.key end;
chosen := coalesce(nullif(selected->>key,''),nullif(selected->>group_entry.key,''),
nullif(x->>key,''),nullif(x->>('selected_'||key),''));
if chosen is not null and group_entry.value ? chosen then
cap := (group_entry.value->>chosen)::integer;
available := least(available,greatest(0,coalesce(cap,0)));
end if;
end loop;
normalized := '{}'::jsonb;
foreach key in array array['color','size','volume'] loop
chosen := coalesce(nullif(selected->>key,''),nullif(x->>key,''),nullif(x->>('selected_'||key),''),'');
normalized := jsonb_set(normalized,array[key],to_jsonb(chosen),true);
end loop;
matrix_key := public.meshwar_matrix_stock_key(normalized);
if matrix_key is not null and coalesce(opts->'matrix_stock','{}'::jsonb) ? matrix_key then
cap := (opts->'matrix_stock'->>matrix_key)::integer;
available := least(available,greatest(0,coalesce(cap,0)));
end if;
if available > 0 then
opts := public.kinto_apply_option_stock_v47(opts,x,available);
cache := jsonb_set(cache,array[pid,'options'],opts,false);
end if;
cache := jsonb_set(cache,array[pid,'stock'],to_jsonb(total-available),false);
end if;
end if;
-- Keep submitted pricing snapshots; never accept browser prices.
old_line := coalesce((x->>'line_total_local')::numeric,
(x->>'unit_price_local')::numeric*requested);
if old_line is null or old_line < 0 then raise exception 'V58_INVALID_PRICE'; end if;
new_line := round(old_line*available/requested,2);
v_changed := v_changed or available < requested;
loss := loss + old_line-new_line;
sid := coalesce(x->>'store_id',d->>'store_id');
loss_by_store := jsonb_set(loss_by_store,array[sid],to_jsonb(
coalesce((loss_by_store->>sid)::numeric,0)+old_line-new_line),true);
x := x || jsonb_build_object('quantity',available,'line_total_local',new_line);
if available < original_requested then
x := x || jsonb_build_object('_invoiceRequestedV57',original_requested,'_invoiceAvailableV57',available);
end if;
display_items := display_items || jsonb_build_array(x);
if available > 0 then
active_items := active_items || jsonb_build_array(x - '_invoiceRequestedV57' - '_invoiceAvailableV57');
qty := qty + available;
line_count := line_count + 1;
end if;
end loop;
select coalesce(jsonb_agg(v order by (v->>'stock_line_id_v58')::integer),'[]'::jsonb) into display_items
from jsonb_array_elements(display_items) v;
goods := greatest(0,round(coalesce(p_order.total_price,0)-loss,2));
if not v_changed then
return jsonb_build_object('changed',false,'details',d,'total_price',p_order.total_price);
end if;
for s in select value from jsonb_array_elements(coalesce(d->'stores','[]'::jsonb)) loop
sid := s->>'store_id';
s := s || jsonb_build_object('subtotal_local',greatest(0,
coalesce((s->>'subtotal_local')::numeric,0)-coalesce((loss_by_store->>sid)::numeric,0)),
'quantity',coalesce((select sum((v->>'quantity')::integer) from jsonb_array_elements(active_items) v
where v->>'store_id'=sid),0),
'item_count',(select count(*) from jsonb_array_elements(active_items) v where v->>'store_id'=sid));
stores := stores || jsonb_build_array(s);
end loop;
d := d || jsonb_build_object('items',active_items,'stores',stores,'quantity',qty,
'requested_quantity',qty,'item_count',line_count,'customer_total_local',goods,
'stock_adjustment_v58',jsonb_build_object('version','v58','display_items',display_items,
'previous_total',p_order.total_price,'current_total',goods));
if d ? 'store_subtotal' then d := jsonb_set(d,'{store_subtotal}',to_jsonb(goods),true); end if;
return jsonb_build_object('changed',true,'details',d,'total_price',goods);
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_reconcile_invoice_v58(p_session_token text, p_order_id uuid, p_approve boolean DEFAULT false, p_expected_revision text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
o public.orders%rowtype;
projection jsonb;
d jsonb;
revision text;
was_changed boolean := false;
begin
v_customer_id := private.require_customer_review_session(p_session_token);

select *
into o
from public.orders
where id = p_order_id
and orders.customer_id::text = v_customer_id::text
for update;

if not found then
raise exception 'V58_ORDER_NOT_FOUND';
end if;

if not (
o.status = any(array[
'بانتظار موافقة العميل',
'بانتظار موافقة الزبون',
'بانتظار التسعير',
'تم التسعير / بانتظار موافقة العميل'
])
) then
raise exception 'V58_ORDER_NOT_AWAITING_APPROVAL';
end if;

d := coalesce(nullif(o.details::text,'')::jsonb,'{}'::jsonb);

if coalesce(d->>'bundle_stock_lifecycle_state','') = 'deducted' then
raise exception 'V58_PAID_ORDER_LOCKED';
end if;

projection := private.invoice_stock_projection_v59(o);
was_changed := (projection->>'changed')::boolean;

if was_changed then
if coalesce((to_jsonb(o)->>'reward_discount_amount')::numeric,0)
> floor((projection->>'total_price')::numeric * 0.1)
then
raise exception 'V58_REWARD_REVIEW_REQUIRED';
end if;

perform set_config('kinto.invoice_adjustment_v58',o.id::text,true);

update public.orders
set
details = (projection->'details')::text,
total_price = (projection->>'total_price')::numeric
where id = o.id
returning * into o;

perform set_config('kinto.invoice_adjustment_v58','',true);

delete from public.order_store_segments seg
where seg.order_id = o.id
and not seg.payment_confirmed
and not exists(
select 1
from jsonb_array_elements(o.details::jsonb->'items') item
where item->>'store_id' = seg.store_id::text
);

if o.details::jsonb is distinct from projection->'details'
or o.total_price is distinct from (projection->>'total_price')::numeric
then
raise exception 'V58_ORDER_WRITE_MISMATCH';
end if;
end if;

revision := md5(to_jsonb(o)::text);

if p_approve then
if was_changed or p_expected_revision is distinct from revision then
return jsonb_build_object(
'approved',false,
'review_required',true,
'order',to_jsonb(o),
'revision',revision
);
end if;

if o.total_price <= 0
or jsonb_array_length(o.details::jsonb->'items') = 0
then
return jsonb_build_object(
'approved',false,
'unavailable',true,
'order',to_jsonb(o),
'revision',revision
);
end if;

perform set_config('kinto.invoice_approval_v58',o.id::text,true);

update public.orders
set status = 'تمت الموافقة - بانتظار الدفع'
where id = o.id
returning * into o;

perform set_config('kinto.invoice_approval_v58','',true);
end if;

return jsonb_build_object(
'approved',p_approve,
'changed',was_changed,
'order',to_jsonb(o),
'revision',revision
);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_notification_action_v391(p_session_token text, p_notification_id uuid, p_action text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
sid text;
a text;
cid uuid;
cstatus text;
cend timestamptz;
begin

sid:=private.require_vendor_session(p_session_token)::text;

if coalesce(sid,'')='' then
raise exception 'VENDOR_SESSION_INVALID';
end if;

a:=lower(trim(coalesce(p_action,'')));

if a not in('read','accepted','rejected') then
raise exception 'invalid action';
end if;


select n.campaign_id
into cid
from public.kinto_admin_notification_recipients r
join public.kinto_admin_notifications n
on n.id=r.notification_id
where r.notification_id=p_notification_id
and r.store_id=sid
for update of r;

if not found then
raise exception 'notification not found';
end if;


-- لا نقبل حملة انتهت أو توقفت
if cid is not null and a='accepted' then

select status,ends_at
into cstatus,cend
from public.kinto_campaigns
where id=cid;

if cstatus is distinct from 'active'
or cend<=now() then
raise exception 'campaign is no longer available';
end if;

end if;


update public.kinto_admin_notification_recipients
set
read_at=coalesce(read_at,now()),

response=
case
when a in('accepted','rejected') then a
else response
end,

responded_at=
case
when a in('accepted','rejected') then now()
else responded_at
end

where notification_id=p_notification_id
and store_id=sid;


if cid is not null then

if a='rejected' then

delete from public.kinto_campaign_stores
where campaign_id=cid
and store_id=sid;


elsif a='accepted' then

insert into public.kinto_campaign_stores(
campaign_id,
store_id
)
select
cid,
s.id::text
from public.local_stores s
where s.id::text=sid
and lower(trim(coalesce(s.status,'')))='active'
on conflict do nothing;

end if;

end if;


return jsonb_build_object(
'ok',true,
'campaign_id',cid,

'campaign_participating',
case
when cid is null then null
else exists(
select 1
from public.kinto_campaign_stores
where campaign_id=cid
and store_id=sid
)
end
);

end $function$

CREATE OR REPLACE FUNCTION public.customer_cart_get_v130(p_customer_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
v_result jsonb;
begin
if not exists (select 1 from public.customers where id = p_customer_id) then
raise exception 'CUSTOMER_NOT_FOUND';
end if;

select jsonb_build_object('items', c.items, 'updated_at', c.updated_at)
into v_result
from public.customer_local_carts c
where c.customer_id = p_customer_id;

return coalesce(v_result, jsonb_build_object('items', '[]'::jsonb, 'updated_at', null));
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_cart_put_v130(p_customer_id uuid, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
v_updated_at timestamptz;
begin
if not exists (select 1 from public.customers where id = p_customer_id) then
raise exception 'CUSTOMER_NOT_FOUND';
end if;
if p_items is null or jsonb_typeof(p_items) <> 'array' then
raise exception 'INVALID_CART_ITEMS';
end if;
if jsonb_array_length(p_items) > 200 or pg_column_size(p_items) > 262144 then
raise exception 'CART_TOO_LARGE';
end if;

insert into public.customer_local_carts(customer_id, items, updated_at)
values (p_customer_id, p_items, now())
on conflict (customer_id) do update
set items = excluded.items,
updated_at = excluded.updated_at
returning updated_at into v_updated_at;

return jsonb_build_object('items', p_items, 'updated_at', v_updated_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.adjust_customer_reward_balance(p_customer_id uuid, p_amount numeric, p_currency text, p_actor_id text, p_note text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_currency text := private.v112_reward_currency(p_currency);
v_customer public.customers%rowtype;
v_current numeric;
v_next numeric;
v_entry jsonb;
begin
perform private.v112_require_reward_actor(p_actor_id);
if v_currency not in ('USD', 'IQD', 'TRY') then
raise exception 'REWARD_CURRENCY_NOT_SUPPORTED' using errcode = '22023';
end if;
if coalesce(p_amount, 0) = 0 then
raise exception 'REWARD_AMOUNT_REQUIRED' using errcode = '22023';
end if;

select * into v_customer
from public.customers
where id = p_customer_id
for update;
if not found then raise exception 'CUSTOMER_NOT_FOUND' using errcode = 'P0002'; end if;

v_current := coalesce(nullif(v_customer.reward_balances ->> v_currency, '')::numeric, 0);
v_next := v_current + p_amount;
if v_next < 0 then raise exception 'REWARD_BALANCE_INSUFFICIENT' using errcode = '22003'; end if;

v_entry := jsonb_strip_nulls(jsonb_build_object(
'amount', p_amount,
'currency', v_currency,
'type', case when p_amount > 0 then 'grant' else 'withdraw' end,
'date', now(),
'actor_id', p_actor_id,
'note', nullif(trim(coalesce(p_note, '')), '')
));

update public.customers
set reward_balances = jsonb_set(coalesce(reward_balances, '{}'::jsonb), array[v_currency], to_jsonb(v_next), true),
rewards_log = coalesce(rewards_log, '[]'::jsonb) || jsonb_build_array(v_entry)
where id = p_customer_id;

return jsonb_build_object('customer_id', p_customer_id, 'currency', v_currency,
'balance', v_next, 'reward_balances', jsonb_set(coalesce(v_customer.reward_balances, '{}'::jsonb), array[v_currency], to_jsonb(v_next), true));
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_campaign_order_discount_v411()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
sid text;
cur text;
camp record;
product_total numeric;
amount numeric;
begin
if new.kinto_campaign_id is not null
or coalesce(new.kinto_campaign_discount_amount,0)>0 then
return new;
end if;

sid:=public.kinto_order_store_id_v310(new);
cur:=public.kinto_normalize_currency_v310(new.currency);
product_total:=greatest(coalesce(new.total_price,0),0);

if sid is null or cur<>'IQD' or product_total<=0 then
return new;
end if;

select c.id,c.title,c.reward_amount,c.currency,
c.starts_at,c.ends_at,c.display_text
into camp
from public.kinto_campaigns c
join public.kinto_campaign_stores cs
on cs.campaign_id=c.id
and cs.store_id=sid
where c.status='active'
and statement_timestamp()>=c.starts_at
and statement_timestamp()<c.ends_at
order by c.created_at,c.id
limit 1;

if not found then
return new;
end if;

amount:=least(camp.reward_amount::numeric,product_total);

if amount<=0 then
return new;
end if;

new.kinto_campaign_id:=camp.id;
new.kinto_campaign_discount_amount:=amount;
new.kinto_campaign_discount_currency:='IQD';

new.kinto_campaign_discount_snapshot:=
jsonb_build_object(
'source','kinto_campaign_v411',
'campaign_id',camp.id,
'campaign_title',camp.title,
'amount',amount,
'currency','IQD',
'store_id',sid,
'product_total_at_order',product_total,
'shipping_discount',0,
'funded_by','kinto',
'locked_at',statement_timestamp()
);

return new;

exception when others then
raise warning
'KINTO_V411_CAMPAIGN_DISCOUNT_SKIPPED order=% error=%',
new.id,sqlerrm;
return new;
end $function$

CREATE OR REPLACE FUNCTION private.kinto_deals_v1_redemption_lifecycle_g5i()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_d jsonb;
v_paid boolean;
v_cancel boolean;
v_r public.kinto_deals_v1_redemptions%rowtype;
v_c public.kinto_deals_v1_campaigns%rowtype;
v_used integer;
v_prior_units integer;
v_allocated integer;
begin
if new.status is not distinct from old.status then return new;end if;
-- Fast no-op for every ordinary order: no reservation, no action.
if not exists(select 1 from public.kinto_deals_v1_redemptions r
where r.order_id=new.id and r.state='pending') then return new;end if;
v_d:=coalesce(nullif(new.details,'')::jsonb,'{}'::jsonb);
if v_d->>'source'<>'local_cart_bundle'
or v_d->>'checkout_contract'<>'independent_vendor_orders' then
raise exception 'DEALS_LIFECYCLE_ORDER_CONTRACT_INVALID' using errcode='P0001';end if;
v_paid:=new.status='تم التسديد'
and v_d->>'bundle_stock_lifecycle_state'='deducted';
v_cancel:=new.status in ('ملغي','ملغي من قبل العميل','رفض الطلب','مرفوض')
and old.status<>'تم التسديد'
and coalesce(v_d->>'bundle_stock_lifecycle_state','')<>'deducted';
if new.status='تم التسديد' and not v_paid then
raise exception 'DEALS_CANONICAL_STOCK_DEDUCTION_REQUIRED' using errcode='P0001';
end if;
if v_paid then
-- Payment is the allocation race winner, not the earliest pending order.
-- A rejected confirmation rolls back this status change AND V93 stock deduction.
-- NOWAIT avoids a lock-order cycle: checkout takes campaign then order;
-- payment already holds order and must never wait on campaign.
select * into v_r from public.kinto_deals_v1_redemptions
where order_id=new.id and state='pending' for update;
if found then
select * into v_c from public.kinto_deals_v1_campaigns
where id=v_r.campaign_id for update nowait;
select count(*)::integer,coalesce(sum(qualifying_units),0)::integer
into v_used,v_prior_units from public.kinto_deals_v1_redemptions
where campaign_id=v_r.campaign_id and customer_id=v_r.customer_id
and state='confirmed';
select count(*)::integer into v_allocated from public.kinto_deals_v1_redemptions
where campaign_id=v_r.campaign_id and state='confirmed';
if v_used>=v_c.max_uses_per_customer
or (v_c.kind='limited_purchase'
and v_c.max_units_per_customer is not null
and v_prior_units+v_r.qualifying_units>v_c.max_units_per_customer)
or (v_c.max_total_redemptions is not null
and v_allocated>=v_c.max_total_redemptions) then
raise exception 'نفد المنتج، حظ أوفر في حملات أخرى قريباً'
using errcode='P0001',hint='DEALS_PAID_ALLOCATION_EXHAUSTED';
end if;
end if;
update public.kinto_deals_v1_redemptions r
set state='confirmed',updated_at=now(),
frozen_snapshot=r.frozen_snapshot||jsonb_build_object(
'confirmed_at',now(),'confirmation_order_status',new.status,
'stock_lifecycle_state','deducted')
where r.order_id=new.id and r.state='pending';
elsif v_cancel then
update public.kinto_deals_v1_redemptions r
set state='released',updated_at=now(),
frozen_snapshot=r.frozen_snapshot||jsonb_build_object(
'released_at',now(),'release_order_status',new.status,
'release_reason','canonical_pre_payment_cancellation')
where r.order_id=new.id and r.state='pending';
end if;
-- After payment, a later status change NEVER releases or reverses a redemption.
return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_profit_report_v164(p_session_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
sid uuid:=private.require_vendor_session(p_session_token);
seg record;
item jsonb;
line jsonb;
frozen record;
financial jsonb;
archived text;
lines jsonb:='[]';
expenses jsonb;
expense_total numeric;
cost numeric;
fx numeric;
qty numeric;
idx integer:=0;
cost_total numeric:=0;
complete boolean:=true;
begin
select s.*,o.order_code,o.created_at order_created_at
into seg
from public.order_store_segments s
join public.orders o on o.id=s.order_id
where s.store_id=sid
and o.order_code='KN-000100'
and s.commission_snapshot->>'version'='v161'
and s.payment_confirmed
and s.store_status='تم التسليم';

if not found then
return jsonb_build_object(
'order',null,'expenses','[]'::jsonb
);
end if;

financial:=seg.commission_snapshot;

if seg.vendor_settlement_archive_id is not null then
select a.statement_no,x.value
into archived,line
from public.vendor_settlement_archives_v163 a
cross join lateral
jsonb_array_elements(a.segment_ids) x(value)
where a.id=seg.vendor_settlement_archive_id
and a.store_id=sid
and x.value->>'segment_id'=seg.id::text;

if not found then
raise exception 'PROFIT_ARCHIVE_LINE_MISSING';
end if;

financial:=line||jsonb_build_object(
'currency',seg.currency
);
end if;

select * into frozen
from private.vendor_profit_costs_v164
where segment_id=seg.id and store_id=sid;

if found then
lines:=frozen.lines;
cost_total:=frozen.total_cost_local;
else
if jsonb_typeof(seg.items_snapshot)<>'array'
or jsonb_array_length(seg.items_snapshot)=0 then
complete:=false;
end if;

for item in
select value from jsonb_array_elements(seg.items_snapshot)
loop
idx:=idx+1;
cost:=null;
fx:=null;
qty:=null;

select p.cost_price into cost
from public.local_products p
where p.id=private.v94_uuid(item->>'product_id')
and p.store_id=sid;

fx:=nullif(
item->'pricing_snapshot'->>'exchange_rate',''
)::numeric;

qty:=nullif(item->>'quantity','')::numeric;

if cost is null or cost<0
or fx is null or fx<=0
or qty is null or qty<=0 then
complete:=false;
end if;

lines:=lines||jsonb_build_array(
jsonb_build_object(
'item_no',idx,
'product_id',item->>'product_id',
'product_name',item->>'product_name',
'quantity',qty,
'unit_cost_usd',cost,
'exchange_rate',fx,
'cost_local',
case when cost>=0 and fx>0 and qty>0
then round(cost*fx*qty,2)
else null
end
)
);
end loop;
end if;

select
coalesce(
jsonb_agg(to_jsonb(e) order by e.created_at desc),
'[]'::jsonb
),
coalesce(sum(e.amount),0)
into expenses,expense_total
from private.vendor_profit_expenses_v164 e
where e.store_id=sid and e.segment_id=seg.id;

return jsonb_build_object(
'order',jsonb_build_object(
'segment_id',seg.id,
'order_code',seg.order_code,
'created_at',seg.order_created_at,
'currency',seg.currency,
'financial',financial,
'archive_id',seg.vendor_settlement_archive_id,
'statement_no',archived,
'cost_lines',lines,
'cost_frozen',frozen.segment_id is not null,
'cost_ready',complete,
'total_cost_local',
case when frozen.segment_id is not null
then cost_total else null end,
'cost_captured_at',frozen.captured_at
),
'expenses',expenses,
'expense_total',expense_total
);
end
$function$

CREATE OR REPLACE FUNCTION public.kinto_vendor_product_write_session_v1(p_session_token text, p_action text, p_id uuid, p_patch jsonb DEFAULT '{}'::jsonb, p_filters jsonb DEFAULT '[]'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE sid uuid; old_row public.local_products%ROWTYPE; next_row public.local_products%ROWTYPE;
f jsonb; field text; kind text; clause text:=''; matched boolean; out_row public.local_products%ROWTYPE;
BEGIN
sid:=private.require_vendor_session(p_session_token);
IF p_action IS NULL OR p_action NOT IN ('insert','update','delete') THEN RAISE EXCEPTION 'PRODUCT_ACTION_DENIED'; END IF;
IF jsonb_typeof(p_filters) IS DISTINCT FROM 'array' OR jsonb_array_length(p_filters)>12 THEN RAISE EXCEPTION 'PRODUCT_FILTER_INVALID'; END IF;
IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_patch) k(key) WHERE k.key<>ALL(ARRAY[
'store_id','product_name','image_url','description','base_price','discount_price','currency','is_out_of_stock','stock_quantity',
'low_stock_threshold','options','updated_at','category_id','subcategory_id','is_featured','barcode','cost_price'])) THEN RAISE EXCEPTION 'PRODUCT_PATCH_DENIED'; END IF;
IF p_patch ? 'store_id' AND p_patch->>'store_id' IS DISTINCT FROM sid::text THEN RAISE EXCEPTION 'PRODUCT_STORE_DENIED' USING ERRCODE='42501'; END IF;
IF p_action='insert' THEN
IF p_id IS NOT NULL OR p_filters<>'[]'::jsonb THEN RAISE EXCEPTION 'PRODUCT_INSERT_INVALID'; END IF;
next_row:=jsonb_populate_record(NULL::public.local_products,jsonb_build_object('store_id',sid,'currency','USD','stock_quantity',0,
'low_stock_threshold',3,'is_out_of_stock',false,'is_featured',false,'options',jsonb_build_object('colors','[]'::jsonb,'sizes','[]'::jsonb,'volumes','[]'::jsonb))||p_patch);
ELSE
IF p_id IS NULL THEN RAISE EXCEPTION 'PRODUCT_ID_REQUIRED'; END IF;
SELECT * INTO old_row FROM public.local_products WHERE id=p_id AND store_id=sid FOR UPDATE;
IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;
FOR f IN SELECT value FROM jsonb_array_elements(p_filters) LOOP
field:=f->>'field';
kind:=CASE field WHEN 'id' THEN 'uuid' WHEN 'store_id' THEN 'uuid' WHEN 'updated_at' THEN 'timestamptz'
WHEN 'options' THEN 'jsonb' WHEN 'stock_quantity' THEN 'integer' WHEN 'is_out_of_stock' THEN 'boolean' ELSE NULL END;
IF kind IS NULL OR f->>'op' IS NULL OR f->>'op' NOT IN ('eq','is') THEN RAISE EXCEPTION 'PRODUCT_FILTER_INVALID'; END IF;
IF f->>'op'='is' THEN
IF f->'value'<>'null'::jsonb THEN RAISE EXCEPTION 'PRODUCT_FILTER_INVALID'; END IF;
clause:=clause||format(' AND p.%I IS NULL',field);
ELSE
clause:=clause||format(' AND p.%I IS NOT DISTINCT FROM %L::%s',field,CASE WHEN kind='jsonb' THEN (f->'value')::text ELSE f->>'value' END,kind);
END IF;
END LOOP;
EXECUTE 'SELECT EXISTS(SELECT FROM public.local_products p WHERE p.id=$1 AND p.store_id=$2'||clause||')' INTO matched USING p_id,sid;
IF NOT matched THEN RETURN '[]'::jsonb; END IF;
IF p_action='delete' THEN DELETE FROM public.local_products WHERE id=p_id AND store_id=sid RETURNING * INTO out_row; RETURN jsonb_build_array(to_jsonb(out_row)); END IF;
next_row:=jsonb_populate_record(old_row,p_patch);
END IF;
next_row.store_id:=sid;
IF p_action='update' AND (to_jsonb(next_row)-'updated_at')=(to_jsonb(old_row)-'updated_at') THEN RETURN jsonb_build_array(to_jsonb(old_row)); END IF;
IF nullif(btrim(next_row.product_name),'') IS NULL OR next_row.currency IS NULL OR length(next_row.currency)>16
OR next_row.base_price IS NULL OR next_row.base_price<0 OR next_row.base_price::text IN ('NaN','Infinity','-Infinity')
OR (next_row.discount_price IS NOT NULL AND (next_row.discount_price<0 OR next_row.discount_price>next_row.base_price OR next_row.discount_price::text IN ('NaN','Infinity','-Infinity')))
OR (next_row.cost_price IS NOT NULL AND (next_row.cost_price<0 OR next_row.cost_price::text IN ('NaN','Infinity','-Infinity')))
OR next_row.stock_quantity IS NULL OR next_row.stock_quantity<0 OR next_row.low_stock_threshold IS NULL OR next_row.low_stock_threshold<0
OR jsonb_typeof(next_row.options) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'PRODUCT_VALUES_INVALID'; END IF;
IF (next_row.category_id IS NOT NULL AND (p_action='insert' OR next_row.category_id IS DISTINCT FROM old_row.category_id)
AND NOT EXISTS(SELECT FROM public.store_categories c WHERE c.id=next_row.category_id AND c.store_id=sid))
OR (next_row.subcategory_id IS NOT NULL AND (p_action='insert' OR next_row.subcategory_id IS DISTINCT FROM old_row.subcategory_id)
AND NOT EXISTS(SELECT FROM public.store_categories c WHERE c.id=next_row.subcategory_id AND c.store_id=sid)) THEN RAISE EXCEPTION 'PRODUCT_CATEGORY_DENIED'; END IF;
IF p_action='insert' THEN
INSERT INTO public.local_products(store_id,product_name,image_url,description,base_price,discount_price,currency,is_out_of_stock,stock_quantity,
low_stock_threshold,options,category_id,subcategory_id,is_featured,barcode,cost_price,updated_at)
VALUES(sid,next_row.product_name,next_row.image_url,next_row.description,next_row.base_price,next_row.discount_price,next_row.currency,next_row.is_out_of_stock,
next_row.stock_quantity,next_row.low_stock_threshold,next_row.options,next_row.category_id,next_row.subcategory_id,next_row.is_featured,next_row.barcode,next_row.cost_price,clock_timestamp()) RETURNING * INTO out_row;
ELSE
UPDATE public.local_products SET product_name=next_row.product_name,image_url=next_row.image_url,description=next_row.description,
base_price=next_row.base_price,discount_price=next_row.discount_price,currency=next_row.currency,is_out_of_stock=next_row.is_out_of_stock,
stock_quantity=next_row.stock_quantity,low_stock_threshold=next_row.low_stock_threshold,options=next_row.options,category_id=next_row.category_id,
subcategory_id=next_row.subcategory_id,is_featured=next_row.is_featured,barcode=next_row.barcode,cost_price=next_row.cost_price,updated_at=clock_timestamp()
WHERE id=p_id AND store_id=sid RETURNING * INTO out_row;
END IF;
RETURN jsonb_build_array(to_jsonb(out_row));
END $function$

CREATE OR REPLACE FUNCTION private.kinto_request_actor_v1()
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE h jsonb; role_name text; token text; actor_id text; actor jsonb; permissions jsonb; row_data jsonb; session_table text; id_column text; account_table text;
BEGIN
h:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
role_name:=h->>'x-kinto-role';token:=h->>'x-kinto-session';
IF token IS NULL OR token='' THEN RETURN NULL; END IF;
-- GET/HEAD are read-only transactions. Validate the existing hashed sessions without updating last_seen_at.
CASE role_name
WHEN 'customer' THEN session_table:='customer_review_sessions';id_column:='customer_id';account_table:='customers';
WHEN 'admin' THEN session_table:='admin_sessions_v147';id_column:='admin_id';account_table:='employees';
WHEN 'employee' THEN session_table:='employee_sessions_v143';id_column:='employee_id';account_table:='employees';
WHEN 'branch' THEN session_table:='branch_sessions_v148';id_column:='branch_id';account_table:='branches';
WHEN 'courier' THEN session_table:='courier_sessions_v149';id_column:='courier_id';account_table:='couriers';
ELSE RAISE EXCEPTION 'ORDER_SESSION_ROLE_DENIED' USING ERRCODE='42501'; END CASE;
EXECUTE format('SELECT %I::text FROM public.%I WHERE token_hash=extensions.digest($1,''sha256'') AND revoked_at IS NULL AND expires_at>now() LIMIT 1',id_column,session_table) INTO actor_id USING token;
IF actor_id IS NULL THEN RAISE EXCEPTION 'ORDER_SESSION_INVALID' USING ERRCODE='42501'; END IF;
EXECUTE format('SELECT to_jsonb(a) FROM public.%I a WHERE a.id::text=$1',account_table) INTO row_data USING actor_id;
IF row_data IS NULL OR lower(coalesce(row_data->>'is_active','true')) IN ('false','0')
OR lower(coalesce(row_data->>'active','true')) IN ('false','0') OR lower(coalesce(row_data->>'disabled','false')) IN ('true','1')
OR lower(coalesce(row_data->>'status','')) IN ('disabled','inactive','blocked','suspended','معطل','موقوف') THEN RAISE EXCEPTION 'ORDER_ACTOR_DISABLED' USING ERRCODE='42501'; END IF;
IF (role_name='admin' AND lower(coalesce(row_data->>'role','')) NOT IN ('admin','أدمن','ادمن'))
OR (role_name='employee' AND lower(coalesce(row_data->>'role','')) NOT IN ('employee','موظف')) THEN RAISE EXCEPTION 'ORDER_ACTOR_ROLE_INVALID' USING ERRCODE='42501'; END IF;
permissions:=row_data->'permissions';IF jsonb_typeof(permissions)='string' THEN permissions:=(permissions#>>'{}')::jsonb; END IF;
IF role_name='employee' AND (permissions->'orders'='false'::jsonb OR permissions->'manage_orders'='false'::jsonb) THEN
RAISE EXCEPTION 'ORDER_SESSION_PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
RETURN jsonb_build_object('id',actor_id,'role',role_name,'permissions',permissions,'name',row_data->>'name','phone',row_data->>'phone','branch_id',row_data->>'branch_id','courier_uuid',row_data->>'courier_uuid');

END $function$

CREATE OR REPLACE FUNCTION public.customer_submit_product_review_v132(p_session_token text, p_order_id uuid, p_product_id uuid, p_rating smallint, p_comment text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
v_verified jsonb;
v_item jsonb;
v_product public.local_products%rowtype;
v_review public.product_reviews%rowtype;
v_reference text;
v_segment_id uuid;
v_store_id uuid;
v_snapshot_store text;
v_comment text := trim(coalesce(p_comment, ''));
begin
v_customer_id :=
private.require_customer_review_session(p_session_token);

if p_rating is null or p_rating < 1 or p_rating > 5 then
raise exception 'INVALID_REVIEW_RATING';
end if;

if v_comment = '' then
raise exception 'REVIEW_COMMENT_REQUIRED';
end if;

if char_length(v_comment) > 2000 then
raise exception 'REVIEW_COMMENT_TOO_LONG';
end if;

-- لقطة الطلب المسلّم هي مصدر الحقيقة لاستحقاق التقييم.
v_verified := private.review_delivered_product(
p_order_id,
v_customer_id,
p_product_id
);

v_item := v_verified -> 'item';

v_reference := coalesce(
nullif(v_item ->> 'product_reference', ''),
p_product_id::text
);

begin
v_segment_id :=
nullif(v_verified ->> 'segment_id', '')::uuid;
exception
when invalid_text_representation then
v_segment_id := null;
end;

-- استخدام المنتج الحي إن كان موجوداً، مع السماح بتقييم
-- المشتريات التاريخية إذا حُذف المنتج من الكتالوج.
select p.*
into v_product
from public.local_products p
where p.id = p_product_id
limit 1;

if v_product.id is not null then
v_store_id := v_product.store_id;
end if;

if v_store_id is null and v_segment_id is not null then
select s.store_id
into v_store_id
from public.order_store_segments s
where s.id = v_segment_id
and s.order_id = p_order_id
limit 1;
end if;

if v_store_id is null then
v_snapshot_store :=
nullif(v_item ->> 'store_id', '');

if v_snapshot_store ~*
'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
then
select s.id
into v_store_id
from public.local_stores s
where s.id = v_snapshot_store::uuid
limit 1;
end if;
end if;

if v_store_id is null then
raise exception 'REVIEW_STORE_NOT_FOUND';
end if;

insert into public.product_reviews (
customer_id,
order_id,
order_store_segment_id,
store_id,
product_id,
product_reference,
product_name_snapshot,
product_image_snapshot,
rating,
comment,
verified_purchase,
moderation_status
)
values (
v_customer_id,
p_order_id,
v_segment_id,
v_store_id,
v_product.id,
v_reference,

coalesce(
nullif(v_item ->> 'product_name', ''),
v_product.product_name,
'المنتج'
),

coalesce(
nullif(v_item ->> 'product_image', ''),
v_product.image_url
),

p_rating,
v_comment,
true,
'pending'
)
on conflict (
customer_id,
order_id,
product_reference
)
do update set
rating = excluded.rating,
comment = excluded.comment,
product_name_snapshot =
excluded.product_name_snapshot,
product_image_snapshot =
excluded.product_image_snapshot,
moderation_status = 'pending',
moderation_note = null,
moderated_at = null,
moderated_by = null,
updated_at = now()
returning *
into v_review;

return jsonb_build_object(
'id', v_review.id,
'rating', v_review.rating,
'status', v_review.moderation_status,
'verified_purchase', v_review.verified_purchase,
'updated_at', v_review.updated_at
);
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_review_login_v132(p_identity text, p_password text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_customer public.customers%rowtype;
v_customer_json jsonb;
v_stored_password text;
v_password_ok boolean := false;
v_token text;
v_expires_at timestamptz := now() + interval '30 days';
v_identity_normalized text;
v_identity_hash bytea;
v_failed_attempts integer;
begin
if trim(coalesce(p_identity, '')) = ''
or coalesce(p_password, '') = '' then
return jsonb_build_object(
'ok', false,
'error', 'REVIEW_LOGIN_FIELDS_REQUIRED'
);
end if;

v_identity_normalized := lower(trim(p_identity));
v_identity_hash := digest(v_identity_normalized, 'sha256');

perform pg_advisory_xact_lock(
hashtextextended(encode(v_identity_hash, 'hex'), 132)
);

delete from public.customer_review_login_attempts
where attempted_at < now() - interval '24 hours';

select count(*)::integer
into v_failed_attempts
from public.customer_review_login_attempts a
where a.identity_hash = v_identity_hash
and a.attempted_at >= now() - interval '15 minutes';

if v_failed_attempts >= 5 then
return jsonb_build_object(
'ok', false,
'error', 'REVIEW_LOGIN_RATE_LIMITED',
'retry_after_seconds', 900
);
end if;

select c.*
into v_customer
from public.customers c
where lower(
trim(
coalesce(to_jsonb(c) ->> 'code', '')
)
) = lower(trim(p_identity))
or trim(
coalesce(to_jsonb(c) ->> 'phone', '')
) = trim(p_identity)
or lower(
trim(
coalesce(to_jsonb(c) ->> 'email', '')
)
) = lower(trim(p_identity))
limit 1;

if v_customer.id is null then
insert into public.customer_review_login_attempts(identity_hash)
values (v_identity_hash);

return jsonb_build_object(
'ok', false,
'error', 'REVIEW_LOGIN_INVALID'
);
end if;

v_customer_json := to_jsonb(v_customer);
v_stored_password := coalesce(
v_customer_json ->> 'password',
''
);

if v_stored_password = p_password then
v_password_ok := true;

elsif v_stored_password ~ '^\$2[aby]\$' then
begin
v_password_ok :=
crypt(p_password, v_stored_password) = v_stored_password;
exception
when others then
v_password_ok := false;
end;
end if;

if not v_password_ok then
insert into public.customer_review_login_attempts(identity_hash)
values (v_identity_hash);

return jsonb_build_object(
'ok', false,
'error', 'REVIEW_LOGIN_INVALID'
);
end if;

delete from public.customer_review_login_attempts
where identity_hash = v_identity_hash;

delete from public.customer_review_sessions
where customer_id = v_customer.id
and (
expires_at <= now()
or revoked_at is not null
);

v_token := encode(gen_random_bytes(32), 'hex');

insert into public.customer_review_sessions(
customer_id,
token_hash,
expires_at
)
values (
v_customer.id,
digest(v_token, 'sha256'),
v_expires_at
);

return jsonb_build_object(
'ok', true,
'session_token', v_token,
'expires_at', v_expires_at,
'customer', jsonb_build_object(
'id', v_customer.id,
'code', v_customer_json ->> 'code',
'name', v_customer_json ->> 'name'
)
);
end;
$function$

CREATE OR REPLACE FUNCTION private.review_delivered_product(p_order_id uuid, p_customer_id uuid, p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_order jsonb;
v_details jsonb;
v_item jsonb;
v_segment_id uuid;
begin
select to_jsonb(o)
into v_order
from public.orders o
where o.id = p_order_id
and trim(o.customer_id::text) = p_customer_id::text
and trim(coalesce(o.status, '')) = 'تم التسليم'
limit 1;

if v_order is null then
raise exception 'DELIVERED_ORDER_NOT_FOUND';
end if;

v_details := private.review_jsonb_object(v_order -> 'details');

if coalesce(v_details ->> 'product_id', '') = p_product_id::text then
v_item := jsonb_build_object(
'product_id', p_product_id::text,
'product_name',
coalesce(
nullif(v_details ->> 'product_name', ''),
'المنتج'
),
'product_image',
coalesce(
nullif(v_details ->> 'product_image', ''),
v_order ->> 'image_url'
),
'store_id', v_details ->> 'store_id',
'product_reference', p_product_id::text
);
else
select x.item
into v_item
from jsonb_array_elements(
case
when jsonb_typeof(v_details -> 'items') = 'array'
then v_details -> 'items'
else '[]'::jsonb
end
) as x(item)
where coalesce(x.item ->> 'product_id', '') = p_product_id::text
limit 1;
end if;

if v_item is null then
select x.item, s.id
into v_item, v_segment_id
from public.order_store_segments s
cross join lateral jsonb_array_elements(
coalesce(s.items_snapshot, '[]'::jsonb)
) as x(item)
where s.order_id = p_order_id
and coalesce(x.item ->> 'product_id', '') = p_product_id::text
limit 1;
end if;

if v_item is null then
raise exception 'PRODUCT_NOT_FOUND_IN_DELIVERED_ORDER';
end if;

return jsonb_build_object(
'item', v_item,
'segment_id', v_segment_id
);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_send_customer_notice_v414(p_session_token text, p_request_key uuid, p_title text, p_body text, p_kind text DEFAULT 'announcement'::text, p_customer_ids text[] DEFAULT NULL::text[], p_all_customers boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
aid text;
nid uuid;
cnt int;
k text;
begin
aid:=private.require_admin_session_v147(p_session_token);

if coalesce(aid,'')='' then
raise exception 'invalid admin session';
end if;

if p_request_key is null then
raise exception 'request key required';
end if;

if char_length(btrim(coalesce(p_title,'')))
not between 2 and 160 then
raise exception 'invalid title';
end if;

if char_length(btrim(coalesce(p_body,'')))
not between 2 and 4000 then
raise exception 'invalid body';
end if;

k:=lower(btrim(coalesce(p_kind,'')));

if k not in (
'announcement','campaign','discount','warning','policy'
) then
raise exception 'invalid kind';
end if;

if not coalesce(p_all_customers,false)
and (
coalesce(cardinality(p_customer_ids),0)=0
or cardinality(p_customer_ids)>500
) then
raise exception 'select 1 to 500 customers';
end if;

insert into public.kinto_customer_admin_notices(
request_key,title,body,kind,created_by
)
values(
p_request_key,btrim(p_title),btrim(p_body),k,aid
)
on conflict(request_key) do nothing
returning id into nid;

if nid is null then
select id into nid
from public.kinto_customer_admin_notices
where request_key=p_request_key
and created_by=aid;

if nid is null then
raise exception 'request key already used';
end if;

return jsonb_build_object(
'ok',true,
'notice_id',nid,
'duplicate',true,
'recipients',(
select count(*)
from public.kinto_customer_admin_notice_recipients
where notice_id=nid
)
);
end if;

insert into public.kinto_customer_admin_notice_recipients(
notice_id,customer_id
)
select nid,c.id::text
from public.customers c
where coalesce(p_all_customers,false)
or c.id::text=any(p_customer_ids)
on conflict do nothing;

get diagnostics cnt=row_count;

if cnt=0 then
raise exception 'no valid recipients';
end if;

return jsonb_build_object(
'ok',true,
'notice_id',nid,
'recipients',cnt,
'duplicate',false
);
end $function$

CREATE OR REPLACE FUNCTION public.admin_customer_notices_v415(p_session_token text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 8)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
aid text;
pg int;
sz int;
begin
aid:=private.require_admin_session_v147(p_session_token);

if coalesce(aid,'')='' then
raise exception 'invalid admin session';
end if;

pg:=greatest(1,least(coalesce(p_page,1),100000));
sz:=greatest(1,least(coalesce(p_page_size,8),20));

return jsonb_build_object(
'total',(
select count(*)
from public.kinto_customer_admin_notices
),
'items',coalesce((
select jsonb_agg(
to_jsonb(x)
order by x.created_at desc,x.id desc
)
from (
select
n.id,n.title,n.body,n.kind,n.created_at,
(
select count(*)
from public.kinto_customer_admin_notice_recipients r
where r.notice_id=n.id
) recipients,
(
select count(*)
from public.kinto_customer_admin_notice_recipients r
where r.notice_id=n.id
and r.read_at is not null
) read_count
from public.kinto_customer_admin_notices n
order by n.created_at desc,n.id desc
limit sz
offset (pg-1)*sz
) x
),'[]'::jsonb)
);
end $function$

CREATE OR REPLACE FUNCTION public.customer_upload_review_image_v139(p_session_token text, p_review_id uuid, p_mime_type text, p_base64 text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
v_review public.product_reviews%rowtype;
v_bytes bytea;
v_image_id uuid := gen_random_uuid();
v_sort_order smallint;
begin
v_customer_id :=
private.require_customer_review_session(p_session_token);

if p_mime_type not in (
'image/jpeg',
'image/png',
'image/webp'
) then
raise exception 'IMAGE_TYPE_NOT_ALLOWED';
end if;

if p_base64 is null
or length(p_base64) > 7000000
then
raise exception 'IMAGE_SIZE_NOT_ALLOWED';
end if;

begin
v_bytes := decode(p_base64, 'base64');
exception
when others then
raise exception 'IMAGE_BASE64_INVALID';
end;

if octet_length(v_bytes) < 12
or octet_length(v_bytes) > 5242880
then
raise exception 'IMAGE_SIZE_NOT_ALLOWED';
end if;

if not (
(
p_mime_type = 'image/jpeg'
and substring(v_bytes from 1 for 3)
= decode('ffd8ff', 'hex')
)
or
(
p_mime_type = 'image/png'
and substring(v_bytes from 1 for 8)
= decode('89504e470d0a1a0a', 'hex')
)
or
(
p_mime_type = 'image/webp'
and substring(v_bytes from 1 for 4)
= convert_to('RIFF', 'UTF8')
and substring(v_bytes from 9 for 4)
= convert_to('WEBP', 'UTF8')
)
) then
raise exception 'IMAGE_SIGNATURE_INVALID';
end if;

perform pg_advisory_xact_lock(
hashtextextended(p_review_id::text, 139)
);

select *
into v_review
from public.product_reviews
where id = p_review_id
and customer_id = v_customer_id
for update;

if v_review.id is null then
raise exception 'REVIEW_NOT_FOUND';
end if;

if v_review.moderation_status
not in ('pending', 'rejected')
then
raise exception 'REVIEW_IMAGES_LOCKED';
end if;

select slot::smallint
into v_sort_order
from generate_series(0, 4) slot
where not exists (
select 1
from public.product_review_images i
where i.review_id = p_review_id
and i.sort_order = slot
)
order by slot
limit 1;

if v_sort_order is null then
raise exception 'REVIEW_IMAGE_LIMIT_REACHED';
end if;

insert into public.product_review_images (
id,
review_id,
storage_path,
mime_type,
byte_size,
sort_order,
moderation_status
)
values (
v_image_id,
p_review_id,
'database://'
|| p_review_id::text
|| '/'
|| v_image_id::text,
p_mime_type,
octet_length(v_bytes),
v_sort_order,
'pending'
);

insert into public.product_review_image_payloads (
image_id,
image_bytes,
content_sha256
)
values (
v_image_id,
v_bytes,
digest(v_bytes, 'sha256')
);

return jsonb_build_object(
'ok', true,
'id', v_image_id,
'sort_order', v_sort_order,
'status', 'pending'
);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_customer_notice_v417(p_session_token text, p_notice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE
aid TEXT;
deleted_count INTEGER;
BEGIN

-- 1. Verify admin session
aid := private.require_admin_session_v147(p_session_token);

IF COALESCE(aid, '') = '' THEN
RAISE EXCEPTION 'invalid admin session';
END IF;

-- 2. Validate notice ID
IF p_notice_id IS NULL THEN
RAISE EXCEPTION 'notice id required';
END IF;

-- 3. Prevent deleting notices with attachments
-- until secure Storage cleanup is implemented
IF EXISTS (
SELECT 1
FROM information_schema.columns
WHERE table_schema = 'public'
AND table_name = 'kinto_customer_admin_notices'
AND column_name = 'attachment_path'
) THEN

IF EXISTS (
SELECT 1
FROM public.kinto_customer_admin_notices n
WHERE n.id = p_notice_id
AND TO_JSONB(n)->>'attachment_path' IS NOT NULL
) THEN
RAISE EXCEPTION
'attachment cleanup required before notice deletion';
END IF;

END IF;

-- 4. Delete notice
-- Recipients and read states are removed via FK CASCADE
DELETE FROM public.kinto_customer_admin_notices
WHERE id = p_notice_id;

GET DIAGNOSTICS deleted_count = ROW_COUNT;

-- 5. Return result
RETURN JSONB_BUILD_OBJECT(
'ok', TRUE,
'deleted', deleted_count > 0
);

END;
$function$

CREATE OR REPLACE FUNCTION public.product_review_helpful_toggle_v141(p_review_id uuid, p_visitor_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
v_hash bytea;
v_liked boolean;
v_count integer;
begin
if p_visitor_token is null
or char_length(p_visitor_token) not between 20 and 200
then
raise exception 'INVALID_VISITOR_TOKEN';
end if;


if not exists (
select 1
from public.product_reviews r
where r.id = p_review_id
and r.moderation_status = 'published'
) then
raise exception 'PUBLISHED_REVIEW_NOT_FOUND';
end if;


v_hash := digest(
p_visitor_token,
'sha256'
);


perform pg_advisory_xact_lock(
hashtextextended(
p_review_id::text || encode(v_hash, 'hex'),
141
)
);


if exists (
select 1
from public.product_review_helpful_votes
where review_id = p_review_id
and visitor_hash = v_hash
) then

delete from public.product_review_helpful_votes
where review_id = p_review_id
and visitor_hash = v_hash;

v_liked := false;

else

insert into public.product_review_helpful_votes (
review_id,
visitor_hash
)
values (
p_review_id,
v_hash
);

v_liked := true;

end if;


select count(*)::integer
into v_count
from public.product_review_helpful_votes
where review_id = p_review_id;


return jsonb_build_object(
'review_id', p_review_id,
'liked', v_liked,
'helpful_count', v_count
);
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_finalize_review_image_upload_v150(p_session_token text, p_ticket_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'storage', 'pg_temp'
AS $function$
declare
v_customer_id uuid;
v_ticket private.product_review_upload_tickets_v150%rowtype;
v_image_id uuid := gen_random_uuid();
v_sort smallint;
begin
v_customer_id :=
private.require_customer_review_session(p_session_token);

select *
into v_ticket
from private.product_review_upload_tickets_v150
where id = p_ticket_id
and customer_id = v_customer_id
and used_at is null
and expires_at > now()
for update;

if v_ticket.id is null then
raise exception 'REVIEW_UPLOAD_TICKET_INVALID';
end if;

if not exists (
select 1
from storage.objects o
where o.bucket_id = 'product-review-images'
and o.name = v_ticket.storage_path
and lower(coalesce(o.metadata ->> 'mimetype', ''))
= v_ticket.mime_type
and coalesce((o.metadata ->> 'size')::integer, 0)
= v_ticket.byte_size
) then
raise exception 'REVIEW_STORAGE_OBJECT_NOT_FOUND';
end if;

perform pg_advisory_xact_lock(
hashtextextended(v_ticket.review_id::text, 150)
);

select slot::smallint
into v_sort
from generate_series(0, 4) slot
where not exists (
select 1
from public.product_review_images i
where i.review_id = v_ticket.review_id
and i.sort_order = slot
)
order by slot
limit 1;

if v_sort is null then
raise exception 'REVIEW_IMAGE_LIMIT_REACHED';
end if;

insert into public.product_review_images (
id,
review_id,
storage_path,
mime_type,
byte_size,
sort_order,
moderation_status
)
values (
v_image_id,
v_ticket.review_id,
v_ticket.storage_path,
v_ticket.mime_type,
v_ticket.byte_size,
v_sort,
'pending'
);

update private.product_review_upload_tickets_v150
set used_at = now()
where id = v_ticket.id;

return jsonb_build_object(
'ok', true,
'id', v_image_id,
'storage_path', v_ticket.storage_path,
'byte_size', v_ticket.byte_size,
'sort_order', v_sort,
'status', 'pending'
);
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_profit_capture_cost_v164(p_session_token text, p_expected_lines jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
sid uuid:=private.require_vendor_session(p_session_token);
report jsonb;
o jsonb;
total numeric;
segid uuid;
begin
perform 1 from public.local_stores
where id=sid for update;

report:=public.vendor_profit_report_v164(p_session_token);
o:=report->'order';

if o is null or o='null'::jsonb then
raise exception 'PROFIT_ORDER_NOT_FOUND';
end if;

segid:=(o->>'segment_id')::uuid;

if (o->>'cost_frozen')::boolean then
return report;
end if;

if p_expected_lines is null
or p_expected_lines<>o->'cost_lines' then
raise exception 'PROFIT_COST_PREVIEW_CHANGED';
end if;

if not coalesce((o->>'cost_ready')::boolean,false) then
raise exception 'PROFIT_COST_OR_ORDER_FX_MISSING';
end if;

select sum((x->>'cost_local')::numeric)
into total
from jsonb_array_elements(o->'cost_lines') x;

if total is null then
raise exception 'PROFIT_COST_MISSING';
end if;

insert into private.vendor_profit_costs_v164(
segment_id,store_id,lines,total_cost_local
)
values(segid,sid,o->'cost_lines',total);

return public.vendor_profit_report_v164(p_session_token);
end
$function$

