CREATE OR REPLACE FUNCTION private.vendor_profit_detail_v165(sid uuid, p_segment_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
seg record; item jsonb; unit jsonb; line jsonb; frozen record;
financial jsonb; archived text; lines jsonb:='[]';
expenses jsonb; expense_total numeric;
cost numeric; fx numeric; qty numeric;
idx integer:=0; cost_total numeric:=0; complete boolean:=true;
begin
select s.*,o.order_code,o.created_at order_created_at into seg
from public.order_store_segments s
join public.orders o on o.id=s.order_id
where s.store_id=sid and s.id=p_segment_id
and s.commission_snapshot->>'version'='v161'
and s.payment_confirmed and s.store_status='تم التسليم';

if not found then
return jsonb_build_object('order',null,'expenses','[]'::jsonb);
end if;

financial:=seg.commission_snapshot;

if seg.vendor_settlement_archive_id is not null then
select a.statement_no,x.value into archived,line
from public.vendor_settlement_archives_v163 a
cross join lateral jsonb_array_elements(a.segment_ids) x(value)
where a.id=seg.vendor_settlement_archive_id
and a.store_id=sid
and x.value->>'segment_id'=seg.id::text;

if not found then
raise exception 'PROFIT_ARCHIVE_LINE_MISSING';
end if;

financial:=line||jsonb_build_object('currency',seg.currency);
end if;

select * into frozen
from private.vendor_profit_costs_v164
where segment_id=seg.id and store_id=sid;

if found then
lines:=frozen.lines;
cost_total:=frozen.total_cost_local;
else
if coalesce(jsonb_typeof(seg.items_snapshot),'null')<>'array'
or jsonb_array_length(seg.items_snapshot)=0 then
complete:=false;
end if;

for item in
select value from jsonb_array_elements(
case when jsonb_typeof(seg.items_snapshot)='array'
then seg.items_snapshot else '[]'::jsonb end
)
loop
qty:=nullif(item->>'quantity','')::numeric;
if qty=0 then continue;end if;
idx:=idx+1;cost:=null;fx:=null;

select p.cost_price into cost
from public.local_products p
where p.id=private.v94_uuid(item->>'product_id')
and p.store_id=sid;

select x.value into unit
from private.vendor_profit_units_v165 u
cross join lateral jsonb_array_elements(u.units) x(value)
where u.order_id=seg.order_id and u.store_id=sid
and x.value->>'product_id'=item->>'product_id'
limit 1;

if found then
fx:=nullif(unit->>'exchange_rate','')::numeric;
if unit->>'unit_cost_usd' is not null then
cost:=(unit->>'unit_cost_usd')::numeric;
end if;
else
fx:=nullif(item->'pricing_snapshot'->>'exchange_rate','')::numeric;
end if;

qty:=nullif(item->>'quantity','')::numeric;
if cost is null or cost<0 or fx is null or fx<=0
or qty is null or qty<=0 then complete:=false;end if;

lines:=lines||jsonb_build_array(jsonb_build_object(
'item_no',idx,
'product_id',item->>'product_id',
'product_name',item->>'product_name',
'quantity',qty,
'unit_cost_usd',cost,
'exchange_rate',fx,
'cost_local',case when cost>=0 and fx>0 and qty>0
then round(cost*fx*qty,2) else null end
));
end loop;
end if;

if jsonb_array_length(lines)=0 then complete:=false;end if;

select
coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc),'[]'::jsonb),
coalesce(sum(e.amount),0)
into expenses,expense_total
from private.vendor_profit_expenses_v164 e
where e.store_id=sid and e.segment_id=seg.id;

return jsonb_build_object(
'order',jsonb_build_object(
'segment_id',seg.id,'order_code',seg.order_code,
'created_at',seg.order_created_at,'currency',seg.currency,
'financial',financial,
'archive_id',seg.vendor_settlement_archive_id,
'statement_no',archived,'cost_lines',lines,
'cost_frozen',frozen.segment_id is not null,
'cost_ready',complete,
'total_cost_local',case when frozen.segment_id is not null
then cost_total else null end,
'cost_captured_at',frozen.captured_at
),
'expenses',expenses,'expense_total',expense_total
);
end $function$

CREATE OR REPLACE FUNCTION private.require_employee_session_v143(p_session_token text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_employee_id text;
begin
if trim(coalesce(p_session_token, '')) = '' then
raise exception 'EMPLOYEE_SESSION_REQUIRED';
end if;

select s.employee_id into v_employee_id
from public.employee_sessions_v143 s
where s.token_hash = digest(p_session_token, 'sha256')
and s.revoked_at is null
and s.expires_at > now()
limit 1;

if v_employee_id is null then
raise exception 'EMPLOYEE_SESSION_INVALID';
end if;

update public.employee_sessions_v143
set last_seen_at = now()
where token_hash = digest(p_session_token, 'sha256');

return v_employee_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.kinto_deals_v1_assert_product_available_g21b(p_store_id uuid, p_product_id uuid, p_selected_options jsonb, p_quantity integer DEFAULT 1)
RETURNS void
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare p public.local_products%rowtype; probe jsonb; opts jsonb;
begin
if p_quantity is null or p_quantity<1 then raise exception 'DEALS_INVALID_STOCK_QUANTITY' using errcode='22023'; end if;
select * into p from public.local_products where id=p_product_id and store_id=p_store_id;
if not found then raise exception 'DEALS_PRODUCT_OWNERSHIP_REQUIRED' using errcode='23514'; end if;
if coalesce(p.is_out_of_stock,false) or (p.stock_quantity is not null and p.stock_quantity<p_quantity) then
raise exception 'DEALS_PRODUCT_OUT_OF_STOCK' using errcode='P0001'; end if;
probe:=jsonb_build_object(
'color',coalesce(p_selected_options->>'color',''),
'size',coalesce(p_selected_options->>'size',''),
'volume',coalesce(p_selected_options->>'volume',''));
begin
opts:=public.meshwar_adjust_variant_stock(coalesce(p.options,'{}'::jsonb),probe,p_quantity,-1);
opts:=public.meshwar_adjust_matrix_stock(opts,probe,p_quantity,-1);
exception when others then
raise exception 'DEALS_PRODUCT_VARIANT_OUT_OF_STOCK' using errcode='P0001';
end;
end;
$function$

CREATE OR REPLACE FUNCTION public.customer_admin_notices_v422(p_session_token text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 8)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
