result:=public.customer_admin_notices_v414(
p_session_token,p_page,p_page_size
);

return jsonb_set(result,'{items}',coalesce((
select jsonb_agg(item || jsonb_build_object(
'stores',coalesce((
select jsonb_agg(jsonb_build_object(
