CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_products_g4(p_session_token text, p_search text DEFAULT ''::text, p_limit integer DEFAULT 30)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_store uuid; v_query text; v_rows jsonb;
begin
v_store:=private.require_vendor_session(p_session_token);
if v_store is null then raise exception 'DEALS_VENDOR_SESSION_REQUIRED' using errcode='28000'; end if;
if p_limit is null or p_limit not between 1 and 50 then
raise exception 'DEALS_INVALID_PRODUCT_LIMIT' using errcode='22023';
end if;

v_query:=left(btrim(coalesce(p_search,'')),70);

select coalesce(jsonb_agg(to_jsonb(q) order by q.product_name,q.id),'[]'::jsonb)
into v_rows
from (
select p.id,p.product_name,p.image_url,p.barcode,p.currency,
p.base_price,p.discount_price,p.is_out_of_stock,p.stock_quantity
from public.local_products p
where p.store_id=v_store
and not coalesce(p.is_out_of_stock,false)
and (p.stock_quantity is null or p.stock_quantity>0)
and (
v_query=''
or position(lower(v_query) in lower(coalesce(p.product_name,'')))>0
or position(lower(v_query) in lower(coalesce(p.barcode,'')))>0
)
order by p.product_name,p.id
limit p_limit
) q;

return jsonb_build_object(
'store_id',v_store,
'items',v_rows,
'read_only',true
);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_payment_admin_g16(p_session_token text, p_action text DEFAULT 'list'::text, p_id uuid DEFAULT NULL::uuid, p_method_type text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_recipient_name text DEFAULT NULL::text, p_account_reference text DEFAULT NULL::text, p_instructions text DEFAULT NULL::text, p_enabled boolean DEFAULT NULL::boolean)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_admin text;v_row public.kinto_payment_methods_g16%rowtype;v_settings boolean;v_items jsonb;
begin
v_admin:=private.require_admin_session_v147(p_session_token);
if nullif(btrim(v_admin),'') is null then raise exception 'ADMIN_SESSION_REQUIRED' using errcode='28000'; end if;
if p_action='create' then
if p_method_type='manual' then raise exception 'EMAIL_VERIFICATION_REQUIRED' using errcode='42501'; end if;
if p_method_type<>'gateway' then raise exception 'INVALID_METHOD_TYPE' using errcode='22023'; end if;
insert into public.kinto_payment_methods_g16(method_type,label,provider,is_enabled)
