CREATE OR REPLACE FUNCTION public.admin_moderate_product_review_v138(p_admin_id uuid, p_review_id uuid, p_decision text, p_note text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
v_admin uuid;

v_decision text :=
lower(trim(coalesce(p_decision, '')));

v_review public.product_reviews%rowtype;
v_note text;
v_deleted integer := 0;
v_paths text[];
begin
v_admin :=
private.require_product_review_admin_v138(p_admin_id);

if v_decision not in (
'published',
'rejected',
'hidden'
) then
raise exception 'INVALID_REVIEW_DECISION';
end if;

v_note :=
nullif(trim(coalesce(p_note, '')), '');

if v_decision = 'rejected'
and v_note is null then
v_note :=
'المحتوى لا يستوفي إرشادات تقييمات KINTO.';
end if;

if char_length(coalesce(v_note, '')) > 1000 then
raise exception 'MODERATION_NOTE_TOO_LONG';
end if;

update public.product_reviews
set
moderation_status = v_decision,
moderation_note = v_note,
moderated_at = now(),
moderated_by = v_admin,
updated_at = now()
where id = p_review_id
returning *
into v_review;

if v_review.id is null then
raise exception 'REVIEW_NOT_FOUND';
end if;

if v_decision = 'rejected' then
select coalesce(
array_agg(storage_path)
filter (
where storage_path not like 'database://%'
),
array[]::text[]
)
into v_paths
from public.product_review_images
where review_id = p_review_id;

insert into private.product_review_storage_deletions_v150 (
storage_path
)
select unnest(v_paths)
on conflict (storage_path)
do update
set expires_at = now() + interval '1 day';

delete from public.product_review_images
where review_id = p_review_id;

get diagnostics v_deleted = row_count;
else
update public.product_review_images
set
moderation_status = v_decision,
moderated_at = now(),
moderated_by = v_admin
where review_id = p_review_id;
end if;

return jsonb_build_object(
'id', v_review.id,
'status', v_review.moderation_status,
'moderated_at', v_review.moderated_at,
'deleted_images', v_deleted,
'deleted_storage_paths',
coalesce(to_jsonb(v_paths), '[]'::jsonb),
'bucket', 'product-review-images'
);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_prepare_customer_notice_delete_v425(p_session_token text, p_notice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE aid text; path text; found_notice boolean;
BEGIN
aid:=private.require_admin_session_v147(p_session_token);
IF coalesce(aid,'')='' OR p_notice_id IS NULL THEN RAISE EXCEPTION 'invalid request'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(p_notice_id::text,425));
SELECT true INTO found_notice FROM public.kinto_customer_admin_notices
WHERE id=p_notice_id FOR UPDATE;
IF NOT coalesce(found_notice,false) THEN
RETURN jsonb_build_object('ok',true,'already_deleted',true);
END IF;
UPDATE public.kinto_customer_admin_notices
SET media_delete_pending_at=coalesce(media_delete_pending_at,now())
WHERE id=p_notice_id;
SELECT object_path INTO path FROM public.kinto_customer_notice_assets_v418
WHERE notice_id=p_notice_id;
RETURN jsonb_build_object('ok',true,'pending',true,'has_asset',path IS NOT NULL);
END $function$

CREATE OR REPLACE FUNCTION public.customer_mark_notifications_read_v155(p_session_token text, p_notification_keys text[])
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_customer uuid;
v_keys text[];
v_marked integer := 0;
begin
v_customer :=
private.require_customer_review_session(p_session_token);

select coalesce(
array_agg(distinct k),
array[]::text[]
)
into v_keys
from unnest(
coalesce(p_notification_keys, array[]::text[])
) k
where char_length(k) between 3 and 500;

if cardinality(v_keys) > 100 then
raise exception 'TOO_MANY_NOTIFICATION_KEYS';
end if;

insert into public.customer_notification_reads_v155 (
customer_id,
notification_key,
read_at
)
select
v_customer,
k,
now()
from unnest(v_keys) k
on conflict (customer_id, notification_key)
do update set read_at = excluded.read_at;

get diagnostics v_marked = row_count;

delete from public.customer_notification_reads_v155 r
where r.customer_id = v_customer
and r.notification_key in (
select notification_key
from public.customer_notification_reads_v155
where customer_id = v_customer
order by read_at desc
offset 500
);

return jsonb_build_object(
'ok', true,
'marked_count', v_marked
);
end;
$function$

