CREATE OR REPLACE FUNCTION public.kinto_deals_v1_vendor_set_product_options_g20(p_session_token text, p_campaign_id uuid, p_product_options jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store uuid;
v_count integer;
v_item record;
begin
v_store:=private.require_vendor_session(p_session_token);

if v_store is null then
raise exception 'DEALS_VENDOR_SESSION_REQUIRED'
using errcode='28000';
end if;

if jsonb_typeof(p_product_options) is distinct from 'object' then
raise exception 'DEALS_PRODUCT_OPTIONS_OBJECT_REQUIRED'
using errcode='22023';
end if;

if not exists(
select 1
from public.kinto_deals_v1_campaigns c
where c.id=p_campaign_id
and c.store_id=v_store
and c.status='draft'
and not exists(
select 1
from public.kinto_deals_v1_submissions s
where s.campaign_id=c.id
)
) then
raise exception 'DEALS_DRAFT_NOT_EDITABLE'
using errcode='40001';
end if;

if exists(
select 1
from jsonb_each(p_product_options) j
where jsonb_typeof(j.value)<>'object'
or length(j.value::text)>3000
or not exists(
select 1
from public.kinto_deals_v1_products cp
where cp.campaign_id=p_campaign_id
and cp.product_id::text=j.key
)
) then
raise exception 'DEALS_INVALID_PRODUCT_OPTIONS'
using errcode='22023';
end if;

for v_item in
select
cp.product_id,
coalesce(
p_product_options->cp.product_id::text,
'{}'::jsonb
) selected_options
from public.kinto_deals_v1_products cp
where cp.campaign_id=p_campaign_id
loop
perform private.kinto_deals_v1_assert_product_available_g21b(
v_store,
v_item.product_id,
v_item.selected_options,
1
);
end loop;

update public.kinto_deals_v1_products cp
set selected_options=coalesce(
p_product_options->cp.product_id::text,
'{}'::jsonb
)
where cp.campaign_id=p_campaign_id;

get diagnostics v_count=row_count;

return jsonb_build_object(
'ok',true,
'campaign_id',p_campaign_id,
'product_count',v_count
);
end;
$function$

CREATE OR REPLACE FUNCTION private.invoice_stock_projection_v59(p_order orders)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
d jsonb := coalesce(nullif(p_order.details::text,'')::jsonb,'{}'::jsonb);
history jsonb := d->'stock_adjustment_v58'->'display_items';
rebuilt jsonb := '[]'::jsonb;
rebuilt_stores jsonb := '[]'::jsonb;
x jsonb; s jsonb; source_order public.orders%rowtype;
requested integer; original_total numeric; projected jsonb;
source_total numeric := 0; source_qty integer := 0; source_count integer := 0;
sid text;
begin
if jsonb_typeof(history) is distinct from 'array' then
return private.invoice_stock_projection_v58(p_order);
end if;

for x in select value from jsonb_array_elements(history) loop
requested := coalesce(
nullif(x->>'stock_requested_quantity_v58','')::integer,
nullif(x->>'quantity','')::integer,
0
);
if requested < 1 then continue; end if;

original_total := coalesce(
nullif(x->>'stock_original_line_total_v59','')::numeric,
coalesce(nullif(x->>'unit_price_local','')::numeric,0) * requested
);

x := jsonb_set(x,'{quantity}',to_jsonb(requested),true);
x := jsonb_set(x,'{line_total_local}',to_jsonb(original_total),true);
x := x - '_invoiceRequestedV57' - '_invoiceAvailableV57';

rebuilt := rebuilt || jsonb_build_array(x);
source_total := source_total + original_total;
source_qty := source_qty + requested;
source_count := source_count + 1;
end loop;

if rebuilt = '[]'::jsonb then
return private.invoice_stock_projection_v58(p_order);
end if;

for s in select value from jsonb_array_elements(coalesce(d->'stores','[]'::jsonb)) loop
sid := s->>'store_id';

s := s || jsonb_build_object(
'subtotal_local', coalesce((
select sum((item->>'line_total_local')::numeric)
from jsonb_array_elements(rebuilt) item
where item->>'store_id' = sid
),0),
'quantity', coalesce((
select sum((item->>'quantity')::integer)
from jsonb_array_elements(rebuilt) item
where item->>'store_id' = sid
),0),
'item_count', coalesce((
select count(*)
from jsonb_array_elements(rebuilt) item
where item->>'store_id' = sid
),0)
);

rebuilt_stores := rebuilt_stores || jsonb_build_array(s);
end loop;

d := jsonb_set(d,'{items}',rebuilt,true);
d := jsonb_set(d,'{stores}',rebuilt_stores,true);
d := d || jsonb_build_object(
'quantity',source_qty,
'requested_quantity',source_qty,
'item_count',source_count,
'customer_total_local',source_total
);
d := d - 'stock_adjustment_v58';

source_order := p_order;
source_order.details := d::text;
source_order.total_price := coalesce(
nullif(
p_order.details::jsonb->'stock_adjustment_v58'->>'previous_total',
''
)::numeric,
source_total
);

projected := private.invoice_stock_projection_v58(source_order);

projected := jsonb_set(
projected,
'{changed}',
to_jsonb(
(projected->'details') is distinct from coalesce(
nullif(p_order.details::text,'')::jsonb,
'{}'::jsonb
)
or (projected->>'total_price')::numeric is distinct from p_order.total_price
),
true
);

return projected;
end;
$function$

CREATE OR REPLACE FUNCTION public.meshwar_independent_vendor_order_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
declare
v_old jsonb := coalesce(nullif(old.details::text,'')::jsonb,'{}'::jsonb);
v_new jsonb := coalesce(nullif(new.details::text,'')::jsonb,v_old);
v_key text;
v_immutable constant text[] := array[
'source','checkout_contract','checkout_group_id','vendor_order_id',
'items','stores','store_id','store_name','quantity','requested_quantity',
'item_count','customer_scope_id','customer_scope_type','submitted_at',
'customer_total_local','store_subtotal','currency','shipping_snapshot'
];
v_paid boolean;
correction jsonb;
begin
if current_setting('kinto.invoice_adjustment_v58',true) = old.id::text
and old.status = any(array[
'بانتظار موافقة العميل',
'بانتظار موافقة الزبون',
'بانتظار التسعير',
'تم التسعير / بانتظار موافقة العميل'
])
and new.status = old.status
and coalesce(v_old->>'bundle_stock_lifecycle_state','') <> 'deducted'
then
correction := private.invoice_stock_projection_v59(old);

if correction->>'changed' = 'true'
and v_new = correction->'details'
and new.total_price = (correction->>'total_price')::numeric
then
return new;
end if;

raise exception 'V59_CORRECTION_MISMATCH';
end if;

foreach v_key in array v_immutable loop
if v_old ? v_key then
v_new := jsonb_set(v_new,array[v_key],v_old->v_key,true);
end if;
end loop;

if new.status = 'تمت الموافقة - بانتظار الدفع'
and old.status is distinct from new.status
and coalesce(v_old->>'bundle_stock_lifecycle_state','') <> 'deducted'
and old.status <> 'تم التسديد'
and current_setting('kinto.invoice_approval_v58',true) is distinct from old.id::text
then
correction := private.invoice_stock_projection_v59(old);

if correction->>'changed' = 'true' then
raise exception 'V58_REVIEW_INVOICE_REQUIRED';
end if;
end if;

if v_old ? 'stock_adjustment_v58' then
v_new := jsonb_set(
v_new,
'{stock_adjustment_v58}',
v_old->'stock_adjustment_v58',
true
);
new.total_price := old.total_price;
else
v_new := v_new - 'stock_adjustment_v58';
end if;

v_paid := coalesce(v_old->>'bundle_stock_lifecycle_state','')='deducted'
or old.status='تم التسديد';

if coalesce(v_old->>'bundle_stock_lifecycle_state','')='deducted' then
v_new := jsonb_set(
v_new,
'{bundle_stock_lifecycle_state}',
'"deducted"'::jsonb,
true
);

foreach v_key in array array[
'bundle_stock_deducted_at',
'bundle_variant_stock_deducted'
]::text[] loop
if v_old ? v_key then
v_new := jsonb_set(v_new,array[v_key],v_old->v_key,true);
end if;
end loop;
end if;

if v_paid
and new.status is distinct from old.status
and new.status = any(array[
'مرفوض','رفض التسليم','رفض الطلب',
'ملغي من قبل العميل','ملغي','ملغى'
]::text[])
then
raise exception 'V94 paid independent vendor order cannot be cancelled or rejected'
using errcode='P0001';
end if;

new.details := v_new::text;
return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.employee_chat_send_v61(p_session_token text, p_customer_id uuid, p_message text DEFAULT NULL::text, p_file_url text DEFAULT NULL::text)
