$function$

CREATE OR REPLACE FUNCTION public.admin_save_vendor_finance_v161(p_session_token text, p_segment_id uuid, p_other numeric, p_payment_status text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
snap jsonb;
gross numeric;
rate numeric;
status text := case
when lower(trim(coalesce(p_payment_status, ''))) in ('paid', 'مدفوع', 'settled')
then 'paid'
else 'pending'
end;
begin
perform private.require_admin_session_v147(p_session_token);

if coalesce(p_other, -1) < 0 then
raise exception 'V161_OTHER_INVALID';
end if;

select commission_snapshot
into snap
from public.order_store_segments
where id = p_segment_id
for update;

if coalesce(snap ->> 'version', '') <> 'v161' then
raise exception 'V161_SEGMENT_NOT_FOUND';
end if;

gross := coalesce((snap ->> 'gross_amount')::numeric, 0);
rate := coalesce((snap ->> 'commission_rate')::numeric, 0);

snap := snap || jsonb_build_object(
'other_deductions', p_other,
'vendor_payment_status', status,
'net_amount', round(gross - (gross * rate / 100) - p_other, 2),
'vendor_paid_at', case when status = 'paid' then now() else null end
);

update public.order_store_segments
set
commission_snapshot = snap,
vendor_payment_status = status,
updated_at = now()
where id = p_segment_id;

return snap;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_archive_vendor_settlement_v163(p_session_token text, p_store_id uuid, p_segment_ids uuid[], p_platform_logo_url text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_store record;
v_rows jsonb;
v_count integer;
v_gross numeric;
v_commission numeric;
v_other numeric;
v_net numeric;
v_id uuid := gen_random_uuid();
v_no text;
begin
perform private.require_admin_session_v147(p_session_token);

if p_store_id is null
or coalesce(array_length(p_segment_ids, 1), 0) = 0 then
raise exception 'V163_ARCHIVE_SELECTION_REQUIRED';
end if;

select id, store_name, logo_url
into v_store
from public.local_stores
where id = p_store_id;

if not found then
raise exception 'V163_STORE_NOT_FOUND';
end if;

select
count(*),
coalesce(sum(coalesce((commission_snapshot->>'gross_amount')::numeric, subtotal_local, 0)), 0),
coalesce(sum(coalesce((commission_snapshot->>'commission_amount')::numeric, 0)), 0),
coalesce(sum(coalesce((commission_snapshot->>'other_deductions')::numeric, 0)), 0)
into v_count, v_gross, v_commission, v_other
from (
select *
from public.order_store_segments
where id = any(p_segment_ids)
and store_id = p_store_id
and vendor_settlement_archive_id is null
and vendor_payment_status = 'paid'
and commission_snapshot->>'version' = 'v161'
for update
) locked;

if v_count <> array_length(p_segment_ids, 1) then
raise exception 'V163_ONLY_UNARCHIVED_PAID_V161_SEGMENTS_ALLOWED';
end if;

v_net := round(v_gross - v_commission - v_other, 2);
v_no := 'KINTO-STL-' || to_char(now(), 'YYYYMMDD')
|| '-' || upper(substr(replace(v_id::text, '-', ''), 1, 8));

select coalesce(
jsonb_agg(
jsonb_build_object(
'segment_id', s.id,
'order_id', s.order_id,
'order_code', o.order_code,
'order_date', o.created_at,
'paid_at', s.commission_snapshot->>'vendor_paid_at',
'gross_amount', coalesce((s.commission_snapshot->>'gross_amount')::numeric, s.subtotal_local, 0),
'commission_rate', coalesce((s.commission_snapshot->>'commission_rate')::numeric, 0),
'commission_amount', coalesce((s.commission_snapshot->>'commission_amount')::numeric, 0),
'other_deductions', coalesce((s.commission_snapshot->>'other_deductions')::numeric, 0),
'net_amount', round(
coalesce((s.commission_snapshot->>'gross_amount')::numeric, s.subtotal_local, 0)
- coalesce((s.commission_snapshot->>'commission_amount')::numeric, 0)
- coalesce((s.commission_snapshot->>'other_deductions')::numeric, 0),
2
)
)
order by o.created_at
),
'[]'::jsonb
)
into v_rows
from public.order_store_segments s
join public.orders o on o.id = s.order_id
where s.id = any(p_segment_ids);

insert into public.vendor_settlement_archives_v163 (
id, statement_no, store_id, store_name_snapshot,
store_logo_url_snapshot, platform_logo_url_snapshot,
currency, gross_amount, commission_amount,
other_deductions, net_amount, order_count,
segment_ids, created_by
)
values (
v_id, v_no, p_store_id, v_store.store_name,
v_store.logo_url, nullif(trim(coalesce(p_platform_logo_url, '')), ''),
'IQD', v_gross, v_commission, v_other, v_net,
v_count, v_rows, null
);

update public.order_store_segments
set vendor_settlement_archive_id = v_id,
updated_at = now()
where id = any(p_segment_ids);

return (
select to_jsonb(a)
from public.vendor_settlement_archives_v163 a
where a.id = v_id
);
end;
$function$

CREATE OR REPLACE FUNCTION private.v165_stamp_unit_cost()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
d jsonb; item jsonb; units jsonb:='[]'; cost numeric; sid uuid;
begin
if current_setting('app.v161_finance_checkout',true)
is distinct from 'on' then return new;end if;

d:=new.details::jsonb;

if coalesce(d->>'vendor_finance_version','')<>'v161'
or jsonb_typeof(d->'items')<>'array' then return new;end if;

sid:=private.v94_uuid(d->>'store_id');

for item in select value from jsonb_array_elements(d->'items') loop
cost:=null;
select cost_price into cost from public.local_products
where id=private.v94_uuid(item->>'product_id') and store_id=sid;

if cost<0 or cost::text in ('NaN','Infinity','-Infinity') then
cost:=null;
end if;

units:=units||jsonb_build_array(jsonb_build_object(
'product_id',item->>'product_id',
'unit_cost_usd',cost,
'exchange_rate',item->'pricing_snapshot'->'exchange_rate'
));
end loop;

insert into private.vendor_profit_units_v165(order_id,store_id,units)
values(new.id,sid,units)
on conflict(order_id,store_id) do nothing;

return new;
end $function$

CREATE OR REPLACE FUNCTION private.v165_freeze_delivered_cost()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
item jsonb; unit jsonb; lines jsonb:='[]';
cost numeric; fx numeric; qty numeric;
total numeric:=0; idx integer:=0;
begin
if not coalesce(new.payment_confirmed,false)
or new.store_status<>'تم التسليم'
or coalesce(new.commission_snapshot->>'version','')<>'v161'
or coalesce(jsonb_typeof(new.items_snapshot),'null')<>'array'
or jsonb_array_length(new.items_snapshot)=0
or exists(
select 1 from private.vendor_profit_costs_v164
where segment_id=new.id
) then return new;end if;

for item in select value from jsonb_array_elements(new.items_snapshot) loop
qty:=nullif(item->>'quantity','')::numeric;
if qty=0 then continue;end if;

select x.value into unit
from private.vendor_profit_units_v165 u
cross join lateral jsonb_array_elements(u.units) x(value)
where u.order_id=new.order_id and u.store_id=new.store_id
and x.value->>'product_id'=item->>'product_id'
limit 1;

if not found then return new;end if;

cost:=nullif(unit->>'unit_cost_usd','')::numeric;
fx:=nullif(unit->>'exchange_rate','')::numeric;
qty:=nullif(item->>'quantity','')::numeric;

if cost is null or cost<0 or fx is null or fx<=0
or qty is null or qty<=0
or cost::text in ('NaN','Infinity','-Infinity')
or fx::text in ('NaN','Infinity','-Infinity')
or qty::text in ('NaN','Infinity','-Infinity') then return new;end if;

idx:=idx+1;
total:=total+round(cost*fx*qty,2);

lines:=lines||jsonb_build_array(jsonb_build_object(
'item_no',idx,'product_id',item->>'product_id',
'product_name',item->>'product_name','quantity',qty,
'unit_cost_usd',cost,'exchange_rate',fx,
'cost_local',round(cost*fx*qty,2)
));
end loop;

if idx=0 then return new;end if;

insert into private.vendor_profit_costs_v164(
segment_id,store_id,lines,total_cost_local
)
values(new.id,new.store_id,lines,total)
on conflict(segment_id) do nothing;

return new;
end $function$

CREATE OR REPLACE FUNCTION public.customer_cart_get_v189(p_customer_id uuid, p_session_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
