CREATE OR REPLACE FUNCTION public.customer_cart_put_v189(p_customer_id uuid, p_items jsonb, p_expected_revision bigint, p_session_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare v_cart record;
begin
if p_session_token is null or private.require_customer_review_session(p_session_token) is distinct from p_customer_id then
raise exception 'CART_SESSION_FORBIDDEN';
end if;
if not exists(select 1 from public.customers where id=p_customer_id) then
raise exception 'CUSTOMER_NOT_FOUND';
end if;
if p_items is null or jsonb_typeof(p_items)<>'array'
or jsonb_array_length(p_items)>200 or pg_column_size(p_items)>262144 then
raise exception 'INVALID_CART_ITEMS';
end if;
if p_expected_revision is null or p_expected_revision<0 then
raise exception 'INVALID_CART_REVISION';
end if;
-- Serialize competing writers even when the cart row does not yet exist.
perform pg_advisory_xact_lock(hashtextextended(p_customer_id::text,189));
select items, updated_at, revision_v189 into v_cart
from public.customer_local_carts where customer_id=p_customer_id for update;
if found then
if v_cart.revision_v189<>p_expected_revision then
raise exception 'CART_REVISION_CONFLICT' using errcode='P0001';
end if;
update public.customer_local_carts
set items=p_items, updated_at=clock_timestamp(), revision_v189=revision_v189+1
where customer_id=p_customer_id
returning items,updated_at,revision_v189 into v_cart;
else
if p_expected_revision<>0 then
raise exception 'CART_REVISION_CONFLICT' using errcode='P0001';
end if;
insert into public.customer_local_carts(customer_id,items,updated_at,revision_v189)
values(p_customer_id,p_items,clock_timestamp(),1)
returning items,updated_at,revision_v189 into v_cart;
end if;
return jsonb_build_object('items',v_cart.items,'updated_at',v_cart.updated_at,'revision',v_cart.revision_v189);
end; $function$

CREATE OR REPLACE FUNCTION public.vendor_profit_list_v165(p_session_token text, p_page integer DEFAULT 1, p_query text DEFAULT ''::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
sid uuid:=private.require_vendor_session(p_session_token);
n integer; pg integer; rows jsonb; summary jsonb;
begin
if p_from is not null and p_to is not null and p_from>p_to then
raise exception 'PROFIT_DATE_RANGE_INVALID';
end if;

if length(coalesce(p_query,''))>100 then
raise exception 'PROFIT_SEARCH_INVALID';
end if;

select count(*) into n
from private.vendor_profit_rows_v165(sid,p_query,p_from,p_to);

pg:=least(
greatest(coalesce(p_page,1),1),
greatest(1,ceil(n/5.0)::integer)
);

select
coalesce(
jsonb_agg(to_jsonb(r) order by r.created_at desc,r.segment_id desc),
'[]'::jsonb
)
into rows
from (
select * from private.vendor_profit_rows_v165(sid,p_query,p_from,p_to)
order by created_at desc,segment_id desc
limit 5 offset (pg-1)*5
) r;

with a as (
select *,
(financial->>'gross_amount')::numeric sales,
(financial->>'commission_amount')::numeric commission,
(financial->>'other_deductions')::numeric other,
(financial->>'net_amount')::numeric net
from private.vendor_profit_rows_v165(sid,p_query,p_from,p_to)
), b as (
select *,
cost_frozen and total_cost_local>=0
and sales is not null and commission is not null
and other is not null and net is not null
and abs(sales-commission-other-net)<=0.011 complete
from a
), c as (
select currency,count(*) orders,
count(*) filter(where complete) complete_orders,
count(*) filter(where not coalesce(complete,false)) incomplete_orders,
sum(sales) sales,sum(commission) commission,
sum(other) other,sum(net) net,
sum(total_cost_local) filter(where complete) cost,
sum(expense_total) expenses,
sum(net-total_cost_local-expense_total) filter(where complete) profit
from b group by currency
)
select coalesce(jsonb_agg(to_jsonb(c) order by currency),'[]'::jsonb)
into summary from c;

return jsonb_build_object(
'rows',rows,'summary',summary,'total',n,'page',pg,'page_size',5,
'pages',greatest(1,ceil(n/5.0)::integer)
);
end $function$

CREATE OR REPLACE FUNCTION public.vendor_profit_capture_cost_v165(p_session_token text, p_segment_id uuid, p_expected_lines jsonb)
