CREATE OR REPLACE FUNCTION public.kinto_approve_paid_order_v1(p_session_token text, p_actor text, p_order_id uuid, p_expected_status text, p_patch jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE
v_id text;
v_old public.orders%ROWTYPE;
v_typed public.orders%ROWTYPE;
v_previous_details jsonb;
v_requested_details jsonb;
BEGIN
IF p_actor = 'employee' THEN
v_id := private.require_employee_session_v143(p_session_token);
ELSIF p_actor = 'admin' THEN
v_id := private.require_admin_session_v147(p_session_token);
ELSE
RAISE EXCEPTION 'KINTO_PAYMENT_ACTOR_DENIED' USING ERRCODE='42501';
END IF;
IF v_id IS NULL THEN
RAISE EXCEPTION 'KINTO_PAYMENT_SESSION_INVALID' USING ERRCODE='42501';
END IF;
IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object'
OR p_patch->>'status' IS DISTINCT FROM 'تم التسديد'
OR p_patch ?| ARRAY['id','created_at','order_code','customer_id'] THEN
RAISE EXCEPTION 'KINTO_PAYMENT_PATCH_INVALID';
END IF;
-- Only the fields currently written by the employee/admin order-save controls.
IF EXISTS (
SELECT 1 FROM jsonb_object_keys(p_patch) AS k(key)
WHERE k.key <> ALL(ARRAY[
'status','reference_order_no','delivery_payment_type','branch_id',
'branch_name','delivery_agent_id','courier_id','total_price','currency',
'rejection_reason','details','delivery_fee'
])
) THEN
RAISE EXCEPTION 'KINTO_PAYMENT_PATCH_FIELDS_DENIED';
END IF;
SELECT * INTO v_old FROM public.orders WHERE id=p_order_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'KINTO_ORDER_NOT_FOUND'; END IF;
IF v_old.status IS DISTINCT FROM p_expected_status THEN
RAISE EXCEPTION 'KINTO_ORDER_STATUS_CHANGED';
END IF;
IF v_old.status IS NULL OR btrim(v_old.status) = '' THEN
RAISE EXCEPTION 'KINTO_PAYMENT_PREVIOUS_STATUS_REQUIRED';
END IF;
IF v_old.status = 'تم التسديد' THEN
RAISE EXCEPTION 'KINTO_ORDER_ALREADY_PAID';
END IF;
-- Compare financial values using the database column types, including SQL NULL.
-- Dashboard saves send unchanged financial values; a mismatched value is rejected.
IF (p_patch ? 'total_price' AND (p_patch->>'total_price')::numeric IS DISTINCT FROM v_old.total_price)
OR (p_patch ? 'delivery_fee' AND (p_patch->>'delivery_fee')::numeric IS DISTINCT FROM v_old.delivery_fee)
OR (p_patch ? 'currency' AND p_patch->>'currency' IS DISTINCT FROM v_old.currency)
THEN
RAISE EXCEPTION 'KINTO_PAYMENT_FINANCIAL_FIELDS_CHANGE_DENIED' USING ERRCODE='42501';
END IF;
-- The employee UI may change only the parcel count while approving payment.
-- Prevent a forged RPC patch from changing cart items, prices or stock evidence.
IF p_patch ? 'details' THEN
BEGIN
v_previous_details := coalesce(nullif(v_old.details, '')::jsonb, '{}'::jsonb);
v_requested_details := coalesce(nullif(p_patch->>'details', '')::jsonb, '{}'::jsonb);
EXCEPTION WHEN others THEN
RAISE EXCEPTION 'KINTO_PAYMENT_DETAILS_INVALID';
END;
-- Keep each validation separate to avoid nested boolean-parenthesis errors.
IF jsonb_typeof(v_previous_details) IS DISTINCT FROM 'object'
OR jsonb_typeof(v_requested_details) IS DISTINCT FROM 'object'
OR (v_requested_details - 'parcels_count') IS DISTINCT FROM
(v_previous_details - 'parcels_count')
THEN
RAISE EXCEPTION 'KINTO_PAYMENT_DETAILS_CHANGE_DENIED';
END IF;
IF v_requested_details IS DISTINCT FROM v_previous_details THEN
IF jsonb_typeof(v_requested_details->'parcels_count') IS DISTINCT FROM 'number' THEN
RAISE EXCEPTION 'KINTO_PAYMENT_DETAILS_CHANGE_DENIED';
END IF;
IF (v_requested_details->>'parcels_count')::numeric < 1
OR (v_requested_details->>'parcels_count')::numeric > 100000
OR (v_requested_details->>'parcels_count')::numeric <>
trunc((v_requested_details->>'parcels_count')::numeric)
THEN
RAISE EXCEPTION 'KINTO_PAYMENT_DETAILS_CHANGE_DENIED';
END IF;
END IF;
END IF;
-- PostgreSQL performs column-type conversion using the real orders row type.
IF p_patch ? 'delivery_agent_id' AND NOT p_patch ? 'courier_id' THEN
p_patch:=p_patch||jsonb_build_object('courier_id',(SELECT c.id::text FROM public.couriers c WHERE c.courier_uuid=(p_patch->>'delivery_agent_id')::uuid));
END IF;
v_typed := jsonb_populate_record(NULL::public.orders, p_patch);
PERFORM private.kinto_check_order_assignment_v1(private.kinto_staff_actor_v1(p_actor,p_session_token),v_old,jsonb_populate_record(v_old,p_patch));
INSERT INTO private.kinto_paid_transition_permits_v1(transaction_id,order_id)
VALUES(txid_current(),p_order_id);
UPDATE public.orders o SET
status = 'تم التسديد',
reference_order_no = CASE WHEN p_patch ? 'reference_order_no' THEN p_patch->>'reference_order_no' ELSE o.reference_order_no END,
delivery_payment_type = CASE WHEN p_patch ? 'delivery_payment_type' THEN p_patch->>'delivery_payment_type' ELSE o.delivery_payment_type END,
branch_id = CASE WHEN p_patch ? 'branch_id' THEN p_patch->>'branch_id' ELSE o.branch_id END,
branch_name = CASE WHEN p_patch ? 'branch_name' THEN p_patch->>'branch_name' ELSE o.branch_name END,
delivery_agent_id = CASE WHEN p_patch ? 'delivery_agent_id' THEN v_typed.delivery_agent_id ELSE o.delivery_agent_id END,
courier_id = CASE WHEN p_patch ? 'courier_id' THEN v_typed.courier_id ELSE o.courier_id END,
total_price = CASE WHEN p_patch ? 'total_price' THEN v_typed.total_price ELSE o.total_price END,
currency = CASE WHEN p_patch ? 'currency' THEN p_patch->>'currency' ELSE o.currency END,
rejection_reason = CASE WHEN p_patch ? 'rejection_reason' THEN p_patch->>'rejection_reason' ELSE o.rejection_reason END,
details = CASE WHEN p_patch ? 'details' THEN p_patch->>'details' ELSE o.details END,
delivery_fee = CASE WHEN p_patch ? 'delivery_fee' THEN v_typed.delivery_fee ELSE o.delivery_fee END
WHERE o.id=p_order_id;
INSERT INTO private.kinto_paid_approval_audit_v1(order_id,actor_type,actor_id,previous_status)
VALUES(p_order_id,p_actor,v_id,v_old.status);
DELETE FROM private.kinto_paid_transition_permits_v1
WHERE transaction_id=txid_current() AND order_id=p_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.kinto_approve_external_shipping_v1(p_session_token text, p_actor text, p_order_id uuid, p_expected_status text, p_expected_fee numeric, p_expected_currency text, p_new_fee numeric, p_new_currency text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE v_actor_id text; v_old public.orders%ROWTYPE;
BEGIN
IF p_actor='employee' THEN
v_actor_id:=private.require_employee_session_v143(p_session_token);
ELSIF p_actor='admin' THEN
v_actor_id:=private.require_admin_session_v147(p_session_token);
ELSE RAISE EXCEPTION 'KINTO_EXTERNAL_SHIPPING_ACTOR_DENIED' USING ERRCODE='42501';
END IF;
IF v_actor_id IS NULL THEN
RAISE EXCEPTION 'KINTO_EXTERNAL_SHIPPING_SESSION_INVALID' USING ERRCODE='42501';
END IF;
IF p_new_fee IS NULL OR p_new_fee < 0 OR p_new_fee > 999999999999
OR p_new_currency IS NULL OR length(btrim(p_new_currency)) NOT BETWEEN 1 AND 12
THEN RAISE EXCEPTION 'KINTO_EXTERNAL_SHIPPING_VALUE_INVALID' USING ERRCODE='22023';
END IF;
SELECT * INTO v_old FROM public.orders WHERE id=p_order_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'KINTO_ORDER_NOT_FOUND'; END IF;
IF v_old.status IS DISTINCT FROM p_expected_status
OR v_old.external_shipping_fee IS DISTINCT FROM p_expected_fee
OR v_old.external_shipping_currency IS DISTINCT FROM p_expected_currency
THEN RAISE EXCEPTION 'KINTO_EXTERNAL_SHIPPING_STALE_ORDER' USING ERRCODE='40001';
END IF;
IF v_old.external_shipping_fee IS NOT DISTINCT FROM p_new_fee
AND v_old.external_shipping_currency IS NOT DISTINCT FROM p_new_currency
THEN RETURN; END IF;
INSERT INTO private.kinto_paid_transition_permits_v1(transaction_id,order_id)
VALUES(txid_current(),p_order_id);
UPDATE public.orders SET external_shipping_fee=p_new_fee,
external_shipping_currency=p_new_currency WHERE id=p_order_id;
INSERT INTO private.kinto_external_shipping_audit_v1(
order_id,actor_type,actor_id,previous_fee,new_fee,previous_currency,new_currency
) VALUES(p_order_id,p_actor,v_actor_id,v_old.external_shipping_fee,p_new_fee,
v_old.external_shipping_currency,p_new_currency);
DELETE FROM private.kinto_paid_transition_permits_v1
WHERE transaction_id=txid_current() AND order_id=p_order_id;
END $function$

CREATE OR REPLACE FUNCTION private.kinto_local_order_insert_gate_v1()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE
v_details jsonb;
v_source text;
v_contract text;
BEGIN
-- Parse without calling private helper functions: anon must be able to
-- execute this SECURITY INVOKER trigger on the global order path.
BEGIN
v_details := coalesce(NEW.details,'{}')::jsonb;
IF jsonb_typeof(v_details) <> 'object' THEN
v_details := '{}'::jsonb;
END IF;
EXCEPTION WHEN invalid_text_representation THEN
v_details := '{}'::jsonb;
END;
v_source := coalesce(v_details->>'source','');
v_contract := coalesce(v_details->>'checkout_contract','');

-- Browser roles may submit only the historical global product-link form.
-- Any local, campaign, or unrecognised order payload must use the trusted
-- SECURITY DEFINER checkout RPC instead of direct REST INSERT.
IF current_user IN ('anon','authenticated') THEN
IF v_source <> ''
OR v_contract <> ''
OR NEW.total_price IS DISTINCT FROM 0
OR NEW.items IS NOT NULL
OR NEW.kinto_campaign_id IS NOT NULL
OR coalesce(NEW.kinto_campaign_discount_amount,0) <> 0
OR coalesce(NEW.order_url,'') !~* '^https?://[^[:space:]]+'
OR NEW.status IS DISTINCT FROM 'انتظار رد الموظف'
OR coalesce(NEW.order_code,'') NOT LIKE 'MW-%'
OR v_details ?| ARRAY['items','store_id','product_id','products',
'stores','store_segments','unit_price',
'unit_price_local','price','total_price',
'campaign_id','deal_campaign_id']
OR EXISTS (
SELECT 1 FROM jsonb_object_keys(v_details) AS k(key)
WHERE k.key NOT IN ('color','size','quantity','notes')
)
OR coalesce(v_details->>'quantity','') !~ '^[0-9]{1,4}$'
OR (v_details->>'quantity')::integer NOT BETWEEN 1 AND 9999
THEN
RAISE EXCEPTION 'KINTO_ORDER_TRUSTED_CHECKOUT_REQUIRED'
USING ERRCODE='42501';
END IF;
END IF;

RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.kinto_local_independent_amount_guard_v1()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE
v_old_details jsonb;
v_new_details jsonb;
v_projection jsonb;
BEGIN
-- Avoid changing the global/legacy order pricing workflow.
v_old_details := private.v94_jsonb_object(to_jsonb(OLD.details));
IF coalesce(v_old_details->>'checkout_contract', '') <> 'independent_vendor_orders' THEN
RETURN NEW;
END IF;

IF NEW.total_price IS NOT DISTINCT FROM OLD.total_price
AND NEW.currency IS NOT DISTINCT FROM OLD.currency THEN
RETURN NEW;
END IF;

-- Order currency is fixed by the checkout's trusted store calculation.
IF NEW.currency IS DISTINCT FROM OLD.currency THEN
RAISE EXCEPTION 'KINTO_LOCAL_ORDER_CURRENCY_LOCKED' USING ERRCODE='42501';
END IF;

-- Preserve the existing customer invoice/stock correction (V58/V59).
-- Never allow a free-form price update, even when the invoice GUC is present.
IF current_setting('kinto.invoice_adjustment_v58', true) = OLD.id::text
AND OLD.status = ANY(ARRAY[
'بانتظار موافقة العميل',
'بانتظار موافقة الزبون',
'بانتظار التسعير',
'تم التسعير / بانتظار موافقة العميل'
])
AND NEW.status IS NOT DISTINCT FROM OLD.status
AND coalesce(v_old_details->>'bundle_stock_lifecycle_state','') <> 'deducted'
THEN
v_projection := private.invoice_stock_projection_v59(OLD);
v_new_details := private.v94_jsonb_object(to_jsonb(NEW.details));
IF v_projection->>'changed' = 'true'
AND NEW.total_price IS NOT DISTINCT FROM (v_projection->>'total_price')::numeric
AND v_new_details = v_projection->'details'
THEN
RETURN NEW;
END IF;
END IF;

RAISE EXCEPTION 'KINTO_LOCAL_ORDER_AMOUNT_LOCKED' USING ERRCODE='42501';
END;
$function$

CREATE OR REPLACE FUNCTION private.kinto_global_link_no_local_promotion_v1()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
v_details jsonb;
v_items jsonb;
BEGIN
IF current_user NOT IN ('anon', 'authenticated')
OR coalesce(OLD.order_code,'') NOT LIKE 'MW-%'
OR coalesce(OLD.order_url,'') !~* '^https?://'
THEN
RETURN NEW;
END IF;

BEGIN
v_details := coalesce(nullif(NEW.details,''),'{}')::jsonb;
EXCEPTION WHEN others THEN
v_details := '{}'::jsonb;
END;

IF jsonb_typeof(v_details) <> 'object' THEN
v_details := '{}'::jsonb;
END IF;

-- Keep the marker used to identify this global-link row intact. Without
-- this check a browser could change the code/URL first and bypass the
-- promotion guard in a second UPDATE.
IF coalesce(NEW.order_code,'') NOT LIKE 'MW-%'
OR coalesce(NEW.order_url,'') !~* '^https?://'
THEN
RAISE EXCEPTION 'KINTO_GLOBAL_LINK_IDENTITY_LOCKED'
USING ERRCODE='42501';
END IF;

-- The global product-link flow has no store/product/campaign contract.
IF NEW.order_code IS DISTINCT FROM OLD.order_code
OR coalesce(NEW.order_url,'') !~* '^https?://'
OR coalesce(v_details->>'checkout_contract','') <> ''
OR coalesce(v_details->>'source','') IN ('local_cart_bundle','local_store')
OR v_details ?| ARRAY['items','stores','store_id','store_segments','product_id',
'products','customer_total_local','store_subtotal',
'checkout_group_id','vendor_order_id']
OR NEW.kinto_campaign_id IS DISTINCT FROM OLD.kinto_campaign_id
AND NEW.kinto_campaign_id IS NOT NULL
THEN
RAISE EXCEPTION 'KINTO_GLOBAL_LINK_CANNOT_BECOME_LOCAL'
USING ERRCODE='42501';
END IF;

-- A forged local item array in the separate orders.items field is not
-- part of the global order.html submission; disallow its introduction
-- only when it carries a local store/product identity.
IF NEW.items IS DISTINCT FROM OLD.items AND NEW.items IS NOT NULL THEN
BEGIN
v_items := NEW.items::jsonb;
IF v_items::text ~* '"(store_id|local_product_id|product_id|checkout_contract)"[[:space:]]*:'
THEN
RAISE EXCEPTION 'KINTO_GLOBAL_LINK_CANNOT_BECOME_LOCAL'
USING ERRCODE='42501';
END IF;
EXCEPTION WHEN invalid_text_representation THEN
NULL;
END;
END IF;

RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_list_featured_requests_session_v1(p_session_token text)
