CREATE OR REPLACE FUNCTION public.admin_approve_featured_request(p_admin_id uuid, p_request_id uuid, p_store_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_admin_note text DEFAULT NULL::text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
r public.merchant_featured_requests%rowtype;
v_slot uuid;
begin
if p_admin_id is null or not public.meshwar_is_admin(p_admin_id) then
raise exception 'not authorized';
end if;
if p_end_date<=p_start_date then raise exception 'end_date must be after start_date'; end if;

select * into r
from public.merchant_featured_requests
where id=p_request_id
for update;

if not found then raise exception 'request not found'; end if;
if r.status<>'pending' then raise exception 'request already reviewed'; end if;
if p_store_id is null then raise exception 'store_id is required'; end if;
if r.store_id is not null and p_store_id<>r.store_id then
raise exception 'selected store does not match request store';
end if;
if not exists(select 1 from public.local_stores s where s.id=p_store_id and coalesce(s.is_active,true)=true) then
raise exception 'store not found or inactive';
end if;

insert into public.merchant_featured_slots(
store_id,merchant_id,slot_type,banner_url,store_logo,store_name,item_ids,start_date,end_date,is_active
) values (
p_store_id,null,r.slot_type,r.banner_url,r.store_logo,r.store_name,r.item_ids,p_start_date,p_end_date,true
) returning id into v_slot;

update public.merchant_featured_requests
set store_id=p_store_id,status='approved',approved_slot_id=v_slot,reviewed_by=p_admin_id,reviewed_at=now(),
admin_note=nullif(trim(p_admin_note),''),updated_at=now()
where id=p_request_id;

return v_slot;
end;
$function$

CREATE OR REPLACE FUNCTION private.kinto_staff_actor_v1(p_role text, p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor text; row_data jsonb; actual_role text;
BEGIN
CASE p_role
WHEN 'admin' THEN actor:=private.require_admin_session_v147(p_token);
WHEN 'employee' THEN actor:=private.require_employee_session_v143(p_token);
WHEN 'branch' THEN actor:=private.require_branch_session_v148(p_token);
WHEN 'courier' THEN actor:=private.require_courier_session_v149(p_token);
ELSE RAISE EXCEPTION 'STAFF_ROLE_REQUIRED' USING ERRCODE='42501';
END CASE;
IF p_role IN ('admin','employee') THEN
SELECT to_jsonb(e) INTO row_data FROM public.employees e WHERE e.id::text=actor;
actual_role:=lower(trim(coalesce(row_data->>'role','')));
IF (p_role='admin' AND actual_role NOT IN ('admin','أدمن','ادمن')) OR
(p_role='employee' AND actual_role NOT IN ('employee','موظف')) THEN
RAISE EXCEPTION 'STAFF_ROLE_INVALID' USING ERRCODE='42501';
END IF;
ELSIF p_role='branch' THEN
SELECT to_jsonb(b) INTO row_data FROM public.branches b WHERE b.id::text=actor;
ELSE
SELECT to_jsonb(c) INTO row_data FROM public.couriers c WHERE c.id::text=actor;
END IF;
IF row_data IS NULL OR lower(coalesce(row_data->>'is_active','true')) IN ('false','0')
OR lower(coalesce(row_data->>'active','true')) IN ('false','0')
OR lower(coalesce(row_data->>'disabled','false')) IN ('true','1')
OR lower(coalesce(row_data->>'status','')) IN ('disabled','inactive','معطل','موقوف') THEN
RAISE EXCEPTION 'STAFF_ACTOR_DISABLED' USING ERRCODE='42501';
END IF;
RETURN jsonb_build_object('id',actor,'role',p_role,'branch_id',row_data->>'branch_id','permissions',row_data->'permissions');
END $function$

CREATE OR REPLACE FUNCTION public.kinto_admin_delete_branch_session_v1(p_session_token text, p_branch_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
PERFORM private.kinto_staff_actor_v1('admin',p_session_token);
PERFORM 1 FROM public.branches WHERE id::text=p_branch_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'BRANCH_NOT_FOUND' USING ERRCODE='P0002'; END IF;
-- Keep the existing no-linked-orders rule atomic with branch deletion.
LOCK TABLE public.orders IN SHARE MODE;
IF EXISTS(SELECT 1 FROM public.orders WHERE branch_id::text=p_branch_id) THEN
RAISE EXCEPTION 'BRANCH_HAS_ORDERS' USING ERRCODE='23503';
END IF;
DELETE FROM public.branches WHERE id::text=p_branch_id;
RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION public.vendor_create_media_upload_session_v1(p_session_token text, p_store_id uuid, p_purpose text, p_mime_type text, p_byte_size integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor uuid; mime text:=lower(trim(p_mime_type)); ext text; object_path text;
BEGIN
actor:=private.require_vendor_session(p_session_token);
IF actor IS DISTINCT FROM p_store_id THEN RAISE EXCEPTION 'VENDOR_STORE_MISMATCH' USING ERRCODE='42501'; END IF;
IF NOT EXISTS(SELECT FROM public.local_stores WHERE id=actor AND coalesce(is_active,true)) THEN RAISE EXCEPTION 'VENDOR_STORE_INACTIVE' USING ERRCODE='42501'; END IF;
ext:=CASE mime WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/webp' THEN 'webp' WHEN 'image/gif' THEN 'gif' WHEN 'image/avif' THEN 'avif' WHEN 'image/bmp' THEN 'bmp' END;
IF ext IS NULL THEN RAISE EXCEPTION 'اختر صورة JPG أو PNG أو WebP أو GIF أو AVIF أو BMP.' USING ERRCODE='22023'; END IF;
IF p_byte_size IS NULL OR p_byte_size<1 OR p_byte_size>15728640 THEN RAISE EXCEPTION 'حجم الصورة يجب أن يكون أكبر من صفر ولا يتجاوز 15MB.' USING ERRCODE='22023'; END IF;
IF p_purpose='product' THEN object_path:=actor::text||'/'||gen_random_uuid()::text||'.'||ext;
ELSIF p_purpose IN ('banner','logo') THEN object_path:='promotions/'||actor::text||'/'||p_purpose||'-'||gen_random_uuid()::text||'.'||ext;
ELSE RAISE EXCEPTION 'MEDIA_PURPOSE_INVALID' USING ERRCODE='22023'; END IF;
DELETE FROM private.vendor_media_tickets_v1 WHERE expires_at<=now();
INSERT INTO private.vendor_media_tickets_v1 VALUES(object_path,actor,extensions.digest(p_session_token,'sha256'),mime,p_byte_size,now()+interval '15 minutes');
RETURN jsonb_build_object('bucket','product-images','path',object_path,'mime_type',mime,'max_bytes',15728640);
END $function$

CREATE OR REPLACE FUNCTION public.customer_update_profile_session_v1(p_session_token text, p_patch jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE customer_id uuid; profile jsonb; field text;
BEGIN
customer_id:=private.require_customer_review_session(p_session_token);
IF p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR p_patch='{}'::jsonb THEN
RAISE EXCEPTION 'CUSTOMER_PROFILE_PATCH_REQUIRED' USING ERRCODE='22023';
END IF;
FOR field IN SELECT jsonb_object_keys(p_patch) LOOP
IF field NOT IN ('address','state','secondary_phone') THEN
RAISE EXCEPTION 'CUSTOMER_PROFILE_FIELD_FORBIDDEN: %',field USING ERRCODE='22023';
END IF;
IF jsonb_typeof(p_patch->field) NOT IN ('string','null') THEN
RAISE EXCEPTION 'CUSTOMER_PROFILE_VALUE_INVALID: %',field USING ERRCODE='22023';
END IF;
IF length(p_patch->>field)>(CASE WHEN field='address' THEN 4000 WHEN field='state' THEN 200 ELSE 100 END) THEN
RAISE EXCEPTION 'CUSTOMER_PROFILE_VALUE_TOO_LONG: %',field USING ERRCODE='22023';
END IF;
END LOOP;
UPDATE public.customers c SET
address=CASE WHEN p_patch?'address' THEN coalesce(btrim(p_patch->>'address'),'') ELSE c.address END,
state=CASE WHEN p_patch?'state' THEN nullif(btrim(p_patch->>'state'),'') ELSE c.state END,
secondary_phone=CASE WHEN p_patch?'secondary_phone' THEN nullif(btrim(p_patch->>'secondary_phone'),'') ELSE c.secondary_phone END
WHERE c.id=customer_id
RETURNING jsonb_build_object('id',c.id,'address',c.address,'state',c.state,'secondary_phone',c.secondary_phone) INTO profile;
IF profile IS NULL THEN RAISE EXCEPTION 'CUSTOMER_SESSION_INVALID'; END IF;
RETURN jsonb_build_object('ok',true,'profile',profile);
END $function$

CREATE OR REPLACE FUNCTION public.kinto_customer_directory_session_v1(p_role text, p_session_token text, p_filters jsonb DEFAULT '[]'::jsonb, p_search text DEFAULT ''::text, p_order text DEFAULT 'id'::text, p_ascending boolean DEFAULT true, p_limit integer DEFAULT 2000, p_offset integer DEFAULT 0)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; actor_id text; actor_row jsonb; scope_sql text; filter_sql text:='';
fields text[]; filter_fields text[]:=ARRAY['id','name','phone','secondary_phone','code','email','country','state','created_at'];
f jsonb; field_name text; op text; result jsonb; sort_direction text;
BEGIN
fields:=ARRAY['id','created_at','name','phone','secondary_phone','code','country','state','address'];
IF p_role='customer' THEN
actor_id:=private.require_customer_review_session(p_session_token)::text;
scope_sql:=format('c.id::text=%L',actor_id);
ELSIF p_role='vendor' THEN
actor_id:=private.require_vendor_session(p_session_token)::text;
scope_sql:=format('(EXISTS(SELECT 1 FROM public.orders o WHERE o.customer_id=c.id::text AND (EXISTS(SELECT 1 FROM public.order_store_segments s WHERE s.order_id=o.id AND s.store_id::text=%1$L) OR private.v94_jsonb_object(to_jsonb(o)->''details'')->>''store_id''=%1$L OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(private.v94_jsonb_object(to_jsonb(o)->''details'')->''items'')=''array'' THEN private.v94_jsonb_object(to_jsonb(o)->''details'')->''items'' ELSE ''[]''::jsonb END) item WHERE item->>''store_id''=%1$L))) OR EXISTS(SELECT 1 FROM public.kinto_loyalty_wallets w WHERE w.customer_id::text=c.id::text AND w.store_id::text=%1$L) OR EXISTS(SELECT 1 FROM public.kinto_loyalty_coupons w WHERE w.customer_id::text=c.id::text AND w.store_id::text=%1$L))',actor_id);
ELSIF p_role IN ('admin','employee','branch','courier') THEN
actor:=private.kinto_staff_actor_v1(p_role,p_session_token);actor_id:=actor->>'id';
IF p_role IN ('admin','employee') THEN
IF p_role='employee' AND actor->'permissions'->>'customers'='false' AND actor->'permissions'->>'orders'='false' THEN
RAISE EXCEPTION 'CUSTOMER_DIRECTORY_PERMISSION_REQUIRED' USING ERRCODE='42501';
END IF;
scope_sql:='true';
ELSIF p_role='branch' THEN
scope_sql:=format('EXISTS(SELECT 1 FROM public.orders o WHERE o.customer_id=c.id::text AND o.branch_id=%L)',actor_id);
ELSE
SELECT to_jsonb(x) INTO actor_row FROM public.couriers x WHERE x.id::text=actor_id;
scope_sql:=format('EXISTS(SELECT 1 FROM public.orders o WHERE o.customer_id=c.id::text AND (o.courier_id=ANY(%1$L::text[]) OR to_jsonb(o)->>''delivery_agent_id''=ANY(%1$L::text[])) AND (coalesce(o.branch_id,'''')='''' OR o.branch_id=ANY(%2$L::text[])))',
array_remove(ARRAY[actor_id,actor_row->>'courier_uuid',actor_row->>'delivery_agent_id',actor_row->>'uuid',actor_row->>'user_id'],NULL),
array_remove(ARRAY[actor_row->>'branch_id',actor_row->>'branch_uuid'],NULL));
END IF;
ELSE RAISE EXCEPTION 'CUSTOMER_DIRECTORY_ROLE_REQUIRED' USING ERRCODE='42501';
END IF;
IF p_role IN ('customer','admin') THEN
fields:=fields||ARRAY['email','cart_items','rewards_log','wallet_balance','wallet_currency','rewards_count','current_cycle_delivered','reward_balances'];
ELSIF p_role='employee' THEN fields:=fields||ARRAY['email']; END IF;
IF p_filters IS NULL OR jsonb_typeof(p_filters)<>'array' OR jsonb_array_length(p_filters)>64
OR p_order IS NULL OR NOT p_order=ANY(filter_fields) OR length(coalesce(p_search,''))>300
OR p_limit IS NULL OR p_limit<1 OR p_limit>10000 OR p_offset IS NULL OR p_offset<0 OR p_offset>10000000 THEN
RAISE EXCEPTION 'CUSTOMER_DIRECTORY_QUERY_INVALID' USING ERRCODE='22023';
END IF;
FOR f IN SELECT value FROM jsonb_array_elements(p_filters) LOOP
field_name:=f->>'field';op:=f->>'op';
IF field_name IS NULL OR NOT field_name=ANY(filter_fields) OR op IS NULL OR op NOT IN ('eq','in','not_null') THEN
RAISE EXCEPTION 'CUSTOMER_DIRECTORY_FILTER_INVALID' USING ERRCODE='22023';
END IF;
IF op='not_null' THEN filter_sql:=filter_sql||format(' AND c.%I IS NOT NULL',field_name);
ELSIF op='eq' THEN
IF jsonb_typeof(f->'value') NOT IN ('string','number') OR f->'value' IS NULL THEN RAISE EXCEPTION 'CUSTOMER_DIRECTORY_FILTER_INVALID'; END IF;
filter_sql:=filter_sql||format(' AND c.%I::text=%L',field_name,f->>'value');
ELSE
IF jsonb_typeof(f->'value') IS DISTINCT FROM 'array' OR jsonb_array_length(f->'value')>10000 THEN RAISE EXCEPTION 'CUSTOMER_DIRECTORY_FILTER_INVALID'; END IF;
filter_sql:=filter_sql||format(' AND c.%I::text IN (SELECT jsonb_array_elements_text(%L::jsonb))',field_name,(f->'value')::text);
END IF;
END LOOP;
IF coalesce(p_search,'')<>'' THEN
filter_sql:=filter_sql||format(' AND (c.name ILIKE %1$L OR c.phone ILIKE %1$L OR c.secondary_phone ILIKE %1$L OR c.code ILIKE %1$L OR c.email ILIKE %1$L)','%'||p_search||'%');
END IF;
sort_direction:=CASE WHEN coalesce(p_ascending,true) THEN 'ASC' ELSE 'DESC' END;
EXECUTE format('WITH matched AS MATERIALIZED (SELECT c.* FROM public.customers c WHERE %1$s %2$s), page AS (SELECT * FROM matched ORDER BY %3$I %4$s,id %4$s LIMIT %5$s OFFSET %6$s) SELECT jsonb_build_object(''rows'',coalesce((SELECT jsonb_agg((SELECT jsonb_object_agg(e.key,e.value) FROM jsonb_each(to_jsonb(t)) e WHERE e.key=ANY($1)) ORDER BY t.%3$I %4$s,t.id %4$s) FROM page t),''[]''::jsonb),''count'',(SELECT count(*) FROM matched))',scope_sql,filter_sql,p_order,sort_direction,p_limit,p_offset) INTO result USING fields;
RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.apply_order_reward_discount(p_order_id uuid, p_amount numeric, p_currency text, p_actor_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
v_currency text := private.v112_reward_currency(p_currency);
v_order public.orders%rowtype;
v_customer public.customers%rowtype;
v_balance numeric;
v_snapshot jsonb;
begin
perform private.v112_require_reward_actor(p_actor_id);
if v_currency not in ('USD', 'IQD', 'TRY') or coalesce(p_amount, 0) <= 0 then
raise exception 'INVALID_REWARD_DISCOUNT' using errcode = '22023';
end if;

select * into v_order from public.orders where id = p_order_id for update;
if not found then raise exception 'ORDER_NOT_FOUND' using errcode = 'P0002'; end if;
if v_order.customer_id is null then raise exception 'ORDER_CUSTOMER_REQUIRED' using errcode = '22023'; end if;
if coalesce(v_order.reward_discount_amount, 0) > 0 then
raise exception 'ORDER_REWARD_ALREADY_APPLIED' using errcode = '23505';
end if;
if coalesce(v_order.status, '') ~ '(تم التسليم|ملغي|رفض|مرفوض|راجع)' then
raise exception 'ORDER_REWARD_STATUS_LOCKED' using errcode = '55000';
end if;
if v_currency not in (
private.v112_reward_currency(coalesce(v_order.currency, 'IQD')),
private.v112_reward_currency(coalesce(v_order.delivery_currency, v_order.currency, 'IQD'))
) then
raise exception 'REWARD_CURRENCY_NOT_IN_ORDER' using errcode = '22023';
end if;
if v_currency = private.v112_reward_currency(coalesce(v_order.currency, 'IQD'))
and p_amount > (
coalesce(v_order.total_price, 0)
+ case
when private.v112_reward_currency(coalesce(v_order.delivery_currency, v_order.currency, 'IQD')) = v_currency
then coalesce(v_order.delivery_fee, 0)
else 0
end
) then
raise exception 'REWARD_DISCOUNT_EXCEEDS_ORDER_TOTAL' using errcode = '22003';
end if;
if v_currency <> private.v112_reward_currency(coalesce(v_order.currency, 'IQD'))
and p_amount > coalesce(v_order.delivery_fee, 0) then
raise exception 'REWARD_DISCOUNT_EXCEEDS_DELIVERY_TOTAL' using errcode = '22003';
end if;

select * into v_customer from public.customers where id::text = v_order.customer_id::text for update;
v_balance := coalesce(nullif(v_customer.reward_balances ->> v_currency, '')::numeric, 0);
if v_balance < p_amount then raise exception 'REWARD_BALANCE_INSUFFICIENT' using errcode = '22003'; end if;

v_snapshot := jsonb_build_object(
'amount', p_amount, 'currency', v_currency, 'applied_at', now(),
'applied_by', p_actor_id, 'source', 'reward_balances_v112'
);
update public.customers
set reward_balances = jsonb_set(reward_balances, array[v_currency], to_jsonb(v_balance - p_amount), true),
rewards_log = coalesce(rewards_log, '[]'::jsonb) || jsonb_build_array(v_snapshot || jsonb_build_object('type', 'order_discount', 'order_id', p_order_id, 'amount', -p_amount, 'date', now()))
where id::text = v_order.customer_id::text;

update public.orders
set reward_discount_amount = p_amount,
reward_discount_currency = v_currency,
reward_discount_snapshot = v_snapshot
where id = p_order_id;

return jsonb_build_object('order_id', p_order_id, 'customer_id', v_order.customer_id,
'discount', v_snapshot, 'remaining_balance', v_balance - p_amount);
end;
$function$

CREATE OR REPLACE FUNCTION public.kinto_decide_settlement_session_v1(p_role text, p_session_token text, p_settlement_id bigint, p_action text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; claim public.settlements%rowtype; entry public.orders%rowtype; n integer:=0; gross numeric:=0; fee numeric:=0; net numeric:=0; legacy_gross numeric:=0; legacy_net numeric:=0; a record;
BEGIN
actor:=private.kinto_settlement_actor_v1(p_role,p_session_token);
IF p_role<>'admin' THEN RAISE EXCEPTION 'SETTLEMENT_ADMIN_REQUIRED' USING ERRCODE='42501'; END IF;
IF p_action IS NULL OR p_action NOT IN ('approve','reject') THEN RAISE EXCEPTION 'SETTLEMENT_ACTION_INVALID'; END IF;
SELECT * INTO claim FROM public.settlements WHERE id=p_settlement_id FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'SETTLEMENT_NOT_FOUND'; END IF;
IF claim.status NOT IN ('pending','pending_admin') THEN RAISE EXCEPTION 'SETTLEMENT_ALREADY_PROCESSED'; END IF;
FOR entry IN SELECT * FROM public.orders WHERE settlement_id=claim.id ORDER BY id FOR UPDATE LOOP
n:=n+1;
IF p_action='approve' THEN
IF entry.total_price::text IN ('NaN','Infinity','-Infinity') OR entry.delivery_fee::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'SETTLEMENT_AMOUNT_INVALID'; END IF;
IF entry.branch_id IS DISTINCT FROM claim.branch_id OR entry.status IS DISTINCT FROM 'تم التسليم'
OR coalesce(nullif(entry.currency,''),'$') IS DISTINCT FROM claim.currency
OR (claim.settlement_type='courier' AND entry.courier_id IS DISTINCT FROM claim.courier_id)
OR NOT coalesce(claim.order_ids ? entry.id::text,false) THEN RAISE EXCEPTION 'SETTLEMENT_SNAPSHOT_MISMATCH'; END IF;
SELECT * INTO a FROM private.kinto_settlement_amounts_v1(entry.total_price,entry.delivery_fee,entry.delivery_payment_type,'collection');gross:=gross+a.gross;fee:=fee+a.fee;net:=net+a.net;
SELECT * INTO a FROM private.kinto_settlement_amounts_v1(entry.total_price,entry.delivery_fee,entry.delivery_payment_type,'legacy_goods');legacy_gross:=legacy_gross+a.gross;legacy_net:=legacy_net+a.net;
END IF;
END LOOP;
IF p_action='approve' THEN
IF n=0 OR jsonb_typeof(claim.order_ids) IS DISTINCT FROM 'array' OR n<>jsonb_array_length(claim.order_ids) THEN RAISE EXCEPTION 'SETTLEMENT_SNAPSHOT_MISMATCH'; END IF;
IF NOT coalesce((coalesce(claim.calculation_basis,'collection')='collection' AND abs(claim.gross_amount-gross)<=0.00000001 AND abs(claim.delivery_fee-fee)<=0.00000001 AND abs(claim.net_amount-net)<=0.00000001)
OR (claim.settlement_type='courier' AND (claim.calculation_basis IS NULL OR claim.calculation_basis='legacy_goods') AND abs(claim.gross_amount-legacy_gross)<=0.00000001 AND abs(claim.delivery_fee-fee)<=0.00000001 AND abs(claim.net_amount-legacy_net)<=0.00000001),false) THEN RAISE EXCEPTION 'SETTLEMENT_AMOUNT_MISMATCH'; END IF;
UPDATE public.orders SET settlement_status='settled' WHERE settlement_id=claim.id;
ELSE UPDATE public.orders SET settlement_id=NULL,settlement_status='unsettled' WHERE settlement_id=claim.id;
END IF;
UPDATE public.settlements SET status=CASE WHEN p_action='approve' THEN 'approved' ELSE 'rejected' END,approved_by=actor->>'id',approved_at=now() WHERE id=claim.id;
RETURN jsonb_build_object('ok',true,'id',claim.id,'action',p_action,'order_count',n);
END $function$

CREATE OR REPLACE FUNCTION public.kinto_cash_settle_courier_session_v1(p_role text, p_session_token text, p_courier_id text, p_order_ids uuid[], p_notes text DEFAULT ''::text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor jsonb; courier public.couriers%rowtype; entry public.orders%rowtype; locked jsonb:='[]'; bucket record; result jsonb:='[]'; n integer:=0; agent uuid; bid text; bname text; sid uuid;
BEGIN
actor:=private.kinto_settlement_actor_v1(p_role,p_session_token);
SELECT * INTO courier FROM public.couriers WHERE id::text=p_courier_id;
IF NOT FOUND THEN RAISE EXCEPTION 'SETTLEMENT_COURIER_NOT_FOUND'; END IF;
bid:=courier.branch_id::text;agent:=courier.courier_uuid;
IF agent IS NULL THEN RAISE EXCEPTION 'SETTLEMENT_COURIER_AGENT_ID_REQUIRED'; END IF;
IF p_role='branch' AND bid IS DISTINCT FROM actor->>'id' THEN RAISE EXCEPTION 'SETTLEMENT_BRANCH_DENIED'; END IF;
SELECT name INTO bname FROM public.branches WHERE id::text=bid;
IF coalesce(length(p_notes),0)>4000 OR coalesce(cardinality(p_order_ids),0) NOT BETWEEN 1 AND 10000 OR (SELECT count(DISTINCT x) FROM unnest(p_order_ids) x)<>cardinality(p_order_ids) THEN RAISE EXCEPTION 'SETTLEMENT_REQUEST_INVALID'; END IF;
FOR entry IN SELECT * FROM public.orders WHERE id=ANY(p_order_ids) ORDER BY id FOR UPDATE LOOP
IF entry.branch_id IS DISTINCT FROM bid OR entry.status IS DISTINCT FROM 'تم التسليم' OR coalesce(entry.is_settled,false)
OR NOT (coalesce(entry.courier_id=p_courier_id,false) OR coalesce(entry.delivery_agent_id=agent,false)) THEN RAISE EXCEPTION 'SETTLEMENT_ORDER_NOT_ELIGIBLE'; END IF;
IF entry.total_price::text IN ('NaN','Infinity','-Infinity') OR entry.delivery_fee::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'SETTLEMENT_AMOUNT_INVALID'; END IF;
locked:=locked||jsonb_build_array(to_jsonb(entry));n:=n+1;
END LOOP;
IF n<>cardinality(p_order_ids) THEN RAISE EXCEPTION 'SETTLEMENT_ORDER_NOT_FOUND'; END IF;
FOR bucket IN SELECT coalesce(nullif(r->>'currency',''),'$') currency,sum(a.gross) gross,sum(a.fee) fee,sum(a.net) net,array_agg((r->>'id')::uuid ORDER BY r->>'id') ids FROM jsonb_array_elements(locked) r
CROSS JOIN LATERAL private.kinto_settlement_amounts_v1((r->>'total_price')::numeric,(r->>'delivery_fee')::numeric,r->>'delivery_payment_type','delivery_report') a GROUP BY 1 ORDER BY 1 LOOP
INSERT INTO public.delivery_settlements(settlement_code,delivery_agent_id,branch_id,total_collected_amount,total_delivery_fees,net_submitted_amount,orders_count,currency,order_ids,notes,settled_by_type,settled_by_id,courier_id,courier_name,branch_name)
VALUES('DS-'||replace(gen_random_uuid()::text,'-',''),agent,bid::uuid,bucket.gross,bucket.fee,bucket.net,cardinality(bucket.ids),bucket.currency,to_jsonb(bucket.ids),p_notes,p_role,actor->>'id',p_courier_id,courier.name,bname) RETURNING id INTO sid;
UPDATE public.orders SET is_settled=true WHERE id=ANY(bucket.ids);
result:=result||jsonb_build_array(jsonb_build_object('id',sid,'currency',bucket.currency,'order_count',cardinality(bucket.ids)));
END LOOP;
RETURN jsonb_build_object('ok',true,'created',jsonb_array_length(result),'settlements',result,'order_count',n);
END $function$

CREATE OR REPLACE FUNCTION private.kinto_order_settlement_guard_v1()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog'
AS $function$
BEGIN
IF current_user NOT IN ('anon','authenticated') THEN
IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END IF;
IF TG_OP='INSERT' THEN
IF NEW.settlement_id IS NOT NULL OR coalesce(NEW.is_settled,false) OR coalesce(NEW.settlement_status,'unsettled') NOT IN ('','unsettled') THEN RAISE EXCEPTION 'SETTLEMENT_SESSION_RPC_REQUIRED' USING ERRCODE='42501'; END IF;
ELSIF TG_OP='DELETE' THEN
IF OLD.settlement_id IS NOT NULL OR coalesce(OLD.is_settled,false) THEN RAISE EXCEPTION 'SETTLED_ORDER_DELETE_DENIED' USING ERRCODE='42501'; END IF;
RETURN OLD;
ELSE
IF NEW.settlement_id IS DISTINCT FROM OLD.settlement_id OR NEW.settlement_status IS DISTINCT FROM OLD.settlement_status OR NEW.is_settled IS DISTINCT FROM OLD.is_settled THEN RAISE EXCEPTION 'SETTLEMENT_SESSION_RPC_REQUIRED' USING ERRCODE='42501'; END IF;
IF (OLD.settlement_id IS NOT NULL OR coalesce(OLD.is_settled,false)) AND
(NEW.total_price IS DISTINCT FROM OLD.total_price OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee OR NEW.delivery_payment_type IS DISTINCT FROM OLD.delivery_payment_type OR NEW.branch_id IS DISTINCT FROM OLD.branch_id OR NEW.courier_id IS DISTINCT FROM OLD.courier_id OR NEW.delivery_agent_id IS DISTINCT FROM OLD.delivery_agent_id) THEN RAISE EXCEPTION 'SETTLED_ORDER_FINANCE_LOCKED' USING ERRCODE='42501'; END IF;
END IF;
RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.kinto_check_order_assignment_v1(actor jsonb, old_row orders, new_row orders)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE permissions jsonb:=actor->'permissions';
BEGIN
IF old_row.branch_id IS NOT DISTINCT FROM new_row.branch_id AND old_row.courier_id IS NOT DISTINCT FROM new_row.courier_id
AND old_row.delivery_agent_id IS NOT DISTINCT FROM new_row.delivery_agent_id THEN RETURN; END IF;
IF jsonb_typeof(permissions)='string' THEN permissions:=(permissions#>>'{}')::jsonb; END IF;
IF actor->>'role'='employee' AND (permissions->'branches'='false'::jsonb OR permissions->'manage_branches'='false'::jsonb
OR permissions->'orders'='false'::jsonb OR permissions->'manage_orders'='false'::jsonb) THEN RAISE EXCEPTION 'ORDER_ASSIGNMENT_PERMISSION_DENIED' USING ERRCODE='42501'; END IF;
IF old_row.settlement_id IS NOT NULL OR coalesce(old_row.is_settled,false) THEN RAISE EXCEPTION 'ORDER_ASSIGNMENT_SETTLED' USING ERRCODE='42501'; END IF;
IF new_row.branch_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.branches b WHERE b.id::text=new_row.branch_id) THEN RAISE EXCEPTION 'ORDER_ASSIGNMENT_BRANCH_INVALID'; END IF;
IF new_row.courier_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.couriers c WHERE c.id::text=new_row.courier_id AND coalesce(c.is_active,true)
AND (new_row.branch_id IS NULL OR c.branch_id=new_row.branch_id) AND (new_row.delivery_agent_id IS NULL OR c.courier_uuid=new_row.delivery_agent_id)) THEN RAISE EXCEPTION 'ORDER_ASSIGNMENT_COURIER_INVALID'; END IF;
IF new_row.delivery_agent_id IS NOT NULL AND NOT EXISTS(SELECT FROM public.couriers c WHERE c.courier_uuid=new_row.delivery_agent_id AND coalesce(c.is_active,true)
AND (new_row.branch_id IS NULL OR c.branch_id=new_row.branch_id)) THEN RAISE EXCEPTION 'ORDER_ASSIGNMENT_AGENT_INVALID'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.kinto_checkout_session_v1(p_session_token text, p_customer_shipping jsonb, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE cid uuid:=private.require_customer_review_session(p_session_token); c jsonb;
BEGIN
SELECT to_jsonb(x) INTO c FROM public.customers x WHERE id=cid;
IF c IS NULL OR lower(coalesce(c->>'status','active')) IN ('disabled','inactive','blocked','suspended','معطل','موقوف')
OR lower(coalesce(c->>'is_active','true'))='false' THEN RAISE EXCEPTION 'CHECKOUT_CUSTOMER_DISABLED' USING ERRCODE='42501'; END IF;
